NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Genesis'

CHAPTERS = {
    1: {
        1: 'Am Anfang schuf Gott den Himmel und die Erde.',
        2: 'Und die Erde war eine Leere und Öde, und Finsternis war auf den Angesichten des Abgrunds; und der Geist Gottes schwebte über den Wassern.',
        3: 'Und Gott sprach: Es werde Licht, und es ward Licht.',
        4: 'Und Gott sah das Licht, daß es gut war, und Gott schied zwischen dem Licht und zwischen der Finsternis.',
        5: 'Und Gott nannte das Licht Tag und die Finsternis nannte Er Nacht; und es war Abend und es war Morgen, der erste Tag.',
        6: 'Und Gott sprach: Es sei eine Ausbreitung inmitten der Wasser und scheide zwischen den Wassern für die Wasser.',
        7: 'Und Gott machte die Ausbreitung und schied zwischen den Wassern die unter der Ausbreitung und den Wassern die über der Ausbreitung waren, und ward also.',
        8: 'Und Gott nannte die Ausbreitung Himmel; und es war Abend und es war Morgen der zweite Tag.',
        9: 'Und Gott sprach: Die Wasser unter dem Himmel sammeln sich an einen Ort, und das Trockene erscheine. Und es ward also.',
        10: 'Und Gott nannte das Trockene Erde, und die Sammlung der Wasser nannte Er Meer. Und Gott sah, daß es gut war.',
        11: 'Und Gott sprach: Die Erde lasse hervorkeimen das junge Grün, das Kraut, das Samen säet, den Fruchtbaum, der Frucht trägt nach seiner Art, worin sein Samen ist auf der Erde. Und es ward also.',
        12: 'Und die Erde brachte hervor das junge Grün, das Kraut, das Samen säet nach seiner Art, und den Baum, der Frucht trägt worin sein Samen ist nach seiner Art. Und Gott sah, daß es gut war.',
        13: 'Und es war Abend und es war Morgen, der dritte Tag.',
        14: 'Und Gott sprach: Es seien Lichter an der Ausbreitung des Himmels, zu scheiden zwischen dem Tag und zwischen der Nacht, und sollen sein zu Zeichen und zu bestimmten Zeiten, und zu Tagen und Jahren;',
        15: 'Und sie seien zu Lichtern an der Ausbreitung des Himmels, zu leuchten auf der Erde. Und es ward also.',
        16: 'Und Gott machte die zwei großen Lichter, das große Licht am Tag zu herrschen, und das kleine Licht bei Nacht zu herrschen, und die Sterne.',
        17: 'Und Gott gab sie an die Ausbreitung des Himmels, zu leuchten auf der Erde,',
        18: 'Und zu herrschen am Tage und bei Nacht, und zu scheiden zwischen dem Licht und zwischen der Finsternis. Und Gott sah, daß es gut war.',
        19: 'Und es war Abend und es war Morgen, der vierte Tag.',
        20: 'Und Gott sprach: Es wimmle das Wasser vom Gewimmel, von der lebendigen Seele und das Gevögel fliege über der Erde, über die Angesichte der Ausbreitung der Himmel.',
        21: 'Und Gott schuf die großen Walfische, und jede lebendige Seele, die da kriecht, wovon die Wasser wimmeln, nach ihrer Art, und alles Gevögel, das da Flügel hat, nach seiner Art. Und Gott sah, daß es gut war.',
        22: 'Und Gott segnete sie und sprach: Seid fruchtbar und mehret euch und füllet die Wasser in den Meeren, und das Gevögel mehre sich auf Erden.',
        23: 'Und es war Abend und es war Morgen, der fünfte Tag.',
        24: 'Und Gott sprach: Die Erde bringe hervor die lebendige Seele nach ihrer Art, Vieh und Kriechtier und das wilde Tier der Erde nach seiner Art. Und es ward also.',
        25: 'Und Gott machte das wilde Tier der Erde nach seiner Art, und das Vieh nach seiner Art und alles Kriechtier auf dem Erdboden nach seiner Art. Und Gott sah, daß es gut war.',
        26: 'Und Gott sprach: Lasset uns den Menschen machen in unser Bild, nach unserer Ähnlichkeit, und laßt sie beherrschen die Fische des Meeres und das Gevögel der Himmel und das Vieh und die ganze Erde und alles Kriechtier, das auf der Erde kriecht.',
        27: 'Und Gott schuf den Menschen in Sein Bild, in das Bild Gottes schuf Er ihn, männlich und weiblich schuf Er sie.',
        28: 'Und Gott segnete sie, und Gott sprach zu ihnen: Seid fruchtbar und mehret euch und füllet die Erde und machet sie euch untertan und beherrschet den Fisch des Meeres und das Gevögel der Himmel und alles wilde Tier, das auf der Erde kriecht.',
        29: 'Und Gott sprach: Siehe, Ich gebe euch alles Kraut, das Samen säet, auf den Angesichten der ganzen Erde, und jeglichen Baum, an dem Frucht ist; der Baum, der die Samen säet, sei euch zur Speise.',
        30: 'Und allem Getier der Erde und allem Gevögel des Himmels, und allem, das auf Erden kriecht, in dem eine lebendige Seele ist, gebe Ich alles grüne Kraut zur Speise. Und es ward so.',
        31: 'Und Gott sah alles, was Er gemacht hatte, und siehe, es war sehr gut. Und es war Abend und es war Morgen, der sechste Tag.',
    },
    2: {
        1: 'Und es wurden vollendet die Himmel und die Erde und all ihr Heer.',
        2: 'Und Gott vollendete am siebenten Tage Sein Werk, das Er gemacht, und feierte am siebenten Tag von all Seinem Werke, das Er gemacht.',
        3: 'Und Gott segnete den siebenten Tag und heiligte ihn, weil Er an ihm feierte von all Seinem Werk, das Gott geschaffen es zu machen.',
        4: 'Dies sind die Zeugungen der Himmel und der Erde. Als Er sie schuf am Tage, da Jehovah Gott Erde und Himmel machte,',
        5: 'Und kein Gesträuch des Feldes war noch auf Erden, und kein Kraut des Feldes sproßte noch, denn Jehovah Gott hatte noch nicht auf Erden regnen lassen, und noch war kein Mensch da, den Boden zu bebauen.',
        6: 'Und Er ließ einen Dunst aufgehen von der Erde und bewässerte alle Angesichte des Bodens.',
        7: 'Und Jehovah Gott bildete den Menschen, Staub vom Boden und blies ihm des Lebens Odem in die Nase; und der Mensch ward zur lebendigen Seele.',
        8: 'Und Jehovah Gott pflanzte in Eden vom Osten einen Garten und setzte darein den Menschen, den Er gebildet hatte.',
        9: 'Und Jehovah Gott ließ aus dem Boden sprossen allerlei Bäume lustig anzusehen und gut zur Speise; und den Baum der Leben in der Mitte des Gartens und den Baum der Erkenntnis des Guten und des Bösen.',
        10: 'Und von Eden ging aus ein Fluß, den Garten zu bewässern, und von da trennte er sich und ward zu vier Hauptwassern.',
        11: 'Der Name des einen ist Pischon, der umgibt das ganze Land Chavilah, wo Gold ist.',
        12: 'Und das Gold desselbigen Landes ist gut. Daselbst ist Bdellium und der Stein Onyx.',
        13: 'Und der Name des zweiten Flusses ist Gichon. Der umgibt das ganze Land Kusch.',
        14: 'Und der Name des dritten Flusses ist Hiddekel. Der geht östlich nach Aschur; und der vierte Fluß der ist der Phrath.',
        15: 'Und Jehovah Gott nahm den Menschen und setzte ihn nieder in dem Garten Eden, ihn zu bebauen und ihn zu hüten.',
        16: 'Und Jehovah Gott gebot über ihn dem Menschen und sprach: Von jeglichem Baume im Garten darfst du essen.',
        17: 'Aber vom Baume der Erkenntnis des Guten und des Bösen, von dem sollst du nicht essen; denn welches Tages du davon issest, wirst du des Todes sterben.',
        18: 'Und Jehovah Gott sprach: Es ist nicht gut, daß der Mensch allein sei, Ich will ihm einen Beistand machen der wie bei ihm sei.',
        19: 'Und Jehovah Gott bildete aus dem Boden jegliches Getier des Feldes und alles Gevögel der Himmel und brachte sie zum Menschen, auf daß Er sähe, wie er sie nennete; und alles, was sie der Mensch nennete, die lebendige Seele, das war dessen Name.',
        20: 'Und der Mensch nannte mit Namen alles Vieh und das Gevögel der Himmel und alles Wild des Feldes, aber für den Menschen fand Er keinen Beistand, der wie bei ihm wäre.',
        21: 'Und Jehovah Gott ließ einen tiefen Schlaf auf den Menschen fallen, daß er schlief, und Er nahm eine von seinen Rippen und schloß Fleisch zu an deren Stelle.',
        22: 'Und Jehovah baute die Rippe, die Er vom Menschen genommen hatte, zu einem Weibe, und brachte sie zu dem Menschen.',
        23: 'Und der Mensch sprach: Das ist einmal Bein von meinen Beinen, und Fleisch von meinem Fleisch. Sie soll Männin heißen; denn vom Manne ist sie genommen.',
        24: 'Darum wird der Mann seinen Vater und seine Mutter verlassen und seinem Weibe anhangen, und sie werden ein Fleisch sein.',
        25: 'Und sie waren beide nackt, der Mensch und sein Weib, und schämten sich nicht.',
    },
    3: {
        1: 'Und die Schlange war listiger als alles Wild des Feldes, das Jehovah Gott gemacht hatte, und sprach zu dem Weibe: Hat denn Gott auch gesagt: Esset nicht von jedem Baume des Gartens?',
        2: 'Und das Weib sprach zur Schlange: Von der Frucht des Baumes des Gartens dürfen wir essen;',
        3: 'Aber von der Frucht des Baumes, der in der Mitte des Gartens ist, sprach Gott, ihr sollt nicht von ihr essen und sie nicht berühren, auf daß ihr nicht sterbet.',
        4: 'Und die Schlange sprach zum Weibe: Ihr werdet nicht des Todes sterben;',
        5: 'Denn Gott weiß, daß welches Tages ihr davon esset, eure Augen sich auftun, und ihr seid wie Gott und wisset was Gutes und Böses.',
        6: 'Und das Weib sah, daß der Baum gut zu essen und daß er ein Gelüste für die Augen und begehrenswert sei, klug zu machen. Und sie nahm von seiner Frucht und aß, und gab auch ihrem Manne bei ihr, und er aß.',
        7: 'Und beider Augen wurden aufgetan und sie erkannten, daß sie nackt wären, und sie hefteten Feigenblätter zusammen und machten sich Schürzen.',
        8: 'Und sie hörten die Stimme Jehovah Gottes, im Garten sich ergehend in der Kühlung des Tages, und der Mann und sein Weib versteckten sich vor dem Angesichte Jehovah Gottes inmitten des Baumes des Gartens.',
        9: 'Und Jehovah Gott rief dem Menschen zu und sprach zu ihm: Wo bist du?',
        10: 'Und er sprach: Ich hörte Deine Stimme im Garten und fürchtete mich, weil ich nackt bin, und versteckte mich.',
        11: 'Und Er sprach: Wer sagte dir an, daß du nackt seiest? Hast du von dem Baume gegessen, von dem Ich dir gebot nicht zu essen?',
        12: 'Und der Mensch sprach: Das Weib, daß Du mir beigegeben hast, die gab mir von dem Baume, und ich aß.',
        13: 'Und Jehovah Gott sprach zu dem Weibe: Warum hast du das getan? Und das Weib sprach: Die Schlange hat mich verführt und ich aß.',
        14: 'Und Jehovah Gott sprach zu der Schlange: Weil du das getan hast, bist du verflucht vor allem Vieh und vor allem Wild des Feldes. Auf deinem Bauche sollst du gehen und Staub essen alle Tage deines Lebens.',
        15: 'Und Feindschaft will Ich setzen zwischen dir und zwischen dem Weibe, und zwischen deinem Samen und zwischen ihrem Samen. Er soll dir den Kopf zertreten und du wirst ihm die Verse verletzen.',
        16: 'Zum Weibe sprach Er: Deine Schmerzen will Ich dir vielfach vermehren und deine Empfängnis. Mit Schmerzen sollst du Söhne gebären. Nach deinem Manne sollst du verlangen und er soll herrschen über dich.',
        17: 'Und zum Menschen sprach Er: Weil du auf die Stimme deines Weibes gehört, und von dem Baume gegessen hast, von dem Ich dir geboten und gesagt: du sollst nicht davon essen! ist verflucht der Boden wegen deiner. Mit Schmerzen sollst du davon essen alle Tage deines Lebens.',
        18: 'Und Dorn und Distel läßt er dir sprossen und das Kraut des Feldes sollst du essen.',
        19: 'Im Schweiß deines Antlitzes sollst du Brot essen, bis du zurück zum Boden kehrst, weil von ihm du genommen bist; denn Staub bist du, und zum Staube kehrst du zurück.',
        20: 'Und der Mensch nannte den Namen seines Weibes Chavah darum daß sie die Mutter alles Lebendigen ist.',
        21: 'Und Jehovah Gott machte dem Menschen und seinem Weibe Röcke von Fell und zog sie ihnen an.',
        22: 'Und Jehovah Gott sprach: Siehe, der Mensch war wie einer von Uns, wissend Gutes und Böses; und nun, daß er nicht seine Hand ausstrecke und nehme auch vom Baume des Lebens und esse und lebe ewiglich.',
        23: 'Und Jehovah Gott sandte ihn fort aus dem Garten Eden, den Boden zu bebauen, aus dem er genommen war.',
        24: 'Und Er trieb den Menschen fort, und ließ vom Osten an dem Garten Eden die Cherube wohnen und die Flamme des sich wendenden Schwertes, um den Weg zum Baume des Lebens zu hüten.',
    },
    4: {
        1: 'Und der Mensch erkannte sein Weib Chavah und sie empfing und gebar Kain, und sprach: Ich habe einen Mann erworben, den Jehovah.',
        2: 'Und sie fuhr fort und gebar seinen Bruder Habel; und Habel ward ein Hirte des Kleinviehs, und Kain war ein Bebauer des Bodens.',
        3: 'Und es geschah am Ende der Tage, daß Kain von der Frucht des Bodens Jehovah ein Opfer brachte.',
        4: 'Und auch Habel brachte dar von den Erstlingen seines Kleinviehs und von ihrem Fette; und Jehovah schaute hin auf Habel und auf sein Opfer,',
        5: 'Aber auf Kain und sein Opfer schaute Er nicht hin. Und Kain entbrannte sehr und sein Angesicht senkte sich.',
        6: 'Und Jehovah sprach zu Kain: Warum entbrennst du, und warum senkt sich dein Angesicht?',
        7: 'Ist es nicht also? Wenn du Gutes tust so ist Erhebung. Wenn du aber nicht Gutes tust, lagert die Sünde vor der Tür, und verlanget nach dir aber du sollst darüber herrschen.',
        8: 'Und Kain sprach mit seinem Bruder Habel. Und es geschah, als sie auf dem Felde waren, daß Kain wider seinen Bruder Habel aufstand und ihn erwürgete.',
        9: 'Und Jehovah sprach zu Kain: Wo ist dein Bruder Habel? Und er sprach: Ich weiß es nicht. Bin ich meines Bruders Hüter?',
        10: 'Und Er sprach: Was hast du getan? Die Stimme von deines Bruders Blut schreit zu Mir von dem Boden.',
        11: 'Und nun - verflucht seist du von dem Boden der seinen Mund hat aufgesperrt, um das Blut deines Bruders von deiner Hand zu nehmen.',
        12: 'Wenn du den Boden bebaust gibt er dir seine Kraft nicht mehr. Du wirst umherwandern und flüchtig sein auf Erden!',
        13: 'Und Kain sprach zu Jehovah: Zu groß ist meine Missetat, als daß sie könnte weggenommen werden.',
        14: 'Siehe! Du treibst mich heute von diesem Boden fort, und vor Deinem Angesichte muß ich mich verbergen, und wandern und flüchtig sein auf Erden. Und wird geschehen, daß jeder, der mich findet, mich erwürgt.',
        15: 'Aber Jehovah sprach zu ihm: Fürwahr, wer Kain erwürgt, das soll siebenfach gerächt werden. Und Jehovah setzte ein Zeichen an Kain, auf daß wer ihn fände, ihn nicht erschlüge.',
        16: 'Und Kain ging hinaus vom Angesicht Jehovahs und wohnte im Lande Nod im Osten von Eden.',
        17: 'Und Kain erkannte sein Weib, und sie empfing und gebar Chanoch. Und er baute eine Stadt, und nannte den Namen der Stadt nach dem Namen seines Sohnes Chanoch.',
        18: 'Und dem Chanoch ward Irad geboren, und Irad zeugte Mechujael, und Mechujael zeugte den Methuschael, und Methuschael, zeugte den Lamech.',
        19: 'Und Lamech nahm sich zwei Weiber. Der Name der einen war Adah, und der Name der zweiten Zillah.',
        20: 'Und Adah gebar Jabal. Dieser war der Vater derer, die in Zelten und bei Viehherden wohnen.',
        21: 'Und seines Bruders Name war Jubal. Er ward der Vater aller so die Harfe und die Flöte handhaben.',
        22: 'Und Zillah, auch sie gebar, den Tubalkain, den Meister aller Werkleute in Erz und Eisen, und Tubalkains Schwester war Naamah.',
        23: 'Und Lamech sprach zu seinen Weibern Adah und Zillah: Höret meine Stimme, ihr Weiber Lamechs und nehmet zu Ohren meine Rede. Einen Mann habe ich erwürget zu meiner Wunde und ein Kind zu meiner Strieme,',
        24: 'Wenn Kain siebenfach gerächt wird, so wird es Lamech siebenundsiebzigmal.',
        25: 'Und der Mensch erkannte abermals sein Weib und sie gebar einen Sohn, und sie nannte seinen Namen Scheth; denn Gott hat mir andern Samen gesetzt für Habel, dafür daß Kain ihn erwürget hat.',
        26: 'Und auch dem Scheth ward ein Sohn geboren und er nannte seinen Namen Enosch. Damals fing man an, den Namen Jehovahs anzurufen.',
    },
    5: {
        1: 'Dies ist das Buch der Zeugungen Adams, am Tage, da Gott den Menschen schuf. In die Ähnlichkeit Gottes machte Er ihn.',
        2: 'Männlich und weiblich schuf Er sie, und Er segnete sie und nannte ihren Namen Mensch, am Tage da sie geschaffen wurden.',
        3: 'Und der Mensch lebte hundertdreißig Jahre, und er zeugte in seine Ähnlichkeit nach seinem Bilde, und nannte seinen Namen Scheth.',
        4: 'Und der Tage des Menschen nachdem er Scheth gezeugt, waren achthundert Jahre, und er zeugte Söhne und Töchter.',
        5: 'Und es waren all die Tage des Menschen, die er lebte, neunhundert Jahre und dreißig Jahre und er starb.',
        6: 'Und Scheth lebte fünf Jahre und hundert Jahre, und er zeugte Enosch.',
        7: 'Und Scheth lebte, nachdem er Enosch gezeugt, sieben Jahre und achthundert Jahre und zeugte Söhne und Töchter.',
        8: 'Und alle Tage Scheths waren zwölf Jahre und neunhundert Jahre, und er starb.',
        9: 'Und Enosch lebte neunzig Jahre und zeugte Kenan.',
        10: 'Und Enosch lebte, nachdem er Kenan gezeugt, fünfzehn Jahre und achthundert Jahre und er zeugte Söhne und Töchter.',
        11: 'Und alle Tage Enoschs waren fünf Jahre und neunhundert Jahre, und er starb.',
        12: 'Und Kenan lebte siebzig Jahre und zeugte Mahalaleel.',
        13: 'Und Kenan lebte, nachdem er Mahalaleel gezeugt, vierzig Jahre und achthundert Jahre und er zeugte Söhne und Töchter.',
        14: 'Und alle Tage Kenans waren zehn Jahre und neunhundert Jahre; und er starb.',
        15: 'Und Mahalaleel lebte fünf Jahre und sechzig Jahre und zeugte Jared.',
        16: 'Und Mahalaleel lebte, nachdem er Jared gezeugt hatte, dreißig Jahre und achthundert Jahre und er zeugte Söhne und Töchter.',
        17: 'Und alle Tage Mahalaleels waren fünfundneunzig Jahre und achthundert Jahre, und er starb.',
        18: 'Und Jared lebte zweiundsechzig Jahre und hundert Jahre und zeugte Chanoch.',
        19: 'Und Jared lebte, nachdem er Chanoch gezeugt, achthundert Jahre und er zeugte Söhne und Töchter.',
        20: 'Und alle Tage Jareds waren zweiundsechzig Jahre und neunhundert Jahre und er starb.',
        21: 'Und Chanoch lebte fünfundsechzig Jahre und zeugte Methuschelach.',
        22: 'Und Chanoch erging sich mit Gott, nachdem er den Methuschelach gezeugt hatte, dreihundert Jahre und er zeugte Söhne und Töchter.',
        23: 'Und alle Tage Chanochs waren fünfundsechzig Jahre und dreihundert Jahre.',
        24: 'Und Chanoch erging sich mit Gott, und er war nicht; denn Gott hatte ihn hinweggenommen.',
        25: 'Und Methuschelach lebte siebenundachtzig Jahre und hundert Jahre und zeugte Lamech.',
        26: 'Und Methuschelach lebte, nachdem er Lamech gezeugt, zweiundachtzig Jahre und siebenhundert Jahre, und zeugte Söhne und Töchter.',
        27: 'Und alle Tage Methuschelachs waren neunundsechzig Jahre und neunhundert Jahre und er starb.',
        28: 'Und Lamech lebte zweiundachtzig Jahre und hundert Jahre und zeugte einen Sohn.',
        29: 'Und er nannte seinen Namen Noach, sagend: der wird uns trösten ob unserem Tun und ob den Schmerzen unserer Hände vom Boden, den Jehovah verflucht hat.',
        30: 'Und Lamech lebte, nachdem er Noach gezeugt hatte, fünfundneunzig Jahre und fünfhundert Jahre, und er zeugte Söhne und Töchter.',
        31: 'Und es waren alle Tage Lamechs siebenundsiebzig Jahre und siebenhundert Jahre, und er starb.',
        32: 'Und Noach war fünfhundert Jahre alt, und Noach zeugte Schem, Cham und Japheth.',
    },
    6: {
        1: 'Und es geschah, daß der Mensch anfing sich zu mehren auf dem Angesichte des Bodens und Töchter ihnen geboren wurden.',
        2: 'Und die Söhne Gottes sahen die Töchter des Menschen, daß sie gut wären und nahmen sich Weiber von allen, die sie erwählten.',
        3: 'Und Jehovah sprach: Mein Geist wird nicht ewiglich rechten mit dem Menschen; denn er ist Fleisch, und seine Tage werden sein hundertzwanzig Jahre!',
        4: 'In denselben Tagen waren die Nephilim auf der Erde, und auch nachher, da die Söhne Gottes zu den Töchtern des Menschen eingingen, und diese ihnen gebaren. Dieselben wurden die Mächtigen von Alters her, Männer von Namen.',
        5: 'Und Jehovah sah, daß des Bösen des Menschen viel ward auf Erden, und daß alles Bilden der Gedanken seines Herzens nur böse war den ganzen Tag.',
        6: 'Und es reuete Jehovah, daß Er den Menschen auf Erden gemacht, und es schmerzte Ihn in Seinem Herzen.',
        7: 'Und Jehovah sprach: Ich will vertilgen den Menschen, den Ich geschaffen, von dem Boden vom Menschen bis zum Vieh, bis zum Kriechtier, und bis zum Gevögel der Himmel; denn es reuet Mich, daß Ich sie machte.',
        8: 'Aber Noach fand Gnade in den Augen Jehovahs.',
        9: 'Dies sind die Geburten Noachs. Noach war ein gerechter Mann und untadelig in seinen Geschlechtern. Noach erging sich mit Gott.',
        10: 'Und Noach zeugte drei Söhne: Schem, Cham und Japheth.',
        11: 'Und die Erde war verdorben vor Gott; und die Erde war erfüllt mit Gewalttat.',
        12: 'Und Gott sah die Erde, und siehe, sie war verdorben; weil alles Fleisch seinen Weg verderbt hatte auf Erden.',
        13: 'Und Gott sprach zu Noach: Das Ende alles Fleisches ist vor Mich gekommen; denn die Erde ist erfüllt mit Gewalttat vor ihrem Angesicht; und siehe Ich will sie verderben mit der Erde.',
        14: 'Mache dir eine Arche von Gopherholz. Mit Kammern mache die Arche und verpiche sie von innen und außen mit Pech.',
        15: 'Und also sollst du sie machen: Dreihundert Ellen sei die Länge der Arche, fünfzig Ellen ihre Breite und dreißig Ellen ihre Höhe.',
        16: 'Ein Fenster sollst du machen der Arche und es oben vollenden bis zu einer Elle; und den Eingang der Arche sollst du an die Seite setzen. Ein unterstes, zweites und drittes Stockwerk sollst du machen.',
        17: 'Und Ich, siehe, Ich bringe die Flut von Wassern über die Erde, zu verderben alles Fleisch unter den Himmeln, in dem der Geist des Lebens ist. Alles, was auf Erden ist, soll verscheiden.',
        18: 'Aber mit dir will Ich einen Bund aufrichten. Und du sollst in die Arche eingehen, du und deine Söhne und dein Weib und deiner Söhne Weiber mit dir.',
        19: 'Und von allem Lebendigen, von allem Fleische sollst du je zwei von allem in die Arche einbringen, auf daß sie mit dir am Leben bleiben, ein Männliches und ein Weibliches sollen sie sein.',
        20: 'Von dem Gevögel nach seiner Art, und vom Vieh nach seiner Art, von allem Kriechtier des Bodens nach seiner Art, sollen je zwei von allen zu dir hereinkommen, auf daß sie am Leben bleiben.',
        21: 'Und du, nimm dir von jeglicher Speise, die gegessen wird, und sammle sie dir, auf daß sie dir und ihnen zur Speise seien.',
        22: 'Und Noach tat es. Nach allem, wie ihm Gott geboten hatte, so tat er.',
    },
    7: {
        1: 'Und Jehovah sprach zu Noach: Gehe ein, du und all dein Haus, zur Arche; denn dich habe Ich gerecht vor Mir gesehen in diesem Geschlechte.',
        2: 'Von allem reinen Vieh nimm dir sieben und sieben, ein Männchen und sein Weibchen, und von dem Vieh, das nicht rein ist, je zwei, ein Männchen und sein Weibchen.',
        3: 'Auch von dem Gevögel der Himmel sieben und sieben, ein Männliches und ein Weibliches, auf daß Samen auf der ganzen Erde erhalten werde.',
        4: 'Denn in noch sieben Tagen lasse Ich regnen auf Erden vierzig Tage und vierzig Nächte, und vertilge jegliches Geschöpf, das Ich gemacht, von dem Boden.',
        5: 'Und Noach tat nach allem, das Jehovah geboten hatte.',
        6: 'Und Noach war sechshundert Jahre alt und die Flut der Wasser war auf der Erde.',
        7: 'Und Noach und seine Söhne und sein Weib und die Weiber seiner Söhne mit ihm gingen ein in die Arche vor den Wassern der Flut.',
        8: 'Von dem reinen Vieh und von dem Vieh, das nicht rein war, und von dem Gevögel und von allem, das auf dem Boden kreucht,',
        9: 'Kamen sie hinein zwei und zwei zu Noach zur Arche, ein Männliches und ein Weibliches, wie Gott dem Noach geboten hatte.',
        10: 'Und es geschah, daß in sieben Tagen die Wasser der Flut auf der Erde waren.',
        11: 'Im sechshundersten Jahre des Lebens Noachs im zweiten Monat, am siebzehnten Tage des Monats, an diesem Tage war es, daß alle Brunnquellen des großen Abgrundes sich zerspalteten, und alle Fenster des Himmels geöffnet wurden.',
        12: 'Und vierzig Tage und vierzig Nächte war der Regen auf der Erde.',
        13: 'An diesem selbigen Tage ging Noach, und Schem und Cham und Japhet, die Söhne Noachs und Noachs Weib und die drei Weiber seiner Söhne mit ihnen ein in die Arche;',
        14: 'Sie, und alles Wild nach seiner Art, und alles Vieh nach seiner Art, und alles Kriechtier, das auf der Erde kriecht, nach seiner Art, und alles Gevögel nach seiner Art, jeder Vogel, alles Geflügelte.',
        15: 'Und sie gingen ein zu Noach zur Arche zwei und zwei, von allem Fleisch, in welchem der Geist des Lebens war.',
        16: 'Und die hineingingen, Männliche und Weibliche, von allem Fleisch gingen sie hinein, wie Gott ihm geboten hatte, und Jehovah schloß hinter ihm zu.',
        17: 'Und die Flut war vierzig Tage auf der Erde, und die Wasser mehrten sich und hoben die Arche auf und sie ward emporgehoben über die Erde.',
        18: 'Und es wurden mächtig die Wasser und mehrten sich sehr auf der Erde, und die Arche ging über die Wasser dahin.',
        19: 'Und die Wasser wurden sehr, sehr mächtig auf Erden, und es wurden alle hohe Berge unter dem ganzen Himmel bedeckt.',
        20: 'Fünfzehn Ellen darüber wurden die Wasser mächtig und sie bedeckten die Berge.',
        21: 'Und alles Fleisch verschied, das auf Erden kriecht, an Gevögel und an Vieh und an Wild und an allem Gewürm, das auf Erden wimmelt, und aller Mensch.',
        22: 'Alles, was den Odem des Geistes des Lebens in seiner Nase hatte von allem, das im Trocknen war, starb.',
        23: 'Und Er vertilgte jegliches Geschöpf, das auf dem Boden war, vom Menschen bis zum Vieh, zum Kriechtier, und zum Gevögel des Himmels; und sie wurden vertilgt von der Erde, und nur Noach verblieb, und was mit ihm in der Arche war.',
        24: 'Und die Wasser waren mächtig auf Erden hundertfünfzig Tage.',
    },
    8: {
        1: 'Und Gott gedachte Noachs und alles Wildes und alles Viehs, das mit ihm in der Arche war, und Gott ließ einen Wind hingehen über die Erde und die Wasser legten sich.',
        2: 'Und die Brunnquellen des Abgrundes und die Fenster des Himmels wurden verstopft, und dem Regen vom Himmel ward gewehrt.',
        3: 'Und die Wasser kehrten zurück von der Erde, sie gingen und kehrten zurück, und die Wasser verringerten sich am Ende von hundertfünfzig Tagen.',
        4: 'Und die Arche ruhte im siebenten Monat am siebzehnten Tage des Monats auf den Bergen Ararat.',
        5: 'Und die Wasser gingen und verringerten sich bis zum zehnten Monat. Am ersten des zehnten Monats wurden die Spitzen der Berge gesehen.',
        6: 'Und es geschah am Ende von vierzig Tagen, daß Noach öffnete das Fenster der Arche, das er gemacht hatte.',
        7: 'Und er sandte den Raben aus. Und er ging aus, ausgehend und zurückkehrend, bis die Wasser von der Erde vertrockneten.',
        8: 'Und er sandte die Taube von sich fort, um zu sehen, ob die Wasser auf dem Boden leichter wären.',
        9: 'Aber die Taube fand keine Ruhe für die Sohle ihres Fußes; und sie kehrte zu ihm zurück zur Arche; denn die Wasser waren auf dem Angesichte der ganzen Erde, und er streckte seine Hand aus und nahm sie und brachte sie herein zu sich in die Arche.',
        10: 'Und er wartete noch sieben andere Tage und sandte die Taube wieder aus der Arche.',
        11: 'Und die Taube kam herein zu ihm um die Abendzeit, und siehe, sie hatte ein abgepflücktes Blatt vom Ölbaum in ihrem Munde. Und Noach wußte, daß die Wasser auf der Erde leichter geworden.',
        12: 'Und er wartete noch sieben andere Tage und entsandte die Taube; und sie kam nicht abermals wieder zu ihm zurück.',
        13: 'Und es geschah im sechshundert und ersten Jahre, im Anfang, am ersten des Monats, waren die Wasser von der Erde aufgetrocknet. Und Noach nahm die Decke weg von der Arche, und sah, und siehe, die Angesichte des Bodens waren aufgetrocknet.',
        14: 'Und im zweiten Monat am siebenundzwanzigsten Tage des Monats ward die Erde trocken.',
        15: 'Und Gott redete zu Noach und sprach:',
        16: 'Geh aus von der Arche du und dein Weib, und deine Söhne und deiner Söhne Weiber mit dir.',
        17: 'Alles Wild, das mit dir ist, von allem Fleisch, an Gevögel und an Vieh, und an allem Kriechtiere, das kriecht auf der Erde, laß herausgehen mit dir, und laß sie wimmeln auf der Erde und fruchtbar sein und sich mehren auf der Erde.',
        18: 'Und Noach ging heraus, und seine Söhne und sein Weib und seiner Söhne Weiber mit ihm.',
        19: 'Alles Wild, alles Kriechtier und alles Gevögel, alles, was kriecht auf der Erde, nach ihren Familien gingen sie heraus aus der Arche.',
        20: 'Und Noach baute dem Jehovah einen Altar, und nahm von allem reinen Vieh und von allem reinen Gevögel und opferte Brandopfer auf auf dem Altare.',
        21: 'Und Jehovah roch den Geruch der Ruhe, und Jehovah sprach in Seinem Herzen: Ich will fortan dem Boden nicht mehr fluchen um des Menschen halben; denn das Gebilde des Menschen Herzens ist böse von seiner Jugend auf, und Ich will hinfort nicht mehr alles Lebendige schlagen, wie Ich getan habe.',
        22: 'Forthin, während aller Tage der Erde soll nimmermehr aufhören Samen und Ernte und Frost und Hitze und Sommer und Winter, und Tag und Nacht.',
    },
    9: {
        1: 'Und Gott segnete Noach und seine Söhne und sprach zu ihnen: Seid fruchtbar und mehret euch und füllet die Erde.',
        2: 'Und die Frucht vor euch und das Erschrecken vor euch sei über allem wilden Getier der Erde und über allem Gevögel des Himmels; über allem, was auf dem Boden kriecht, und über allen Fischen des Meeres; sie seien in eure Hände gegeben.',
        3: 'Alles Kriechtier, das Leben hat, soll eure Speise sein, wie das grüne Kraut habe Ich euch alles gegeben.',
        4: 'Nur Fleisch in seiner Seele, seinem Blut, sollt ihr nicht essen.',
        5: 'Und fürwahr, euer Blut will Ich von euern Seelen fordern, von der Hand alles wilden Tiers will Ich es fordern und von der Hand des Menschen, von der Hand des Mannes, seines Bruders, will Ich fordern die Seele des Menschen.',
        6: 'Wer das Blut des Menschen im Menschen vergießt, dessen Blut soll vergossen werden, weil im Bilde Gottes Er den Menschen gemacht hat.',
        7: 'Und ihr, seid fruchtbar und mehret euch, wimmelt auf der Erde und mehret euch auf ihr.',
        8: 'Und Gott sprach zu Noach und zu seinen Söhnen mit ihm, und sagte:',
        9: 'Und Ich, siehe, Ich richte Meinen Bund auf mit euch und mit eurem Samen nach euch.',
        10: 'Und mit aller lebendigen Seele, die bei euch ist, an Gevögel, an Vieh, und an allem wilden Tiere der Erde bei euch, von allen, die von der Arche ausgegangen, von allem wilden Tier der Erde.',
        11: 'Und Ich richte Meinen Bund auf mit euch, und es soll nicht mehr alles Fleisch von den Wassern der Flut ausgerottet werden, und es wird nicht mehr eine Flut sein, die Erde zu verderben.',
        12: 'Und Gott sprach: Dies sei das Zeichen des Bundes, den Ich zwischen Mir und zwischen euch und zwischen aller lebendigen Seele, die bei euch ist, für die Geschlechter des Zeitlaufs gebe.',
        13: 'Meinen Bogen gebe Ich in die Wolke, und er soll sein zum Zeichen des Bundes zwischen Mir und zwischen der Erde.',
        14: 'Und es wird geschehen, wenn Ich Wolken zusammenwölke über der Erde, und der Bogen in den Wolken gesehen wird;',
        15: 'So will Ich gedenken Meines Bundes zwischen Mir und zwischen euch und zwischen aller lebendigen Seele in allem Fleisch; und die Wasser sollen nicht mehr zur Flut werden, alles Fleisch zu verderben.',
        16: 'Und der Bogen wird in der Wolke sein, und Ich werde ihn sehen, zu gedenken des ewigen Bundes zwischen Gott und zwischen aller lebendigen Seele in allem Fleisch, das auf Erden ist.',
        17: 'Und Gott sprach zu Noach: Dies sei das Zeichen des Bundes, den Ich aufrichte zwischen Mir und zwischen allem Fleisch, das auf Erden ist.',
        18: 'Und die Söhne Noachs, die von der Arche ausgingen, waren Schem und Cham und Japhet; und Cham ist der Vater Kanaans.',
        19: 'Diese drei sind die Söhne Noachs und von ihnen ward die ganze Erde überstreut.',
        20: 'Und Noach fing an als Mann des Bodens und pflanzte einen Weinberg.',
        21: 'Und er trank von dem Wein und ward trunken und war aufgedeckt mitten in seinem Zelte.',
        22: 'Und Cham, der Vater Kanaans, sah die Blöße seines Vaters und sagte es seinen zweien Brüdern draußen an.',
        23: 'Und Schem und Japhet nahmen das Gewand und legten es auf ihre beiden Schultern und gingen rückwärts und bedeckten die Blöße ihres Vaters, und ihre Angesichter waren rückwärts, und die Blöße ihres Vaters sahen sie nicht.',
        24: 'Und Noach erwachte von seinem Weine, und er erfuhr, was ihm sein kleiner Sohn getan hatte,',
        25: 'Und er sprach: Verflucht sei Kanaan! Der Knecht der Knechte soll er seinen Brüdern sein.',
        26: 'Und er sprach: Gesegnet sei Jehovah, der Gott Schems und Kanaan soll ihm Knecht sein.',
        27: 'Weit breite Gott Japhet aus, und er soll wohnen in den Zelten Schems, und Kanaan soll ihm Knecht sein.',
        28: 'Und Noach lebte nach der Flut dreihundert Jahre und fünfzig Jahre.',
        29: 'Und es waren alle Tage Noachs neunhundert Jahre und fünfzig Jahre, und er starb.',
    },
    10: {
        1: 'Und dies sind die Zeugungen der Söhne Noachs: Schem, Cham und Japheth; und es wurden ihnen nach der Flut Söhne geboren.',
        2: 'Die Söhne Japheths sind Gomer und Magog und Madai und Javan und Thubal und Meschech und Thiras.',
        3: 'Und die Söhne Gomers: Aschkenas und Riphath und Thogarmah.',
        4: 'Und die Söhne Javans: Elischah und Tarschisch, Kitthim und Dodanim.',
        5: 'Von diesen trennten sich ab die Inseln der Völkerschaften in ihren Ländern, jede nach ihrer Zunge, nach ihren Familien, in ihren Völkerschaften.',
        6: 'Und die Söhne Chams: Kusch und Mizraim und Put und Kanaan.',
        7: 'Und die Söhne Kuschs waren Seba und Chavilah und Sabtha und Raemah und Sabtheka; und die Söhne Raemahs: Scheba und Dedan.',
        8: 'Und Kusch zeugte Nimrod; der fing an ein Mächtiger zu werden auf der Erde.',
        9: 'Er war ein mächtiger Jäger vor Jehovah. Darum sagte man: Wie Nimrod ein mächtiger Jäger vor Jehovah.',
        10: 'Und der Anfang seines Königreiches war Babel und Erech und Akkad und Kalneh im Lande Schinear.',
        11: 'Von diesem Lande zog aus Aschur, und baute Niniveh und die Stadt Rechoboth und Kalach;',
        12: 'Und Resen zwischen Niniveh und zwischen Kalach. Dies ist die große Stadt.',
        13: 'Und Mizraim zeugte die Ludim und Lehabim und Naphtuchim.',
        14: 'Und die Pathrusim und die Kasluchim. Woher die Philister ausgingen, und die Kaphthorim.',
        15: 'Und Kanaan zeugte Zidon, seinen Erstgeborenen, und Cheth.',
        16: 'Und den Jebusiter und den Amoriter und den Girgaschiter.',
        17: 'Und den Chiviter und den Arkiter und den Siniter.',
        18: 'Und den Arvaditer und den Zemariter und den Chamathiter; und nachher zerstreuten sich die Familien des Kanaaniters.',
        19: 'Und die Grenze des Kanaaniters war von Zidon, da man nach Gerar und Gazah kommt, da man gen Sodom und Gomorrah, und Admah und Zeboim bis Lascha kommt.',
        20: 'Dies sind die Söhne Chams nach ihren Familien, nach ihren Zungen in ihren Ländern, in ihren Völkerschaften.',
        21: 'Und dem Schem, auch ihm ward geboren; er war der Vater aller Söhne Ebers; der größere Bruder Japheths.',
        22: 'Schems Söhne sind Elam und Aschur und Arpachschad und Lud und Aram.',
        23: 'Und Arams Söhne sind Uz und Chul und Gether und Masch.',
        24: 'Und Arpachschad zeugte Schelach und Schelach zeugte Eber.',
        25: 'Und dem Eber wurden zwei Söhne geboren. Der Name des einen war Peleg, weil in seinen Tagen die Erde zerteilt ward, und der Name seines Bruders war Joktan.',
        26: 'Und Joktan zeugte Almodad und Schaleph und Chazarmaveth und Jerach;',
        27: 'Und Hadoram und Uzal und Diklah;',
        28: 'Und Obal und Abimael und Scheba;',
        29: 'Und Ophir und Chavilah und Jobab. Alle diese waren Söhne Joktans.',
        30: 'Und ihre Wohnung war von Mescha, da man gen Sephar, einen Berg in Osten kommt.',
        31: 'Dies sind die Söhne Schems nach ihren Familien, nach ihren Zungen, in ihren Ländern, nach ihren Völkerschaften.',
        32: 'Dies sind die Familien der Söhne Noachs nach ihren Geburten, in ihren Völkerschaften; und von ihnen trennten sich ab die Völkerschaften auf der Erde nach der Flut.',
    },
    11: {
        1: 'Und die ganze Erde hatte eine Lippe und einerlei Worte.',
        2: 'Und es geschah, daß sie von Osten auszogen und ein Tal im Lande Schinear fanden und daselbst wohnten.',
        3: 'Und sie sprachen zueinander: Wohlan, lasset uns Ziegel streichen und im Feuer brennen; und sie hatten Ziegel statt Stein und Erdharz hatten sie statt Mörtel.',
        4: 'Und sie sprachen: Wohlan, lasset uns eine Stadt bauen, und einen Turm und seine Spitze sei im Himmel, und laßt uns einen Namen für uns machen, daß wir uns nicht über die ganze Erde zerstreuen.',
        5: 'Und Jehovah kam herab um zu sehen die Stadt und den Turm, den die Söhne des Menschen bauten.',
        6: 'Und Jehovah sprach: Siehe, sie sind alle ein Volk und haben eine Lippe und dies fangen sie an zu tun und nun wird nichts von ihnen zurückgehalten werden was sie gedenken zu tun.',
        7: 'Wohlan, lasset uns hinabgehen und ihre Lippe verwirren, daß keiner auf die Lippe des anderen höre.',
        8: 'Und Jehovah zerstreute sie von da über die ganze Erde und sie hörten auf die Stadt zu bauen,',
        9: 'Deshalb nannte man ihren Namen Babel, weil dort Jehovah die Lippe der ganzen Erde verwirrte; und von da zerstreute sie Jehovah über die ganze Erde.',
        10: 'Dies sind die Geburten des Schem. Schem war hundert Jahre alt, und er zeugte den Arpachschad zwei Jahre nach der Flut.',
        11: 'Und Schem lebte, nachdem er den Arpachschad gezeugt, fünfhundert Jahre und zeugte Söhne und Töchter.',
        12: 'Und Arpachschad lebte fünfunddreißig Jahre, und er zeugte Schelach.',
        13: 'Und nachdem er Schelach gezeugt, lebte Arpachschad drei Jahre und vierhundert Jahre, und er zeugte Söhne und Töchter.',
        14: 'Und Schelach lebte dreißig Jahre, und zeugte den Eber.',
        15: 'Und Schelach lebte, nachdem er Eber gezeugt hatte, drei Jahre und vierhundert Jahre, und er zeugte Söhne und Töchter.',
        16: 'Und Eber lebte vierunddreißig Jahre, und zeugte den Peleg.',
        17: 'Und Eber lebte, nachdem er den Peleg gezeugt, dreißig Jahre und vierhundert Jahre, und zeugte Söhne und Töchter.',
        18: 'Und Peleg lebte dreißig Jahre und zeugte Reu.',
        19: 'Und Peleg lebte, nachdem er Reu gezeugt neun Jahre und zweihundert Jahre, und zeugte Söhne und Töchter.',
        20: 'Und Reu lebte zweiunddreißig Jahre, und zeugte Serug.',
        21: 'Und Reu lebte, nachdem er Serug gezeugt hatte, sieben Jahre und zweihundert Jahre, und er zeugte Söhne und Töchter.',
        22: 'Und Serug lebte dreißig Jahre, und zeugte Nachor.',
        23: 'Und Serug lebte, nachdem er Nachor gezeugt hatte, zweihundert Jahre, und er zeugte Söhne und Töchter.',
        24: 'Und Nachor lebte neunundzwanzig Jahre, und zeugte Tharach.',
        25: 'Und Nachor lebte, nachdem er den Tharach gezeugt hatte, neunzehn Jahre und hundert Jahre, und er zeugte Söhne und Töchter.',
        26: 'Und Tharach lebte siebzig Jahre, und zeugte Abram, Nachor und Haran.',
        27: 'Und dies sind die Geburten Tharachs: Tharach zeugte Abram, Nachor und Haran; und Haran zeugte Lot.',
        28: 'Und Haran starb auf dem Angesichte seines Vaters Tharach im Lande seiner Geburt in Ur der Chaldäer.',
        29: 'Und Abram und Nachor nahmen sich Weiber. Der Name von Abrams Weib war Sarai, und der Name von Nachors Weib Milkah, eine Tochter Harans, des Vaters der Milkah und des Vaters der Jiskah.',
        30: 'Und Sarai war unfruchtbar, sie hatte kein Kind.',
        31: 'Und Tharach nahm Abram seinen Sohn und Lot, den Sohn Harans seines Sohnes Sohn, und Sarai, seine Schwiegertochter, seines Sohnes Abrams Weib, und sie zogen aus mit ihnen aus Ur der Chaldäer um nach dem Lande Kanaan zu gehen, und sie kamen bis Charan und wohnten daselbst.',
        32: 'Und Tharachs Tage waren fünf Jahre und zweihundert Jahre, und Tharach starb in Charan.',
    },
    12: {
        1: 'Und Jehovah sprach zu Abram: Gehe aus deinem Lande, und aus deinem Geburtsort und aus dem Hause deines Vaters nach dem Lande, das Ich dir zeigen werde.',
        2: 'Und Ich will dich zu einer großen Völkerschaft machen und dich segnen und groß machen deinen Namen, und du sollst zum Segen werden.',
        3: 'Und Ich will segnen, die dich segnen und verfluchen, wer dir flucht; und in dir sollen gesegnet werden alle Familien des Bodens!',
        4: 'Und Abram ging, wie Jehovah zu ihm geredet hatte, und Lot ging mit ihm, und Abram war fünfundsiebzig Jahre alt da er von Charan auszog.',
        5: 'Und Abram nahm Sarai sein Weib und Lot, seines Bruders Sohn, und all ihre Habe, die sie gewonnen und die Seelen, die sie sich in Charan verschafft, und sie zogen aus, um nach dem Lande Kanaan zu gehen, und kamen ins Land Kanaan.',
        6: 'Und Abram zog hin im Lande bis an den Ort Sichem, zum Eichenhain Moreh, und der Kanaaniter war damals in dem Lande.',
        7: 'Und Jehovah erschien dem Abram und sprach: Deinem Samen will Ich geben dieses Land; und er baute da einen Altar dem Jehovah, Der ihm erschienen.',
        8: 'Und von da zog er weiter nach dem Berge im Osten von Bethel und schlug sein Zelt auf mit Bethel dem Meere zu und Haai im Osten und er baute dort dem Jehovah einen Altar, und rief den Namen Jehovahs an.',
        9: 'Und Abram brach auf und ging und zog aus nach Mittag.',
        10: 'Und es war eine Hungersnot im Land, und Abram ging hinab nach Ägypten um dort sich aufzuhalten; denn die Hungersnot war schwer in dem Lande.',
        11: 'Und es geschah, als er nahe war, nach Ägypten zu kommen, sprach er zu Sarai, seinem Weibe: Siehe ich weiß, daß du ein Weib, schön anzusehen, bist.',
        12: 'Und es wird geschehen, wenn dich die Ägypter sehen und sagen: das ist sein Weib! daß sie mich erwürgen und dich am Leben lassen.',
        13: 'Sage doch, du seiest meine Schwester; auf daß es mir gut gehe um deinetwillen, und meine Seele am Leben bleibe deinetwegen.',
        14: 'Und es geschah, als Abram nach Ägypten kam, daß die Ägypter das Weib sahen, daß sie sehr schön war.',
        15: 'Und die Obersten Pharaos sahen sie und lobten sie dem Pharao; und das Weib wurde in das Haus des Pharao genommen.',
        16: 'Und er tat dem Abram Gutes um ihrethalben; und er hatte Kleinvieh und Rinder und Esel und Knechte und Dienstmägde und Eselinnen und Kamele.',
        17: 'Und Jehovah plagte Pharao und sein Haus mit großen Plagen ob Sarai, des Weibes Abrams.',
        18: 'Und Pharao rief Abram und sprach: Was hast du mir das getan? Warum sagtest du mir nicht an, daß sie dein Weib ist?',
        19: 'Warum sagtest du: sie ist meine Schwester, und ich hätte sie mir zum Weibe genommen? Und nun siehe, da ist dein Weib! Nimm sie und geh!',
        20: 'Und Pharao gebot seinen Männern über ihn, und sie entsandten ihn und sein Weib mit allem, was er hatte.',
    },
    13: {
        1: 'Und Abram kam herauf aus Ägypten er und sein Weib und alles, das er hatte, und Lot mit ihm gen Mittag.',
        2: 'Und Abram war sehr reich an Viehherden, an Silber und an Gold.',
        3: 'Und er ging in seinen Zügen von Mittag bis nach Bethel zu dem Orte wo sein Zelt zum Anbeginn war, zwischen Bethel und Haai.',
        4: 'An den Ort des Altars, den er am Anfang gemacht; und Abram rief dort den Namen Jehovahs an.',
        5: 'Und auch Lot, der mit Abram zog, hatte Kleinvieh und Rinder und Zelte.',
        6: 'Aber das Land trug sie nicht, daß sie beisammen wohnten; denn ihrer Habe war viel, und sie konnten nicht beisammen wohnen.',
        7: 'Und es war Hader zwischen den Hirten von Abrams Viehherden und zwischen den Hirten von Lots Viehherden. Und der Kanaaniter und der Pheresiter wohnten damals im Lande.',
        8: 'Und Abram sprach zu Lot: Laß doch nicht Hader zwischen mir und zwischen dir, und zwischen meinen Hirten, und zwischen deinen Hirten sein, denn wir sind Brüder.',
        9: 'Ist nicht das ganze Land vor dir? So trenne dich doch von mir. Wenn zur Linken, so will ich zur Rechten gehen, und wenn zur Rechten, so will ich zur Linken gehen.',
        10: 'Und Lot hob seine Augen auf und sah den ganzen Umkreis, daß dieser ganz vom Jordan bewässert war. Ehe Jehovah Sodom und Gomorrah verdarb, war das Land wie ein Garten Jehovahs, wie Ägypten, wo man nach Zoar kommt.',
        11: 'Und Lot erwählte den ganzen Umkreis des Jordans für sich; und Lot brach auf vom Osten und sie trennten sich der Mann von seinem Bruder.',
        12: 'Abram wohnte im Lande Kanaan, und Lot wohnte in den Städten des Umkreises und zeltete bis gen Sodom.',
        13: 'Und die Männer Sodoms waren sehr böse und Sünder gegen Jehovah.',
        14: 'Und Jehovah sprach zu Abram, nachdem sich Lot von ihm getrennt hatte: Hebe doch deine Augen auf und siehe von dem Ort aus, wo du bist gen Mitternacht und gen Mittag und gen Osten und dem Meere zu.',
        15: 'Denn alles Land, das du siehst, will Ich dir und deinem Samen geben ewiglich.',
        16: 'Und will deinen Samen machen wie Staub der Erde. So ein Mann den Staub der Erde zu berechnen vermag, so wird auch dein Same berechnet werden.',
        17: 'Mache dich auf und ziehe durch das Land, seiner Länge nach und seiner Breite nach; denn dir will Ich es geben.',
        18: 'Und Abram zeltete und kam und wohnte in den Eichenhainen Mamres, die in Hebron sind, und baute daselbst dem Jehovah einen Altar.',
    },
    14: {
        1: 'Und es geschah, in den Tagen Amraphels, des Königs von Schinear, Ariochs, des Königs von Ellasar, Kedorlaomers, des Königs von Elam und Thideals, des Königs von Gojim,',
        2: 'Daß sie Krieg machten mit Bera, König von Sodom, und mit Birscha, König von Gomorrah, Schineab, König von Admah, und Schemeber, König von Zebojim, und dem Könige von Bela, das ist Zoar.',
        3: 'Diese alle verbündeten sich im Talgrunde Siddim, das ist das Salzmeer.',
        4: 'Zwölf Jahre hatten sie dem Kedorlaomer gedient, und im dreizehnten empörten sie sich.',
        5: 'Und im vierzehnten Jahre kam Kedorlaomer und die Könige, die mit ihm waren, und schlugen die Rephaim in Aschteroth-Karnaim und die Susim in Ham und die Emim in Schaveh Kirjathaim.',
        6: 'Und die Choriter auf ihrem Berge Seir bis El-Paran, das oben an der Wüste ist.',
        7: 'Und sie kehrten zurück, und kamen nach En-Mischpat, das ist Kadesch, und schlugen das ganze Gefilde des Amalekiters, und auch den Amoriter, der in Chazezon Thamar wohnt.',
        8: 'Und der König von Sodom zog aus, und der König von Gomorrah, und der König von Admah, und der König von Zeboim und der König von Bela, und ordneten sich zum Streit mit ihnen im Talgrund Siddim.',
        9: 'Mit Kedorlaomer, König von Elam, und Thideal, König von Gojim, und Amraphel, König von Schinear, und Arioch, König von Ellasar, vier Könige mit fünf.',
        10: 'Und der Talgrund Siddim hat Gruben an Gruben mit Erdharz, und der König von Sodom und von Gomorrah flohen und fielen daselbst, und die übrigen flohen aufs Gebirge.',
        11: 'Und sie nahmen alle Habe von Sodom und Gomorrah und all ihre Speise und zogen hin.',
        12: 'Und sie nahmen Lot, den Sohn von Abrams Bruder, und seine Habe und zogen hin; und er wohnte in Sodom.',
        13: 'Und es kam einer, der entkommen war, und sagte es Abram, dem Hebräer an, der da wohnte in den Eichenhainen Mamres, des Amoriters, des Bruders von Eskol und Bruders von Aner, und diese waren im Bunde mit Abram.',
        14: 'Und Abram hörte, daß sein Bruder gefangen war, und er ließ ausziehen seine Eingeübten in seinem Hause Geborenen dreihundertachtzehn, und setzte ihnen nach bis gen Da.',
        15: 'Und er teilte sich wider sie in der Nacht, er und seine Knechte, und schlug sie, und setzte ihnen nach bis nach Chobah, das zur Linken von Damaskus ist.',
        16: 'Und brachte alle ihre Habe zurück; auch seinen Bruder Lot und seine Habe brachte er zurück und auch die Weiber und das Volk.',
        17: 'Und der König von Sodom kam heraus, ihm entgegen, nachdem er zurückgekommen, als er Kedorlaomer und die Könige, die mit ihm waren geschlagen in dem Talgrund Schaveh, das ist des Königs Talgrund.',
        18: 'Und Melchizedek, König von Schalem, brachte heraus Brot und Wein, und er war Priester des höchsten Gottes;',
        19: 'Und er segnete ihn und sprach: Gesegnet sei Abram dem höchsten Gotte, der Himmel und Erde besitzet!',
        20: 'Und gesegnet sei der höchste Gott, daß Er deine Dränger in deine Hand geliefert. Und er gab ihm von allem den Zehnten.',
        21: 'Und der König von Sodom sprach zu Abram: Gib mir die Seelen und nimm die Habe für dich.',
        22: 'Abram aber sprach zu dem König von Sodom: Ich habe meine Hand emporgehoben zu Jehovah, dem höchsten Gott, der Himmel und Erde besitzet,',
        23: 'Daß ich vom Faden bis zum Schuhriemen, von allem das dein ist, nichts nehmen will; und du sollst nicht sagen: Ich habe den Abram reich gemacht.',
        24: 'Nichts für mich! außer dem, was die Jünglinge verzehrten, und dem Teil der Männer, die mit mir zogen. Aner, Eschkol und Mamre, sie sollen ihren Teil nehmen.',
    },
    15: {
        1: 'Nach diesen Dingen geschah das Wort Jehovahs zu Abram im Gesichte, und sprach: Fürchte dich nicht, Abram, Ich bin ein Schild dir, deines Lohnes ist sehr viel.',
        2: 'Und Abram sprach: Was willst Du mir geben, Herr, Jehovah, und ich gehe hin kinderlos, und der Sohn, der Hausvogt, ist dieser Damasker Elieser.',
        3: 'Und Abram sprach: Siehe, Du hast mir keinen Samen gegeben. Und siehe, der Sohn meines Hauses wird mich beerben.',
        4: 'Und siehe, das Wort Jehovahs zu ihm sprach: Nicht soll dieser dich beerben sondern der ausgehen wird aus deinen Eingeweiden, der soll dich beerben.',
        5: 'Und Er führte ihn hinaus und sprach: Blicke doch gen Himmel und zähle die Sterne, wenn du sie zu zählen vermagst! und Er sprach zu ihm: So wird dein Same sein.',
        6: 'Und er glaubte an Jehovah, und Er gedachte es ihm zur Gerechtigkeit.',
        7: 'Und Er sprach zu ihm: Ich bin Jehovah, Der dich herausführte aus Ur der Chaldäer, dir dieses Land zum Erbbesitze zu geben.',
        8: 'Und er sprach: Herr, Jehovah, woran soll ich erkennen, daß ich es erblich besitzen werde?',
        9: 'Und Er sprach zu ihm: Hole Mir eine dreijährige Färse und eine dreijährige Ziege und einen dreijährigen Widder und eine Turteltaube und eine junge Taube.',
        10: 'Und er holte sich sie alle und zerstückte sie in der Mitte, und legte jegliches Stück dem anderen gegenüber, den Vogel aber zerstückte er nicht.',
        11: 'Und es kam der Raubvogel herab auf die Leiber her; aber Abram wandte sie zurück.',
        12: 'Und die Sonne war am Untergehen, und ein tiefer Schlaf fiel auf Abram; und siehe, der Schrecken großer Finsternis fiel über ihn.',
        13: 'Und Er sprach zu Abram: Du sollst gewißlich wissen, daß dein Same sich wird aufhalten in einem Lande, das nicht das seine ist. Und sie werden ihnen dienen; und sie werden sie drücken vierhundert Jahre lang.',
        14: 'Aber auch mit der Völkerschaft, der sie dienen werden, werde Ich rechten; und danach sollen sie ausziehen mit großer Habe.',
        15: 'Du aber sollst eingehen zu deinen Vätern im Frieden, du sollst in gutem Greisenalter begraben werden.',
        16: 'Und im vierten Geschlecht sollen sie hierher zurückkehren; denn die Missetat des Amoriters ist bis jetzt noch nicht voll.',
        17: 'Und es geschah, daß die Sonne unterging, und es war düster, und siehe, ein rauchender Ofen und eine Feuerfackel zog zwischen den Stücken hin.',
        18: 'An jenem Tage schloß Jehovah mit Abram einen Bund und sprach: Deinem Samen habe Ich dieses Land gegeben, von dem Flusse Ägyptens bis zu dem großen Flusse, dem Flusse Phrat;',
        19: 'Den Keniter und den Kenissiter und den Kadmoniter,',
        20: 'Und den Chethiter und den Pherisiter und die Rephaim;',
        21: 'Und den Amoriter und den Kanaaniter und den Gergasiter und den Jebusiter.',
    },
    16: {
        1: 'Und Sarai, Abrams Weib, gebar ihm nicht. Sie hatte aber eine ägyptische Dienstmagd und ihr Name war Hagar.',
        2: 'Und Sarai sprach zu Abram: Siehe doch, Jehovah hat mich vom Gebären zurückgehalten; so gehe doch ein zu meiner Dienstmagd, vielleicht werde ich durch sie aufgebaut. Und Abram hörte auf Sarais Stimme.',
        3: 'Und Sarai, Abrams Weib, nachdem zehn Jahre zu Ende waren, seit Abram im Lande Kanaan wohnte, nahm die Ägypterin Hagar, ihre Dienstmagd, und gab sie ihrem Manne Abram ihm zum Weibe.',
        4: 'Und er ging ein zu Hagar und sie empfing; und da sie sah, daß sie empfangen hatte, ward ihre Gebieterin gering in ihren Augen.',
        5: 'Und Sarai sprach zu Abram: Mein Unrecht sei auf dir! Ich gab dir meine Dienstmagd an deinen Busen. Und sie sieht, daß sie empfangen hat, und ich werde gering in ihren Augen. Jehovah richte zwischen mir und dir!',
        6: 'Abram aber sprach zu Sarai: Siehe, deine Dienstmagd ist in deiner Hand, tue ihr, was gut in deinen Augen ist. Und Sarai demütigte sie, und sie floh vor ihrem Angesicht.',
        7: 'Und der Engel Jehovahs fand sie in der Wüste an einer Wasserquelle; an der Quelle am Wege nach Schur.',
        8: 'Und Er sprach: Hagar, Sarais Dienstmagd, woher kommst du und wohin gehst du? Und sie sprach: Vor meiner Gebieterin Sarai fliehe ich.',
        9: 'Und Jehovahs Engel sprach zu ihr: Kehre zurück zu deiner Gebieterin und demütige dich unter ihre Hände.',
        10: 'Und der Engel Jehovahs sprach zu ihr: Mehren will Ich deinen Samen und er wird vor Menge nicht gezählt werden.',
        11: 'Und der Engel Jehovahs sprach zu ihr: Siehe, du hast empfangen und gebierst einen Sohn, und sollst seinen Namen Ismael nennen, darum, daß Jehovah auf dein Elend gehört hat.',
        12: 'Und er wird ein Waldesel-Mensch sein, seine Hand wider alle, und die Hand aller wider ihn; und wird wohnen wider aller seiner Brüder Angesicht.',
        13: 'Und sie nannte den Namen Jehovahs, Der mit ihr redete: Du bist der Gott, Der mich siehet; denn sie sprach: Hab ich auch hier gesehen, nach Dem, Der mich gesehen?',
        14: 'Daher nannte man den Brunnen: Brunnen Lachai Roi. Siehe, er ist zwischen Kadesch und zwischen Bared.',
        15: 'Und Hagar gebar dem Abram einen Sohn, und Abram nannte den Namen seines Sohnes, den Hagar geboren, Ismael.',
        16: 'Und Abram war achtzig Jahre und sechs Jahre alt, da Hagar den Ismael dem Abram gebar.',
    },
    17: {
        1: 'Und Abram war neunzig Jahre und neun Jahre alt, und Jehovah erschien dem Abram und sprach zu ihm: Ich bin Gott Schaddai, wandle vor Mir und sei untadelig.',
        2: 'Und Ich will Meinen Bund geben zwischen Mir und zwischen dir und dich gar sehr vermehren.',
        3: 'Und Abram fiel auf sein Angesicht; und Gott redete mit ihm und sprach:',
        4: 'Ich, siehe Mein Bund ist mit dir; und du sollst der Vater einer Menge Völkerschaften werden.',
        5: 'Und deinen Namen soll man fortan nicht mehr Abram nennen, sondern dein Name soll Abraham sein; denn zum Vater einer Menge von Völkerschaften gebe Ich dich.',
        6: 'Und Ich will dich gar sehr fruchtbar machen, und gebe dich zu Völkerschaften, und Könige sollen von dir ausgehen.',
        7: 'Und Ich richte auf Meinen Bund zwischen Mir und zwischen dir und zwischen deinem Samen nach dir für ihre Geschlechter, als einen ewigen Bund, dir und deinem Samen nach dir Gott zu sein;',
        8: 'Und Ich gebe dir und deinem Samen nach dir das Land deiner Wanderungen, das ganze Land Kanaan, zum ewigen Eigentum, und werde ihnen Gott sein.',
        9: 'Und Gott sprach zu Abraham: Du aber, du sollst Meinen Bund halten, du und dein Same nach dir, nach ihren Geschlechtern.',
        10: 'Das ist Mein Bund, den ihr halten sollt zwischen Mir und zwischen euch und zwischen deinem Samen nach dir. Beschnitten werde euch alles Männliche!',
        11: 'Und ihr sollet beschnitten werden am Fleische eurer Vorhaut; und das sei zum Zeichen des Bundes zwischen Mir und zwischen euch!',
        12: 'Und acht Tage alt werde von euch alles Männliche beschnitten in euern Geschlechtern, der im Hause geboren und der mit Silber erworben ist von irgendwelchem Sohne des Auslands, der nicht deines Samens ist.',
        13: 'Gewißlich soll beschnitten werden, wer in deinem Hause geboren und wer mit deinem Silber erworben ist. Und Mein Bund soll in eurem Fleische sein zum ewigen Bunde.',
        14: 'Und der unbeschnittene Männliche, der sich nicht das Fleisch seiner Vorhaut beschneiden ließ, dessen Seele soll ausgerottet werden von seinen Völkern, er hat Meinen Bund zunichte gemacht.',
        15: 'Und Gott sprach zu Abraham: Dein Weib Sarai - ihren Namen sollst du nicht Sarai nennen, sondern Sarah soll ihr Name sein.',
        16: 'Und Ich segne sie, und gebe dir auch von ihr einen Sohn; und Ich segne sie, daß sie zu Völkerschaften werde; Könige von Völkern sollen aus ihr werden.',
        17: 'Und Abraham fiel auf sein Angesicht und lachte, und sprach in seinem Herzen: Soll mir, dem hundert Jahre alten, geboren werden, und Sarah soll, neunzig Jahre alt, gebären?',
        18: 'Und Abraham sprach zu Gott: Oh, möchte Ismael leben vor dir!',
        19: 'Und Gott sprach: Fürwahr, dein Weib Sarah wird dir einen Sohn gebären, und du sollst seinen Namen Isaak nennen, und Ich werde Meinen Bund mit ihm aufrichten zu einem Bunde der Ewigkeit für seinen Samen nach ihm.',
        20: 'Und wegen Ismael habe Ich dich erhört. Siehe, Ich segne ihn, und mach ihn fruchtbar und mehre ihn sehr, sehr. Zwölf Fürsten wird er zeugen, und zu einer großen Völkerschaft gebe Ich ihn.',
        21: 'Aber Meinen Bund richte Ich mit Isaak auf, den Sarah dir um diese bestimmte Zeit im anderen Jahr gebären wird.',
        22: 'Und Er vollendete Seine Rede mit ihm, und Gott stieg auf von Abraham.',
        23: 'Und Abraham nahm seinen Sohn Ismael und alle in seinem Haus Geborenen und alle mit seinem Silber Erworbenen, alles Männliche unter den Männern des Hauses Abrahams, und beschnitt das Fleisch ihrer Vorhaut an diesem selbigen Tage, wie Gott mit ihm geredet hatte.',
        24: 'Und Abraham war neunundneunzig Jahre alt, als er das Fleisch seiner Vorhaut beschnitt.',
        25: 'Und Sein Sohn Ismael war dreizehn Jahre alt, als ihm das Fleisch seiner Vorhaut beschnitten wurde.',
        26: 'An diesem selbigen Tage wurde Abraham und sein Sohn Ismael beschnitten.',
        27: 'Und alle Männer seines Hauses, der im Haus Geborene und der von dem Sohne des Auslandes mit Silber Erworbene, wurden mit ihm beschnitten.',
    },
    18: {
        1: 'Und Jehovah erschien ihm in den Eichenhainen Mamres, und er saß am Eingang des Zeltes als der Tag heiß ward.',
        2: 'Und er hob seine Augen auf und sah, und siehe, drei Männer standen bei ihm; und er sah, und lief ihnen entgegen vom Eingang des Zeltes und verbeugte sich zur Erde.',
        3: 'Und sprach: Mein Herr, wenn ich doch Gnade fände in deinen Augen! Zieh doch nicht vorüber an deinem Knechte.',
        4: 'Nehmet doch ein wenig Wasser, und waschet eure Füße und lehnet euch unter den Baum.',
        5: 'Und ich will einen Bissen Brot holen, daß ihr euer Herz stützet, hernach möget ihr vorüberziehen. Denn darum seid ihr bei eurem Knechte vorübergezogen. Und sie sprachen: Tue, wie du geredet hast.',
        6: 'Und Abraham eilte nach dem Zelt zu Sarah, und sprach: Nimm eilends drei Seah Mehl, Semmelmehl, knete und mache Kuchen.',
        7: 'Und Abraham lief zu den Rindern, und nahm ein Kalb, zart und gut, und gab es dem Jungen; und er eilte, es zu bereiten.',
        8: 'Und er nahm Butter und Milch und das Kalb, das er bereiten ließ, und setzte ihnen vor, und er stand bei ihnen unter dem Baum und sie aßen.',
        9: 'Und sie sprachen zu ihm: Wo ist dein Weib Sarah? Und er sagte: sehet, in dem Zelte.',
        10: 'Und Er sprach: Zu dieser Zeit des Lebens kehre Ich zu dir zurück, und siehe, dein Weib Sarah hat einen Sohn; und Sarah hörte es am Eingang des Zeltes, und dieser war hinter ihm.',
        11: 'Und Abraham und Sarah waren alt, gekommen in die Tage und es hatte aufgehört mit Sarah zu sein nach der Weiber Weise.',
        12: 'Und Sarah lachte bei sich und sprach: Nachdem ich alt geworden bin, sollt ich noch Wollust haben? Und mein Herr ist alt.',
        13: 'Und Jehovah sprach zu Abraham: Warum lacht Sarah und spricht: Sollte ich fürwahr gebären, so ich doch alt bin?',
        14: 'Sollte für Jehovah ein Ding zu wunderbar sein? Zur bestimmten Zeit kehre Ich zu dir zurück, um diese Zeit des Lebens und Sarah hat einen Sohn.',
        15: 'Und Sarah leugnete und sagte: Ich habe nicht gelacht; denn sie fürchtete sich. Er aber sprach: Nein, du hast gelacht.',
        16: 'Und die Männer standen auf von da und schauten aus gegen Sodom, und Abraham ging mit ihnen, sie zu entsenden.',
        17: 'Und Jehovah sprach: Soll Ich vor Abraham verdecken, was Ich tun will?',
        18: 'Und Abraham wird doch zur großen und zahlreichen Völkerschaft, und alle Völkerschaften der Erde sollen in ihm gesegnet werden.',
        19: 'Denn Ich habe ihn dahin erkannt, daß er seinen Söhnen und seinem Hause nach ihm wird gebieten, daß sie den Weg Jehovahs halten, zu tun Gerechtigkeit und Recht, auf daß Jehovah auf Abraham kommen lasse, was Er über ihn geredet hat.',
        20: 'Und Jehovah sprach: Weil des Geschreis über Sodom und Gomorrah viel geworden, und ihre Sünde sehr schwer ist.',
        21: 'Will Ich nun doch hinabsteigen und sehen, ob sie nach dem Geschrei, das zu Mir gekommen, eine Vollendung gemacht, und ob nicht, will Ich wissen.',
        22: 'Die Männer aber wandten sich von da und gingen gen Sodom; und Abraham stand noch vor Jehovah.',
        23: 'Und Abraham trat herzu und sprach: Willst Du auch wegraffen den Gerechten mit dem Ungerechten?',
        24: 'Vielleicht sind fünfzig Gerechte in der Mitte der Stadt. Willst Du den Ort auch dann wegraffen, und nicht ihm verzeihen um der fünfzig Gerechten willen, die in seiner Mitte sind?',
        25: 'Das sei ferne von Dir, nach solchem Worte zu tun, daß Du tötest den Gerechten mit dem Ungerechten, und daß der Gerechte sei, wie der Ungerechte; das sei ferne von Dir. Sollte der Rier der ganzen Erde nicht Gericht üben?',
        26: 'Und Jehovah sprach: Wenn Ich in Sodom fünfzig Gerechte in der Mitte der Stadt finde, so verzeihe Ich dem ganzen Orte um ihretwillen.',
        27: 'Und Abraham antwortete und sprach: Siehe doch, ich habe mich unterstanden, mit meinem Herrn zu reden, und ich bin Staub und Asche.',
        28: 'Vielleicht mangeln zu den fünfzig Gerechten fünf, wirst du die ganze Stadt um der fünfe willen verderben? Und Er sprach: Ich will sie nicht verderben, wenn Ich dort fünfundvierzig finde.',
        29: 'Und er fuhr fort, mit Ihm zu reden, und sprach: Vielleicht finden sich dort vierzig; und Er sprach: Ich will es nicht tun um der vierzig willen.',
        30: 'Und er sprach: Entbrenne doch nicht, mein Herr, und ich will reden; vielleicht würden dreißig dort gefunden. Und Er sprach: Ich will es nicht tun, wenn Ich dort dreißig finde.',
        31: 'Und er sprach: Siehe doch, ich habe mich unterstanden, mit meinem Herrn zu reden. Vielleicht wird man dort zwanzig finden. Und Er sprach: Ich verderbe sie nicht um der zwanzig willen.',
        32: 'Und er sprach: Es entbrenne nicht mein Herr, daß ich nur noch diesmal rede. Vielleicht werden dort zehn gefunden. Und Er sprach: Um der zehn willen verderbe Ich sie nicht.',
        33: 'Und Jehovah ging hin, als Er mit Abraham vollendet zu reden; und Abraham kehrte zurück an seinen Ort.',
    },
    19: {
        1: 'Und die zwei Engel kamen am Abend nach Sodom, und Lot saß im Tore Sodoms. Und Lot sah sie und er stand auf, ihnen entgegen, und verbeugte sich mit dem Antlitz zur Erde.',
        2: 'Und er sprach: Siehe doch, meine Herren, lenket doch in das Haus eures Knechtes ab und übernachtet und waschet eure Füße, und stehet früh auf und gehet eures Weges. Sie sagten aber: Nein, denn wir werden auf der Straße übernachten.',
        3: 'Und er drang sehr in sie; und sie lenkten zu ihm ab und kamen in sein Haus. Und er machte ihnen ein Gastmahl und buk Ungesäuertes, und sie aßen.',
        4: 'Ehe sie sich legten, da umgaben die Männer der Stadt, die Männer von Sodom, das Haus, vom Jungen bis zum Alten, das ganze Volk vom Ende her.',
        5: 'Und sie riefen Lot, und sagten zu ihm: Wo sind die Männer, die diese Nacht zu dir gekommen sind. Bringe sie zu uns heraus, daß wir sie erkennen.',
        6: 'Lot aber ging hinaus zu ihnen an den Eingang, und schloß die Tür hinter sich zu.',
        7: 'Und sprach: Nicht doch, meine Brüder, tut nicht Böses!',
        8: 'Sehet doch, ich habe zwei Töchter, die keinen Mann erkannt haben, laßt sie mich doch zu euch herausbringen, und tut mit ihnen, was gut ist in euren Augen, nur diesen Männern tut nichts; denn dafür sind sie unter den Schatten meines Daches gekommen.',
        9: 'Und sie sprachen: Tritt hier herzu. Und sie sagten: Ist einer gekommen, sich hier aufzuhalten, und will als Rier richten? Nun wollen wir dir Böseres tun, denn jenen; und sie drangen sehr ein auf den Mann, auf Lot, und sie traten herzu, um die Tür aufzubrechen.',
        10: 'Und die Männer streckten ihre Hand hinaus und brachten Lot zu sich herein ins Haus und verschlossen die Tür.',
        11: 'Die Männer aber am Eingang zum Hause schlugen sie mit Blindheit vom Kleinen bis zum Großen und sie müheten sich ab, den Eingang zu finden.',
        12: 'Und die Männer sprachen zu Lot: Wen hast du noch hier? Eidam und deine Söhne und deine Töchter und jeden, den du in der Stadt hast, bringe heraus aus diesem Orte;',
        13: 'Denn wir verderben diesen Ort, weil das Geschrei über sie groß ist vor Jehovah, und Jehovah hat uns gesandt, ihn zu verderben.',
        14: 'Und Lot ging hinaus und redete zu seinen Eidamen, die seine Töchter nehmen wollten, und sprach: Machet euch auf, gehet aus von diesem Ort, denn Jehovah verdirbt die Stadt. Er war aber vor den Augen seiner Eidame, wie ein Scherzender.',
        15: 'Und als die Morgenröte aufging, trieben die Engel Lot an, und sprachen: Mache dich auf, nimm dein Weib und deine zwei Töchter, die sich finden, daß du nicht in der Missetat der Stadt weggerafft werdest.',
        16: 'Und er zauderte; die Männer aber faßten ihn an seiner Hand und sein Weib bei der Hand und seine zwei Töchter bei der Hand, weil Jehovah ihn bemitleidete, und brachten ihn hinaus und ließen ihn draußen vor der Stadt.',
        17: 'Und es geschah, als sie dieselben hinausgebracht hatten, sprach Er: Entrinne ob deiner Seele, blicke nicht hinter dich und bleib nicht stehen in dem ganzen Umkreis, entrinne auf den Berg, auf daß du nicht weggerafft werdest.',
        18: 'Lot aber sprach zu ihnen: Nicht doch, meine Herren!',
        19: 'Siehe doch, Dein Knecht hat Gnade gefunden in Deinen Augen, und Du hast groß gemacht Deine Barmherzigkeit, die Du an mir getan, daß Du meine Seele am Leben erhalten; aber ich vermag nicht auf den Berg zu entrinnen, daß mir nicht das Böse anklebe, daß ich stürbe.',
        20: 'Siehe doch diese Stadt ist nahe, um dahin zu fliehen. Und sie ist klein, laß mich dahin entrinnen; ist sie nicht klein? und meine Seele wird leben.',
        21: 'Und Er sprach zu ihm: Siehe auch in diesem Worte erhöre Ich dich, daß Ich die Stadt nicht umkehre, von der du geredet hast.',
        22: 'Eile, entrinne dahin, weil Ich nichts zu tun vermag, bis du dahin kommst. Deshalb nannte man den Namen der Stadt Zoar.',
        23: 'Die Sonne ging auf über die Erde und Lot kam gen Zoar.',
        24: 'Und Jehovah ließ regnen über Sodom und über Gomorrah Schwefel und Feuer von Jehovah aus dem Himmel.',
        25: 'Und Er kehrte um diese Städte und den ganzen Umkreis und alle Einwohner der Städte und das Gewächs des Bodens.',
        26: 'Aber sein Weib blickte um hinter ihm und ward zur Salzsäule.',
        27: 'Und Abraham machte sich früh am Morgen auf nach dem Orte, wo er vor Jehovah gestanden;',
        28: 'Und schaute aus über Sodom und Gomorrah und über das ganze Land des Umkreises und er sah, und siehe da, es stieg der Qualm der Erde auf, wie der Qualm eines Ofens.',
        29: 'Und es geschah, als Gott die Städte des Umkreises verdarb, daß Gott des Abrahams gedachte, und Lot mitten aus der Zerstörung entsandte wie er die Städte umkehrte in denen Lot gewohnt.',
        30: 'Lot aber ging hinauf aus Zoar und wohnte auf dem Berge und seine zwei Töchter mit ihm; denn er fürchtete sich in Zoar zu wohnen; und er wohnte in der Höhle, er und seine zwei Töchter.',
        31: 'Und die Erstgeborene sprach zur Jüngeren: Unser Vater ist alt und kein Mann ist im Lande, der zu uns käme, nach der Weise der ganzen Erde.',
        32: 'So komm, laß uns unserem Vater Wein zu trinken geben und bei ihm liegen, auf daß wir von unserem Vater Samen lebendig machen.',
        33: 'Und sie ließen ihren Vater Wein trinken in derselben Nacht, und die Erstgeborene kam und lag bei ihrem Vater, und er wußte es nicht, da sie sich niederlegte, noch da sie aufstand.',
        34: 'Und es geschah am morgenden Tag, daß die Erstgeborene zur Jüngeren sprach: Siehe ich bin gestern bei meinem Vater gelegen. Lassen wir ihn auch diese Nacht Wein trinken, und gehe du hinein und liege bei ihm, daß wir von unserem Vater Samen lebendig machen.',
        35: 'Und sie ließen ihren Vater Wein trinken; und die Jüngere machte sich auf und lag bei ihm, und er wußte es nicht, da sie sich legte, noch da sie aufstand.',
        36: 'Und die zwei Töchter Lots empfingen von ihrem Vater.',
        37: 'Und die Erstgeborene gebar einen Sohn und nannte seinen Namen Moab. Er ist der Vater Moabs bis auf diesen Tag.',
        38: 'Und die Jüngere gebar auch einen Sohn, und nannte seinen Namen Ben-Ammi. Er ist der Vater der Söhne Ammons bis auf diesen Tag.',
    },
    20: {
        1: 'Und Abraham zog aus von da nach dem Lande gegen Mittag, und wohnte zwischen Kadesch und zwischen Schur, und hielt sich in Gerar auf.',
        2: 'Und Abraham sagte von seinem Weibe Sarah: Sie ist meine Schwester. Und Abimelech, König von Gerar, sandte und nahm Sarah.',
        3: 'Und Gott kam zu Abimelech im Traume bei Nacht, und sprach zu ihm: Siehe, du stirbst ob dem Weibe, das du genommen hast; denn sie ist einem Gemahle vermählt.',
        4: 'Abimelech aber hatte sich ihr nicht genaht, und sprach: Herr, wirst du auch eine gerechte Völkerschaft erwürgen?',
        5: 'Sagte er mir nicht: Sie ist meine Schwester? Und sie auch, sagte sie nicht selbst: Er ist mein Bruder? In Rechtschaffenheit meines Herzens und mit Unschuld meiner Hände habe ich das getan.',
        6: 'Und Gott sprach zu ihm im Traum: Auch Ich weiß, daß du dies in der Rechtschaffenheit deines Herzens getan hast; und Ich hielt dich auch zurück, daß du nicht wider Mich sündigest; deshalb gab Ich es nicht zu, daß du sie berührtest.',
        7: 'Nun aber gib zurück des Mannes Weib; denn er ist ein Prophet, und er wird beten für dich, daß du am Leben bleibst; und gibst du sie nicht zurück, so wisse, daß du des Todes sterben mußt, du und alles, was du hast.',
        8: 'Und Abimelech stand früh am Morgen auf und rief alle seine Knechte, und redet alle diese Worte vor ihren Ohren. Und die Männer fürchteten sich sehr.',
        9: 'Und Abimelech rief dem Abraham, und sprach zu ihm: Was hast du uns getan? Und was habe ich an dir gesündigt, daß du über mich und über mein Reich so große Sünde gebracht? Du hast Taten an mir getan, die man nicht tun sollte.',
        10: 'Und Abimelech sprach zu Abraham: Was hast du gesehen, daß du solches tatest.',
        11: 'Und Abraham sprach: Ich sagte: Es ist doch keine Furcht Gottes an diesem Orte, und sie werden mich erwürgen wegen meines Weibes.',
        12: 'Und sie ist auch in Wahrheit meine Schwester, die Tochter meines Vaters ist sie, aber nicht die Tochter meiner Mutter, und sie ward mir zum Weibe.',
        13: 'Und es geschah als mich Gott aus meines Vaters Hause wandern ließ, da sprach ich zu ihr: das ist deine Barmherzigkeit, die du an mir tun sollst an jedem Ort, an den wir kommen, daß du von mir sagst: Er ist mein Bruder.',
        14: 'Und Abimelech nahm Kleinvieh und Rinder und Knechte und Dienstmägde, und gab sie Abraham, und gab ihm Sarah, sein Weib, zurück.',
        15: 'Und Abimelech sprach: Siehe, mein Land ist vor dir, wohne, wo es gut ist in deinen Augen.',
        16: 'Und zu Sarah sprach er: Siehe, deinem Bruder gebe ich tausend Silberstücke. Siehe, das ist für dich eine Decke der Augen für alle, die mit dir sind, und für alle. Und für sie ward gerügt.',
        17: 'Und Abraham betete zu Gott; und Gott heilte Abimelech, sein Weib und seine Mägde, und sie gebaren.',
        18: 'Denn Jehovah hatte jeglichen Mutterschoß in Abimelechs Haus zurückgehalten ob Sarah, dem Weibe Abrahams.',
    },
    21: {
        1: 'Und Jehovah suchte Sarah heim, wie Er gesagt, und Jehovah tat mit Sarah, wie Er geredet hatte.',
        2: 'Und Sarah empfing und gebar Abraham einen Sohn in seinem Alter zu der bestimmten Zeit, wie Gott mit ihm geredet hatte.',
        3: 'Und Abraham nannte den Namen seines Sohnes, der ihm geboren worden, den ihm Sarah gebar, Isaak.',
        4: 'Und Abraham beschnitt Isaak, seinen Sohn, am achten Tage, wie ihm Gott geboten hatte.',
        5: 'Und Abraham war hundert Jahre alt, da ihm Isaak, sein Sohn, geboren wurde.',
        6: 'Und Sarah sprach: Ein Lachen hat mir Gott bereitet. Jeder, der es hört, wird lachen über mich.',
        7: 'Und sie sprach: Wer hätte dem Abraham gesagt: Sarah säugt Söhne! daß ich seinem Alter einen Sohn gebären würde!',
        8: 'Und das Kind ward groß und ward entwöhnt, und Abraham machte ein großes Gastmahl am Tage von Isaaks Entwöhnung.',
        9: 'Und Sarah sah den Sohn der Hagar, der Ägypterin, den sie dem Abraham geboren hatte, spotten,',
        10: 'Und sie sprach zu Abraham: Treibe diese Magd und ihren Sohn fort; denn der Sohn dieser Magd darf nicht mit meinem Sohne, mit Isaak, erblich besitzen.',
        11: 'Und das Wort war sehr böse in den Augen Abrahams wegen seines Sohnes.',
        12: 'Und Gott sprach zu Abraham: Es sei nicht böse in deinen Augen wegen des Jungen und deiner Magd. Alles, was Sarah zu dir sagt, höre auf ihre Stimme; denn in Isaak soll dir ein Same genannt werden.',
        13: 'Und auch den Sohn der Magd will Ich als eine Völkerschaft setzen, weil er dein Same ist.',
        14: 'Und Abraham stand früh am Morgen auf, und nahm Brot und einen Schlauch mit Wasser, und gab sie Hagar, legte sie auf ihre Schulter, und den Knaben und entsandte sie. Und sie ging hin und wanderte umher in der Wüste Beerschaba.',
        15: 'Und das Wasser war alle aus dem Schlauche; und sie warf den Knaben unter eines der Gesträuche;',
        16: 'Und sie ging hin und setzte sich von ferne, einen Bogenschuß weit gegenüber; denn, sprach sie, ich will nicht sehen, wie der Knabe stirbt. Und sie saß da gegenüber, und hob ihre Stimme auf und weinte.',
        17: 'Und Gott hörte die Stimme des Jungen, und der Engel Gottes rief der Hagar vom Himmel zu, und sprach zu ihr: Was ist dir, Hagar? Früchte dich nicht! denn Gott hat die Stimme des Jungen gehört dort, wo er ist.',
        18: 'Steh auf, nimm den Jungen und faß ihn an der Hand; denn Ich will ihn zu einer großen Völkerschaft setzen.',
        19: 'Und Gott tat ihre Augen auf, und sie sah einen Brunnen mit Wasser; und sie ging und füllte den Schlauch mit Wasser und ließ den Jungen trinken.',
        20: 'Und Gott war mit dem Jungen, und er ward groß, und wohnte in der Wüste, und er ward ein Bogenschütze.',
        21: 'Und er wohnte in der Wüste Paran, und seine Mutter nahm ihm ein Weib aus dem Lande Ägypten.',
        22: 'Und es geschah um diese Zeit, daß Abimelech und der Oberste seines Heeres, Pichol, mit Abraham sprachen und sagten: Gott ist mit dir in allem, was du tust.',
        23: 'Und nun schwöre mir bei Gott hier, daß du gegen mich, meinen Sohn und meinen Enkel nicht lügen willst. Nach der Barmherzigkeit, die ich an dir getan, tue auch an mir und an dem Lande, in dem du dich aufgehalten hast.',
        24: 'Und Abraham sprach: Ich will schwören.',
        25: 'Und Abraham rügte den Abimelech über einen Wasserbrunnen, den Abimelechs Knechte ihm entrissen hatten.',
        26: 'Abimelech aber sprach: Ich weiß nicht, wer das Ding getan, und du hast mir es auch nicht angesagt, und ich hörte nichts davon bis heute.',
        27: 'Und Abraham nahm Kleinvieh und Rinder und gab sie Abimelech, und sie beide schlossen einen Bund.',
        28: 'Und Abraham stellte sieben Lämmer von dem Kleinvieh besonders.',
        29: 'Und Abimelech sprach zu Abraham: Was sollen diese sieben Lämmer, die du besonders gestellt hast?',
        30: 'Und er sprach: Die sieben Lämmer sollst du nehmen aus meiner Hand, auf daß es mir zum Zeugnis sei, daß ich diesen Brunnen gegraben habe.',
        31: 'Daher nennt man diesen Ort Beerschaba, weil sie beide dort einander geschworen haben.',
        32: 'Und sie schlossen einen Bund in Beerschaba. Und Abimelech und Pichol, der Oberste seines Heeres, machten sich auf und kehrten zurück in das Land der Philister.',
        33: 'Und Abraham pflanzte in Beerschaba einen Hain, und rief dort den Namen Jehovahs, des ewigen Gottes an.',
        34: 'Und Abraham hielt sich viele Tage im Lande der Philister auf.',
    },
    22: {
        1: 'Und es geschah nach diesen Dingen, daß Gott versuchte Abraham und sprach zu ihm: Abraham! Und er sagte: Hier bin ich!',
        2: 'Und Er sprach: Nimm doch deinen Sohn, deinen einzigen, den du liebst, den Isaak, und geh in das Land Moriah und opfere ihn auf daselbst als Brandopfer auf einem der Berge, den Ich dir sagen werde.',
        3: 'Und Abraham stand früh am Morgen auf, und sattelte seinen Esel und nahm seine zwei Jungen und seinen Sohn Isaak mit sich, und spaltete Holz zum Brandopfer, und machte sich auf und ging an den Ort, den ihm Gott gesagt hatte.',
        4: 'Am dritten Tage, da hob Abraham seine Augen auf und sah den Ort von ferne;',
        5: 'Und Abraham sprach zu seinen Jungen: Bleibet ihr hier mit dem Esel; und ich und der Junge wollen dorthin gehen und uns niederbeugen und zu euch zurückkehren.',
        6: 'Und Abraham nahm das Holz für das Brandopfer und legte es auf seinen Sohn Isaak. Und er nahm das Feuer und das Messer in seine Hand, und sie beide gingen miteinander.',
        7: 'Und Isaak sprach zu seinem Vater Abraham und sagte: Mein Vater! Und er sprach: Hier bin ich, mein Sohn. Und er sprach: Siehe das Feuer und das Holz, wo ist aber das Lamm zum Brandopfer?',
        8: 'Und Abraham sprach: Gott wird sich das Lamm zum Brandopfer ausersehen, mein Sohn; und sie beide gingen miteinander.',
        9: 'Und sie kamen an den Ort, den ihm Gott gesagt hatte; und Abraham baute dort den Altar und legte das Holz zurecht und band Isaak seinen Sohn und legte ihn auf den Altar über das Holz;',
        10: 'Und Abraham reckte seine Hand aus und nahm das Messer, um seinen Sohn zu schlachten.',
        11: 'Und der Engel Jehovahs rief ihm vom Himmel, und sprach: Abraham! Abraham! Und er sprach: Hier bin ich!',
        12: 'Und Er sprach: Recke deine Hand nicht aus über den Jungen, und tue ihm nichts; denn nun weiß Ich, daß du Gott fürchtest, und hast deinen Sohn, deinen einzigen, Mir nicht zurückbehalten.',
        13: 'Und Abraham hob seine Augen auf und sah, und siehe, ein Widder hinten mit seinen Hörnern im Dickicht verfangen. Und Abraham ging und nahm den Widder und opferte ihn auf zum Brandopfer statt seines Sohnes.',
        14: 'Und Abraham nannte den Namen dieses Ortes Jehovah sieht; daher man noch diesen Tages sagt: â¬SAuf dem Berge wird Jehovah sehenâ¬_.',
        15: 'Und der Engel Jehovahs rief Abraham zum zweitenmal vom Himmel,',
        16: 'Und sprach: Ich habe bei Mir geschworen, spricht Jehovah, weil du dies Ding getan und deinen Sohn, deinen einzigen, nicht zurückbehalten hast;',
        17: 'Will Ich gewißlich dich segnen und deinen Samen mehren, wie die Sterne der Himmel und wie den Sand am Ufer des Meeres, und dein Same soll das Tor seiner Feinde erblich besitzen.',
        18: 'Und gesegnet sollen werden in deinem Samen alle Völkerschaften der Erde, darum, daß du auf Meine Stimme gehört hast.',
        19: 'Und Abraham kehrte zu seinen Jungen zurück, und sie machten sich auf und gingen miteinander nach Beerschaba; und Abraham wohnte in Beerschaba.',
        20: 'Und es geschah nach diesen Dingen, daß dem Abraham angesagt wurde sprechend: Siehe, auch Milkah, sie hat deinem Bruder Nachor Söhne geboren:',
        21: 'Uz, seinen Erstgeborenen, und seinen Bruder Bus, und Kemuel, den Vater Arams,',
        22: 'Und Chesed und Chaso und Pildasch und Jidlaph und Bethuel.',
        23: 'Und Bethuel zeugte Rebekah. Diese acht gebar Milkah dem Nachor, Abrahams Bruder.',
        24: 'Und sein Kebsweib, deren Name war Reumah, und auch sie gebar Tebach und Gacham und Thachasch und Maachah.',
    },
    23: {
        1: 'Und es war das Leben Sarahs hundert Jahre und zwanzig Jahre und sieben Jahre. Dies sind die Jahre des Lebens Sarahs.',
        2: 'Und Sarah starb in Kiriath-Arba, das ist Chebron, im Lande Kanaan; und Abraham kam zu klagen um Sarah und sie zu beweinen.',
        3: 'Und Abraham stand auf über dem Angesichte seiner Toten und redete zu den Söhnen Cheths, und sprach:',
        4: 'Ein Fremdling und Beisasse bin ich bei euch. Gebt mir das Eigentum eines Grabes bei euch, daß ich meine Tote von meinem Angesichte weg begrabe.',
        5: 'Und die Söhne Cheths antworteten Abraham, und sprachen zu ihm:',
        6: 'Höre uns, mein Herr. Du bist ein Fürst Gottes in unserer Mitte. In der Auswahl unserer Gräber begrabe deine Tote. Kein Mann von uns wird dir sein Grab verwehren, daß du deine Tote begrabest.',
        7: 'Und Abraham stand auf und verbeugte sich vor dem Volke des Landes, vor den Söhnen Cheths.',
        8: 'Und er redete mit ihnen, und sprach: Wenn es in eurer Seele ist, daß ich die Tote von meinem Angesichte weg begrabe, so höret mich an, und vermittelt für mich bei Ephron, Zochars Sohn,',
        9: 'Daß er mir gebe die Höhle Machpelah, die sein ist, am Ende seines Feldes; um volles Silber gebe er sie mir in eurer Mitte zum Grabeseigentum.',
        10: 'Und Ephron saß in der Mitte der Söhne Cheths, und Ephron, der Chethiter, antwortete Abraham vor den Ohren der Söhne Cheths, vor allen, die zum Tore seiner Stadt eingingen, und sprach:',
        11: 'Nein, mein Herr, höre mich. Das Feld gebe ich dir, und die Höhle, die darinnen ist, gebe ich dir, vor den Augen der Söhne meines Volkes gebe ich sie dir, begrabe deine Tote.',
        12: 'Und Abraham verbeugte sich vor dem Volke des Landes,',
        13: 'Und er redete zu Ephron vor den Ohren des Volkes des Landes und sprach: Wolltest du doch auf mich hören. Ich gebe dir das Silber des Feldes. Nimm es von mir, und ich will meine Tote dort begraben.',
        14: 'Und Ephron antwortete Abraham und sprach zu ihm:',
        15: 'Mein Herr, höre mich: Ein Land, vierhundert Schekel Silbers wert, was ist das zwischen mir und dir? So begrabe nun deine Tote.',
        16: 'Und Abraham hörte auf Ephron; und Abraham wog Ephron das Silber dar, wie dieser vor den Ohren der Söhne Cheths geredet hatte, vierhundert Schekel Silbers, wie es beim Händler gangbar ist.',
        17: 'Und es ward erstanden das Feld Ephrons, das in Machpelah vor Mamre ist, das Feld und die Höhle die darin ist und jeder Baum auf dem Felde, die in all seiner Grenze umher,',
        18: 'Dem Abraham als Erworbenes vor den Augen der Söhne Cheths, vor allen, die zum Tor seiner Stadt eingingen.',
        19: 'Und danach begrub Abraham Sarah, sein Weib, in der Höhle des Feldes Machpelah, vor Mamre, das ist Chebron, im Lande Kanaan.',
        20: 'Und es war das Feld und die Höhle darin als Grabeigentum von den Söhnen Cheths von Abraham erstanden.',
    },
    24: {
        1: 'Und Abraham war alt, in die Tage gekommen, und Jehovah hatte Abraham in allem gesegnet.',
        2: 'Und Abraham sprach zu dem ältesten Knechte seines Hauses, der über alles, was er hatte, herrschte: Lege doch deine Hand unter meine Hüfte.',
        3: 'Und beschwöre dich bei Jehovah, dem Gott der Himmel und dem Gott der Erde, daß du meinem Sohne kein Weib nehmest von den Töchtern des Kanaaniters, in dessen Mitte ich wohne.',
        4: 'Sondern zu meinem Land und zu meinem Geburtsort sollst du gehen, und meinem Sohne Isaak ein Weib nehmen.',
        5: 'Und der Knecht sprach zu ihm: Vielleicht will das Weib mir nicht zu diesem Lande nachgehen. Soll ich dann deinen Sohn zu dem Land zurückbringen, aus dem du ausgezogen bist?',
        6: 'Und Abraham sprach zu ihm: Hüte dich, daß du meinen Sohn dahin zurückbringest.',
        7: 'Jehovah, der Gott der Himmel, Der mich vom Hause meines Vaters und von dem Lande meiner Geburt genommen und zu mir geredet, und mir geschworen hat und gesagt: Deinem Samen will Ich dieses Land geben, Der wird Seinen Engel vor dir senden, und du wirst von dorther für meinen Sohn ein Weib nehmen.',
        8: 'Und wenn das Weib dir nicht nachgehen will, so bist du dieses Schwurs ledig. Nur bringe meinen Sohn nicht dorthin zurück.',
        9: 'Und der Knecht legte seine Hand unter die Hüfte Abrahams, seines Herrn, und schwur ihm dieses Wort.',
        10: 'Und der Knecht nahm zehn Kamele von den Kamelen seines Herrn, und er ging und alles Gut seines Herrn war in seiner Hand, und er machte sich auf und zog gen Aram der beiden Flüsse, nach der Stadt Nachors.',
        11: 'Und er ließ die Kamele niederknien außerhalb der Stadt an dem Wasserbrunnen zur Abendzeit, zur Zeit, da die Wasserschöpferinnen herauskommen.',
        12: 'Und er sprach: Jehovah, Gott meines Herrn Abraham, laß es doch vor mir heute begegnen, und tue Barmherzigkeit meinem Herrn Abraham.',
        13: 'Siehe, ich stelle mich an die Wasserquelle, und die Töchter der Männer der Stadt kommen heraus, Wasser zu schöpfen.',
        14: 'Lasse es geschehen, daß das Mädchen, zu der ich spreche: Neige doch deinen Krug, daß ich trinke, und die dann sagt: Trinke, und ich will auch deine Kamele tränken, die sei, die Du für deinen Knecht, für Isaak, bestimmt hast, und daß ich daran erkenne, daß Du mit meinem Herrn Barmherzigkeit tuest.',
        15: 'Und es geschah, ehe er die Rede vollendet hatte, siehe, da kam Rebekah heraus, die dem Bethuel geboren ward, dem Sohne Milkahs, des Weibes von Nachor, dem Bruder Abrahams, und ihr Krug war auf ihrer Schulter.',
        16: 'Und das Mädchen war sehr gut anzusehen, eine Jungfrau, und kein Mann hatte sie erkannt. Und sie ging zur Quelle hinab und füllte ihren Krug, und kam herauf.',
        17: 'Und der Knecht lief ihr entgegen und sprach: Bitte, laß mich ein wenig Wasser aus deinem Kruge schlürfen.',
        18: 'Und sie sprach: Trinke, mein Herr, und sie eilte und ließ ihren Krug herab auf ihre Hand und tränkte ihn;',
        19: 'Und als sie ihn zu tränken vollendet, sprach sie: Auch deinen Kamelen will ich schöpfen, bis daß sie vollends getrunken haben.',
        20: 'Und sie eilte und ergoß ihren Krug in die Tränke, und lief wieder zum Brunnen, zu schöpfen, und schöpfte für alle seine Kamele.',
        21: 'Und der Mann staunte sie stillschweigend an, um zu erkennen, ob Jehovah seinen Weg gelingen lasse oder nicht.',
        22: 'Und es geschah, da die Kamele aufhörten zu trinken, da nahm der Mann einen goldenen Reif, vom Gewicht eines halben Schekels, und zwei Armbänder an ihre Hände, zehn Goldschekel an Gewicht.',
        23: 'Und er sprach: Wessen Tochter bist du? Bitte, sage mir an, ob im Hause deines Vaters ein Ort zum übernachten für uns ist?',
        24: 'Und sie sprach zu ihm: Ich bin Bethuels Tochter, des Sohns der Milkah, den sie Nachor gebar.',
        25: 'Und sie sprach zu ihm: Auch haben wir viel Stroh und Futter bei uns, auch einen Ort zum übernachten.',
        26: 'Und der Mann verneigte sich und beugte sich vor Jehovah,',
        27: 'Und sprach: Gesegnet sei Jehovah, der Gott meines Herrn Abraham, der von Seiner Barmherzigkeit und Wahrheit gegen meinen Herrn nicht gelassen; und mich hat Jehovah auf dem Weg nach dem Hause der Brüder meines Herrn geführt.',
        28: 'Und das Mädchen lief, und sagte es dem Hause ihrer Mutter an, gemäß diesen Worten.',
        29: 'Und Rebekah hatte einen Bruder, und sein Name war Laban; und Laban lief hinaus zu dem Manne an der Quelle.',
        30: 'Und es geschah, als er den Reif und die Armbänder an den Händen seiner Schwester sah, und als er hörte die Worte seiner Schwester Rebekah, die sprach: So hat der Mann zu mir geredet, da kam er zu dem Manne, und siehe, er stand bei den Kamelen an der Quelle.',
        31: 'Und er sprach: Komm, Gesegneter Jehovahs, warum stehst du draußen, und ich habe das Haus geräumt, und den Ort für die Kamele.',
        32: 'Und der Mann kam in das Haus; und er löste die Kamele und gab Stroh und Futter den Kamelen, und Wasser, zu waschen seine Füße und die Füße der Männer, die mit ihm waren.',
        33: 'Und man setzte ihm zu essen vor. Er sprach aber: Ich will nicht essen bis ich meine Worte geredet habe. Und er sprach: Rede.',
        34: 'Und er sprach: Ich bin Abrahams Knecht.',
        35: 'Und Jehovah hat meinen Herrn sehr gesegnet, und er ist groß geworden, und Er hat ihm Kleinvieh und Rinder und Silber und Gold und Knechte und Dienstmägde und Kamele und Esel gegeben.',
        36: 'Und Sarah, meines Herrn Weib, gebar, nachdem sie alt geworden, meinem Herrn einen Sohn, und er hat ihm alles gegeben, was er hatte.',
        37: 'Und mein Herr ließ mich schwören, und sagte: Du sollst meinem Sohne kein Weib nehmen von den Töchtern des Kanaaniters, in dessen Lande ich wohne.',
        38: 'Vielmehr sollst du zum Hause meines Vaters und zu meiner Familie gehen, und meinem Sohne ein Weib nehmen.',
        39: 'Und ich sprach zu meinem Herrn: Vielleicht wird das Weib mir nicht nachgehen.',
        40: 'Und er sprach zu mir: Jehovah, vor Dem ich gewandelt bin, wird Seinen Engel mit dir senden, und deinen Weg gelingen lassen, auf daß du meinem Sohne ein Weib von meiner Familie und aus dem Hause meines Vaters nehmest.',
        41: 'Dann bist du deines Eides ledig, wenn du zu meiner Familie kommst, und sie dir sie nicht geben; dann bist du deines Eides ledig.',
        42: 'Und ich kam heute zu der Quelle, und sprach: Jehovah, Gott meines Herrn Abraham, sei es doch, daß Du den Weg, auf dem ich gehe, gelingen lassest!',
        43: 'Siehe ich stelle mich an die Wasserquelle, und es geschehe, daß die Jungfrau, die herauskommt zu schöpfen, und zu der ich spreche, gib mir doch ein wenig Wasser zu trinken aus deinem Krug,',
        44: 'Und die zu mir sagt: Trinke du, und ich will auch deinen Kamelen schöpfen; daß sie das Weib sei, die Jehovah für den Sohn meines Herrn bestimmt hat.',
        45: 'Ehe ich vollendet zu reden zu meinem Herzen, und siehe, da kommt Rebekah heraus und ihr Krug auf ihrer Schulter und sie ging zur Quelle hinab und schöpfte; und ich sprach zu ihr: Gib mir doch zu trinken.',
        46: 'Und sie eilte und ließ ihren Krug von sich herab und sprach: Trinke, und ich will auch deine Kamele tränken; und ich trank und auch die Kamele tränkte sie.',
        47: 'Und ich fragte sie und sprach: Wessen Tochter bist du? Und sie sprach: Ich bin die Tochter Bethuels, des Sohns von Nachor, den ihm Milkah gebar. Und ich legte den Reif an ihre Nase und die Armbänder an ihre Hände.',
        48: 'Und ich verneigte und verbeugte mich vor Jehovah und segnete Jehovah, den Gott meines Herrn Abraham, Der mich auf den Weg der Wahrheit geführt, um die Tochter von meines Herrn Bruder seinem Sohne zu nehmen.',
        49: 'Und nun, wenn es bei euch ist Barmherzigkeit und Wahrheit an meinem Herrn zu tun, sagt es mir an, und wo nicht, so sagt es mir an, auf daß ich das Gesicht zur Rechten oder zur Linken wende.',
        50: 'Und Laban antwortete und Bethuel und sie sprachen: Von Jehovah geht das Wort aus, wir vermögen nicht zu dir zu reden, weder Böses noch Gutes.',
        51: 'Siehe Rebekah ist vor dir, nimm sie und gehe, und sie sei das Weib des Sohnes deines Herrn, wie Jehovah geredet hat.',
        52: 'Und es geschah, wie der Knecht Abrahams ihre Worte hörte, verbeugte er sich zur Erde vor Jehovah.',
        53: 'Und der Knecht brachte silberne Geräte und goldene Geräte und Kleider heraus und gab sie der Rebekah, und Kostbarkeiten gab er ihrem Bruder und ihrer Mutter.',
        54: 'Und sie aßen und tranken, er und die Männer, die mit ihm waren, und sie übernachteten. Und sie standen am Morgen auf und er sprach: Entsendet mich zu meinem Herrn.',
        55: 'Und ihr Bruder und ihre Mutter sprachen: Laß das Mädchen etwa zehn Tage bei uns bleiben, danach magst du gehen.',
        56: 'Er aber sprach zu ihnen: Haltet mich nicht auf; denn Jehovah hat meinen Weg gelingen lassen. Entsendet mich, daß ich zu meinem Herrn gehe.',
        57: 'Und sie sprachen: Wir wollen das Mädchen rufen und ihren Mund fragen.',
        58: 'Und sie riefen Rebekah, und sprachen zu ihr: Willst du mit diesem Manne gehen? Und sie sprach: Ich will gehen.',
        59: 'Und sie entsandten Rebekah, ihre Schwester und ihre Amme, und Abrahams Knecht und seine Männer.',
        60: 'Und sie segneten Rebekah, und sprachen zu ihr: Du bist unsere Schwester. Werde zu tausenden der Zehntausend, und dein Same besitze erblich das Tor seiner Hasser.',
        61: 'Und Rebekah machte sich auf und ihre Mädchen, und sie ritten auf den Kamelen und gingen dem Manne nach. Und der Knecht nahm Rebekah und ging.',
        62: 'Und Isaak kam von einem Gange nach dem Brunnen Lachai-Roi; und er wohnte im Lande des Mittags.',
        63: 'Und Isaak war, als sich der Abend wendete, in das Feld hinausgegangen zu sinnen, und er hob seine Augen auf, und sah, und siehe, Kamele kamen daher.',
        64: 'Und Rebekah hob ihre Augen auf, und sah Isaak, und sie glitt herab vom Kamel.',
        65: 'Und sie sprach zu dem Knechte: Wer ist der Mann da, der auf dem Feld geht uns entgegen? Und der Knecht sprach: Das ist mein Herr. Und sie nahm den Schleier und bedeckte sich.',
        66: 'Und der Knecht erzählte Isaak alles, was er getan hatte.',
        67: 'Und Isaak brachte sie herein in das Zelt seiner Mutter Sarah, und nahm Rebekah, und sie ward sein Weib, und er liebte sie. Und Isaak ward getröstet nach seiner Mutter.',
    },
    25: {
        1: 'Und Abraham nahm wieder ein Weib, und ihr Name war Keturah.',
        2: 'Und sie gebar ihm Simran und Jokschan und Medan und Midjan und Jischbak und Schuach.',
        3: 'Und Jokschan zeugte Scheba und Dedan, und die Söhne Dedans waren die Aschurim und die Letuschim und die Leumim.',
        4: 'Und die Söhne Midjans waren Ephah und Epher und Chanoch und Abidah und Eldaah. Alle diese waren Söhne Keturahs.',
        5: 'Und Abraham gab all das Seine dem Isaak.',
        6: 'Und den Söhnen der Kebsweiber, die Abraham hatte, gab Abraham Gaben, und entsandte sie weg von seinem Sohne Isaak, noch während er lebte, gegen Osten, in das Land des Ostens.',
        7: 'Und dies sind die Tage der Jahre des Lebens Abrahams, die er lebte: hundert Jahre und siebzig Jahre und fünf Jahre.',
        8: 'Und Abraham verschied und starb in gutem Greisenalter, alt und satt, und ward zu seinen Völkern versammelt.',
        9: 'Und es begruben ihn Isaak und Ismael, seine Söhne, in die Höhle Machpelah, nach dem Felde Ephrons, des Sohnes Zochar, des Chethiters, das ob dem Angesichte von Mamre ist.',
        10: 'Auf dem Felde, das Abraham von den Söhnen Chets erworben, da ward Abraham und Sarah, sein Weib, begraben.',
        11: 'Und es geschah nach dem Tode Abrahams, daß Gott segnete Isaak, seinen Sohn; und Isaak wohnte bei dem Brunnen Lachai-Roi.',
        12: 'Und dies sind die Geburten Ismaels, des Sohnes Abrahams, den Hagar die Ägypterin, die Dienstmagd Sarahs, dem Abraham gebar.',
        13: 'Und dies sind die Namen der Söhne Ismaels in ihren Namen nach ihren Geburten: der Erstgeborene Ismaels Nebajoth, und Kedar und Adbeel und Mibsam.',
        14: 'Und Mischma und Dumah und Massa.',
        15: 'Chadar und Thema, Jetur, Naphisch und Kedmah.',
        16: 'Dies sind sie, die Söhne Ismaels, und dies ihre Namen in ihren Gehöften und in ihren Zeltlagern zwölf Fürsten ihrer Volksstämme.',
        17: 'Und dies sind die Jahre des Lebens Ismaels: hundert Jahre und dreißig Jahre und sieben Jahre. Und er verschied und starb, und ward zu seinen Völkern versammelt.',
        18: 'Und sie wohnten von Chavilah bis Schur, das ob den Angesichten Ägyptens ist, wenn man nach Aschur kommt; vor allen seinen Brüdern fiel er.',
        19: 'Und dies sind die Geburten Isaaks des Sohnes Abrahams: Abraham zeugte Isaak.',
        20: 'Und Isaak war vierzig Jahre alt als er Rebekah, die Tochter Bethuels, des Aramiten von Padan Aram, die Schwester Labans, des Aramiten, sich zum Weibe nahm.',
        21: 'Und Isaak flehte wegen seines Weibes zu Jehovah; denn sie war unfruchtbar, und Jehovah ließ sich von ihm erflehen, und Rebekah, sein Weib, empfing.',
        22: 'Und die Stöhne stießen sich in ihrer Mitte, und sie sprach: Wenn dem so ist, warum bin ich so? Und sie ging Jehovah zu fragen.',
        23: 'Und Jehovah sprach zu ihr: Zwei Völkerschaften sind in deinem Leibe, und zwei Volksstämme werden sich aus deinen Eingeweiden trennen; und ein Volksstamm wird stärker als der andere Volksstamm und der Große wird dem Kleinen dienen.',
        24: 'Und die Tage erfüllten sich, daß sie gebären sollte, und siehe Zwillinge waren in ihrem Leibe.',
        25: 'Und der erste kam heraus, ganz rötlich, wie ein haariger Mantel, und sie nannten seinen Namen Esau.',
        26: 'Und nachher kam sein Bruder heraus, und seine Hand ergriff die Ferse Esaus und man nannte seinen Namen Jakob. Und Isaak war sechzig Jahre alt, da sie geboren wurden.',
        27: 'Und die Jungen wurden groß, und Esau war ein Mann kundig der Jagd, ein Mann des Feldes; und Jakob war ein untadeliger Mann, und wohnte in den Zelten.',
        28: 'Und Isaak liebte den Esau; denn Wildbret war in seinem Munde; und Rebekah liebte Jakob.',
        29: 'Und Jakob kochte ein Gemüse und Esau kam vom Felde und war matt.',
        30: 'Und Esau sprach zu Jakob: Laß mich doch von dem Roten, diesem Roten da kosten, denn ich bin matt. Deshalb nannte man seinen Namen Edom.',
        31: 'Und Jakob sprach: Verkaufe mir wie heute deine Erstgeburt.',
        32: 'Und Esau sagte: Siehe, ich gehe hin zu sterben, und wozu ist mir da die Erstgeburt?',
        33: 'Und Jakob sprach: Schwöre mir wie heute; und er schwur ihm, und verkaufte seine Erstgeburt dem Jakob.',
        34: 'Und Jakob gab dem Esau Brot und das Gemüse von Linsen; und er aß und trank und stand auf und ging. Und Esau verachtete die Erstgeburt.',
    },
    26: {
        1: 'Und es war eine Hungersnot im Lande außer der ersten Hungersnot, die in den Tagen Abrahams war; und Isaak ging zu Abimelech, dem Könige der Philister nach Gerar.',
        2: 'Und Jehovah erschien ihm, und sprach: Geh nicht nach Ägypten hinab, sondern wohne in dem Lande, das Ich dir sage.',
        3: 'Halte dich in diesem Lande auf, und Ich will mit dir sein und will dich segnen; denn dir und deinem Samen will Ich alle diese Lande geben und den Schwur bestätigen, den Ich Abraham, deinem Vater, geschworen habe.',
        4: 'Und Ich will mehren deinen Samen wie die Sterne der Himmel, und deinem Samen alle diese Lande geben, und es sollen in deinem Samen gesegnet werden alle Völkerschaften der Erde,',
        5: 'Infolge davon, daß Abraham Meiner Stimme gehorchte, und Meine Verordnung, Meine Gebote, Meine Satzungen und Meine Gesetze hielt.',
        6: 'Und Isaak wohnte in Gerar.',
        7: 'Und die Männer des Ortes fragten über sein Weib, und er sagte: Sie ist meine Schwester; denn er fürchtete sich zu sagen: Sie ist mein Weib, damit die Männer des Ortes ihn nicht erwürgeten ob Rebekah; denn sie war gut von Ansehen.',
        8: 'Und es geschah, als seine Tage dort sich verlängerten, daß Abimelech, König der Philister, durch das Fenster schaute und sah, und siehe, Isaak lachte mit Rebekah, seinem Weibe.',
        9: 'Und Abimelech rief den Isaak, und sprach: Siehe doch, sie ist dein Weib! und was sagtest du: sie ist meine Schwester? Und Isaak sprach zu ihm: Weil ich sagte, damit ich nicht sterbe wegen ihrer.',
        10: 'Und Abimelech sagte. Warum hast du uns das getan? Um ein kleines, so wäre einer vom Volke bei deinem Weibe gelegen, und du hättest eine Schuld über uns gebracht.',
        11: 'Und Abimelech gebot allem Volk und sprach: Wer diesen Mann und sein Weib berührt, der soll des Todes sterben.',
        12: 'Und Isaak säte in diesem Lande, und fand desselbigen Jahres hundert Maße; und Jehovah segnete ihn.',
        13: 'Und der Mann ward groß, und ging hin und ward groß, bis er sehr groß war.',
        14: 'Und er hatte Besitztum an Kleinvieh und Besitztum an Rindern, und viele Knechte, und die Philister beneideten ihn.',
        15: 'Und alle die Brunnen seines Vaters, welche die Knechte seines Vaters in den Tagen seines Vaters Abraham gegraben hatten, verstopften die Philister und füllten sie mit Staub.',
        16: 'Und Abimelech sprach zu Isaak: Gehe von uns, denn du bist uns zu sehr mächtig geworden.',
        17: 'Und Isaak ging von dannen, und lagerte im Bachtal Gerar, und wohnte allda.',
        18: 'Und Isaak grub wieder die Wasserbrunnen auf, die sie in den Tagen seines Vaters Abraham gegraben, die Philister aber nach dem Tode Abrahams verstopft hatten, und nannte sie mit Namen, nach den Namen, womit sein Vater sie genannt hatte.',
        19: 'Und die Knechte Isaaks gruben in dem Bachtal, und fanden dort einen Brunnen lebendigen Wassers.',
        20: 'Und die Hirten von Gerar haderten mit den Hirten Isaaks, und sprachen: Unser ist das Wasser. Und er nannte den Namen des Brunnens Esek, weil sie mit ihm gezankt hatten.',
        21: 'Und sie gruben einen anderen Brunnen, und sie haderten auch über diesen, und er nannte seinen Namen Sitnah.',
        22: 'Und von da zog er weiter, und grub einen anderen Brunnen, und über den haderten sie nicht; und er nannte seinen Namen Rechoboth, und sprach: Denn nun hat uns Jehovah breit werden lassen, und wir werden fruchtbar sein im Lande.',
        23: 'Und von da ging er hinauf gen Beerschaba.',
        24: 'Und Jehovah erschien ihm in derselben Nacht und sprach: Ich bin der Gott Abrahams deines Vaters, fürchte dich nicht; denn Ich bin mit dir und segne dich, und will deinen Samen mehren um Abrahams, Meines Knechtes, willen.',
        25: 'Und er baute allda einen Altar und rief den Namen Jehovahs an, und schlug daselbst sein Zelt auf. Und die Knechte Isaaks bohrten hier einen Brunnen.',
        26: 'Und Abimelech ging zu ihm von Gerar, und Achusath sein Genosse und Pichol, der Oberste seines Heeres.',
        27: 'Und Isaak sprach zu ihnen: Warum kommet ihr zu mir, und ihr hasset mich und habt mich von euch fortgesandt?',
        28: 'Sie aber sprachen: Wir haben gesehen, daß Jehovah mit dir ist, und da sagten wir: Es sei doch ein Eid zwischen uns, zwischen uns und zwischen dir, und wir wollen einen Bund mit dir schließen;',
        29: 'Daß du an uns nichts Böses tuest, wie wir dich nicht berührt, und wie wir an dir nur Gutes getan, und dich in Frieden entsandten: Nun bist du ein Gesegneter Jehovahs.',
        30: 'Und er machte ihnen ein Gastmahl, und sie aßen und tranken:',
        31: 'Und sie standen früh am Morgen auf und schwuren einander; und Isaak entsandte sie, und sie gingen von ihm im Frieden.',
        32: 'Und es geschah an diesem Tage, daß Isaaks Knechte kamen und sagten ihm an, wegen dem Brunnen, den sie gegraben, und sie sprachen zu ihm: Wir haben Wasser gefunden.',
        33: 'Und er nannte ihn Schibah, weshalb der Name der Stadt bis auf diesen Tag Beerscheba ist.',
        34: 'Und Esau war vierzig Jahre alt, und er nahm zum Weibe Jehudith, die Tochter Beeris, des Chethiters, und Basemath, die Tochter des Chethiters Elon.',
        35: 'Und sie waren für Isaak und Rebekah Bitterkeit des Geistes.',
    },
    27: {
        1: 'Und es geschah als Isaak alt geworden, und seine Augen getrübt wurden zum Sehen, daß er seinen größeren Sohn Esau rief und zu ihm sprach: Mein Sohn! Und er sprach: Siehe, hier bin ich!',
        2: 'Und er sprach: Siehe doch, ich bin alt geworden, ich weiß nicht den Tag meines Todes.',
        3: 'Und nun nimm doch dein Geräte, deinen Köcher und deinen Bogen, und geh hinaus auf das Feld und jage mir ein Wildbret,',
        4: 'Und mache mir ein schmackhaftes Gericht, wie ich es liebe, und bringe mir es herein, daß ich esse, auf daß dich meine Seele segne bevor ich sterbe.',
        5: 'Und Rebekah hörte, wie Isaak zu Esau, seinem Sohne, redete, und wie Esau auf das Feld ging, daß er ein Wildbret jage und es hereinbrächte.',
        6: 'Und Rebekah sagte zu ihrem Sohne Jakob und sprach: Siehe, ich hörte deinen Vater zu deinem Bruder Esau reden und sagen:',
        7: 'Bring mir ein Wildbret herein und mache mir ein schmackhaftes Gericht, daß ich esse, und dich segne vor Jehovah, bevor ich sterbe.',
        8: 'Und nun, mein Sohn, höre auf meine Stimme, was ich dir gebiete.',
        9: 'Geh doch zum Kleinvieh und hole mir von dort zwei gute Böcklein von den Ziegen, daß ich davon deinem Vater ein schmackhaftes Gericht mache, wie er es liebt.',
        10: 'Und du bringst es deinem Vater hinein, daß er esse, auf daß er dich segne, bevor er stirbt.',
        11: 'Und Jakob sprach zu Rebekah, seiner Mutter: Siehe, Esau, mein Bruder, ist ein behaarter Mann und ich bin ein glatter Mann.',
        12: 'Vielleicht betastet mich mein Vater und ich wäre in seinen Augen als Einer, der irreführt, und bringe Fluch herein über mich und nicht Segen.',
        13: 'Und seine Mutter sprach zu ihm: Auf mir sei dein Fluch, mein Sohn. Nur höre auf meine Stimme, und geh und hole mir.',
        14: 'Und er ging und holte, und brachte sie seiner Mutter, und seine Mutter machte ein schmackhaftes Gericht, wie es sein Vater liebte.',
        15: 'Und Rebekah nahm die köstlichen Kleider ihres größeren Sohnes Esau, die bei ihr im Hause waren, und ließ sie ihren kleineren Sohn Jakob anziehen.',
        16: 'Und sie tat ihm die Felle der Ziegenböcklein auf seine Hände und auf die Glätte seines Halses.',
        17: 'Und gab das schmackhafte Gericht und das Brot, das sie gemacht, in die Hand ihres Sohnes Jakob.',
        18: 'Und er ging hinein zu seinem Vater und sprach: Mein Vater! Und er sprach: Siehe, hier bin ich. Wer bist du, mein Sohn?',
        19: 'Und Jakob sprach zu seinem Vater: Ich bin Esau, dein Erstgeborener, ich habe getan, wie du zu mir geredet hast. Mache dich doch auf, sitze und iß von meinem Wildbret, auf daß mich segne deine Seele.',
        20: 'Und Isaak sprach zu seinem Sohne: Wie hast du so eilends gefunden, mein Sohn? Und er sprach: Jehovah, dein Gott, ließ es meinem Angesichte entgegenkommen.',
        21: 'Und Isaak sprach zu Jakob: Tritt doch herzu, daß ich dich betaste, mein Sohn, ob du da mein Sohn Esau bist oder nicht.',
        22: 'Und Jakob trat hinzu zu seinem Vater Isaak, und er betastete ihn und sprach: Die Stimme ist Jakobs Stimme, und die Hände sind Esaus Hände.',
        23: 'Und er erkannte ihn nicht; denn seine Hände waren wie die Hände Esaus, seines Bruders, haarig, und er segnete ihn.',
        24: 'Und er sprach, bist du da mein Sohn Esau? Und er sprach: Ich bin es.',
        25: 'Und er sprach: Reiche mir her, daß ich esse von dem Wildbret meines Sohnes, auf daß meine Seele dich segne. Und er reichte es ihm her und er aß, und er brachte ihm Wein herein und er trank.',
        26: 'Und Isaak, sein Vater, sprach zu ihm: Tritt doch herzu und küsse mich, mein Sohn.',
        27: 'Und er trat hinzu und küßte ihn. Und er roch den Geruch seiner Kleider, und segnete ihn und sprach: Siehe, der Geruch meines Sohnes ist wie der Geruch des Feldes, das Jehovah gesegnet hat.',
        28: 'Und Gott gebe dir von dem Tau des Himmels und von dem Fett der Erde und viel Korn und Most.',
        29: 'Völker sollen dir dienen und Volksstämme sich vor dir verbeugen. Sei ein Gebieter über deine Brüder, und deiner Mutter Söhne sollen sich vor dir verbeugen. Verflucht sei, wer dich verflucht! Und gesegnet sei, wer dich segnet!',
        30: 'Und es geschah, als Isaak Jakobs Segen vollendet und Jakob kaum von dem Angesichte seines Vaters Isaak hinausgegangen war, daß Esau, sein Bruder, kam von seiner Jagd.',
        31: 'Und auch er machte ein schmackhaftes Gericht, und brachte es seinem Vater herein und sprach zu seinem Vater: Mein Vater mache sich auf und esse von dem Wildbret seines Sohnes, auf daß deine Seele mich segne.',
        32: 'Und sein Vater Isaak sprach zu ihm: Wer bist du? Und er sprach: Ich bin dein Sohn, dein Erstgeborener, Esau.',
        33: 'Und Isaak zitterte mir sehr großem Zittern und sprach: Wer war dann der, so das Wildbret jagte und mir hereinbrachte? Und ich aß von allem ehe du kamst und segnete ihn. Gesegnet soll er auch sein.',
        34: 'Wie Esau die Worte seines Vaters hörte, tat er einen großen, sehr bitteren Schrei, und sprach zu seinem Vater: Segne mich, auch mich, mein Vater.',
        35: 'Und er sprach: Dein Bruder ist trüglich gekommen und hat deinen Segen genommen.',
        36: 'Und er sprach: Hat man seinen Namen nicht Jakob genannt? Und diese zweimal hat er mich überlistet. Meine Erstgeburt hat er genommen, und siehe, jetzt nimmt er meinen Segen. Und er sprach: Hast du denn keinen Segen mehr für mich vorbehalten?',
        37: 'Und Isaak antwortete und sprach zu Esau: Siehe, zum Gebieter habe ich ihn über dich gesetzt, und alle seine Brüder ihm zu Knechten gegeben, mit Korn und Most ihn gekräftigt. Und nun, was soll ich tun für dich, mein Sohn?',
        38: 'Und Esau sprach zu seinem Vater: Hattest du nur diesen einen Segen, mein Vater? Segne mich, auch mich, mein Vater! Und Esau hob auf seine Stimme und weinte.',
        39: 'Und sein Vater Isaak antwortete und sprach zu ihm: Siehe, vom Fetten des Landes wird dein Wohnsitz sein, und von dem Tau des Himmels von oben.',
        40: 'Und du wirst ob deinem Schwerte leben und deinem Bruder dienen. Und es wird geschehen, wenn du herrschen wirst, daß du sein Joch von deinem Halse abreißest.',
        41: 'Und Esau grollte dem Jakob ob dem Segen, womit sein Vater ihn gesegnet hatte; und Esau sprach in seinem Herzen: Es nahen die Tage der Trauer für meinen Vater und ich erwürge Jakob, meinen Bruder.',
        42: 'Und es wurden Rebekah die Worte Esaus, ihres größeren Sohnes angesagt, und sie sandte und rief Jakob, ihren kleineren Sohn, und sprach zu ihm: Siehe, Esau, dein Bruder, vertröstet sich wegen dir und will dich erwürgen.',
        43: 'Und nun, mein Sohn, höre auf meine Stimme und mache dich auf, entweiche zu meinem Bruder Laban nach Charan,',
        44: 'Und bleibe einige Tage bei ihm, bis sich der Grimm deines Bruders zurückgewendet hat;',
        45: 'Bis sich zurückgewendet hat der Zorn deines Bruders wider dich, und er vergessen hat, was du ihm getan, und ich werde senden und dich von dort holen. Warum sollte ich auch euer beider an einem Tage beraubt werden?',
        46: 'Und Rebekah sprach zu Isaak: Mir ist das Leben zum Überdruß vor den Töchtern Cheths; wenn Jakob ein Weib nehmen soll von den Töchtern Cheths, wie die da von den Töchtern des Landes, was soll mir dann das Leben?',
    },
    28: {
        1: 'Und Isaak rief dem Jakob und er segnete ihn und gebot ihm und sprach zu ihm: Du sollst dir kein Weib von den Töchtern Kanaans nehmen.',
        2: 'Mache dich auf, geh nach Padan Aram zu dem Hause Bethuels, des Vaters deiner Mutter, und nimm dir von da ein Weib von den Töchtern Labans, des Bruders deiner Mutter.',
        3: 'Und Gott Schaddai wird dich segnen und dich fruchtbar machen und dich mehren, daß du zu einer Versammlung von Völkern werdest.',
        4: 'Und wird dir geben den Segen Abrahams, dir und deinem Samen mit dir, auf daß du das Land deiner Wanderungen erblich besitzest, das Gott dem Abraham gegeben hat.',
        5: 'Und Isaak entsandte den Jakob, und er ging nach Padan Aram zu Laban, dem Sohne Bethuels, des Aramiters, dem Bruder der Rebekah, der Mutter Jakobs und Esaus.',
        6: 'Und Esau sah, daß Isaak den Jakob segnete und nach Padan Aram sandte, um sich von dort ein Weib zu holen, und ihm mit seinem Segen gebot und sprach: Du sollst dir kein Weib von den Töchtern Kanaans nehmen;',
        7: 'Und daß Jakob seinem Vater und seiner Mutter gehorchte und nach Padan Aram ging;',
        8: 'Und Esau sah, daß die Töchter Kanaans böse waren in den Augen seines Vaters Isaak;',
        9: 'Und Esau ging zu Ismael, und nahm über seine Weiber Machalath, die Tochter Ismaels, des Sohns von Abraham, eine Schwester des Nebajoth zum Weibe.',
        10: 'Und Jakob ging aus von Beerschaba und ging nach Charan.',
        11: 'Und er stieß auf einen Ort und übernachtete daselbst, denn die Sonne war untergegangen; und er nahm von den Steinen des Ortes und legte sie zu seinen Häupten, und legte sich an demselben Orte nieder.',
        12: 'Und es träumte ihm, und siehe, eine Leiter war auf die Erde gestellt und ihre Spitze berührte den Himmel, und siehe, die Engel Gottes stiegen auf und stiegen nieder daran.',
        13: 'Und siehe, Jehovah stand oben darauf und sprach: Ich bin Jehovah, der Gott Abrahams, deines Vaters, und der Gott Isaaks. Das Land, darauf du liegst, will Ich dir und deinem Samen geben.',
        14: 'Und dein Same soll wie der Staub der Erde sein, und du sollst hervorbrechen nach dem Meere zu und nach Osten und nach Norden und nach Mittag; und alle Familien des Bodens sollen in dir und deinem Samen gesegnet werden.',
        15: 'Und siehe, Ich bin mit dir, und werde dich behüten überall, wohin du gehst, und dich zurückbringen auf diesen Boden; denn Ich werde dich nicht verlassen, bis daß Ich getan habe, was Ich zu dir geredet habe.',
        16: 'Und Jakob erwachte von seinem Schlaf und sprach: Fürwahr, Jehovah ist an diesem Orte und ich wußte es nicht.',
        17: 'Und er fürchtete sich und sprach: Wie furchtbar ist dieser Ort! Hier ist nichts denn Gottes Haus; und dies ist das Tor des Himmels.',
        18: 'Und Jakob stand früh am Morgen auf, und nahm den Stein, den er zu seinen Häupten gelegt hatte und setzte ihn auf zu einer Denksäule, und goß Öl oben darauf.',
        19: 'Und er nannte den Namen dieses Ortes Bethel. Früher aber war der Name der Stadt Lus.',
        20: 'Und Jakob gelobte ein Gelübde und sprach: Wenn Gott mit mir sein und mich behüten wird auf diesem Wege, den ich gehe, und mir Brot zu essen und ein Kleid zum Anziehen gibt,',
        21: 'Und ich in Frieden zum Hause meines Vaters zurückkehre, so soll Jehovah mir zum Gotte sein;',
        22: 'Und dieser Stein, den ich zur Denksäule gesetzt, soll sein ein Gotteshaus; und alles, was Du mir geben wirst, will ich Dir verzehnten.',
    },
    29: {
        1: 'Und Jakob hob seine Füße auf, und ging nach dem Lande der Söhne des Ostens.',
        2: 'Und er sah, und siehe, ein Brunnen auf dem Felde, und siehe, dabei waren drei Herden Kleinvieh gelagert; denn von diesem Brunnen tränkten sie die Herden; und ein großer Stein war auf der Mündung des Brunnens.',
        3: 'Und dorthin versammelten sich alle Herden, und sie wälzten den Stein von der Mündung des Brunnens und tränkten das Kleinvieh, und brachten den Stein zurück auf die Mündung des Brunnens an seinen Ort.',
        4: 'Und Jakob sprach zu ihnen: Meine Brüder, woher seid ihr? Und sie sprachen: Von Charan sind wir.',
        5: 'Und er sprach zu ihnen: Kennet ihr Laban, den Sohn Nachors? Und sie sprachen: Wir kennen ihn.',
        6: 'Und er sprach zu ihnen: Hat er Frieden? Und sie sprachen: Frieden; und siehe, Rachel, seine Tochter, kommt mit dem Kleinvieh.',
        7: 'Und er sprach: Siehe, der Tag ist noch lang, es ist nicht die Zeit, die Viehherden zu versammeln. Tränket das Kleinvieh und gehet, weidet.',
        8: 'Und sie sprachen: Wir können nicht, bevor die Herden alle versammelt sind, da wälzen sie den Stein von der Mündung des Brunnens und wir tränken das Kleinvieh.',
        9: 'Noch redete er mit ihnen, da kam Rachel mit dem Kleinvieh ihres Vaters; denn sie war Hirtin.',
        10: 'Und es geschah, wie Jakob Rachel, die Tochter Labans, des Bruders seiner Mutter, und das Kleinvieh Labans, des Bruders seiner Mutter sah, da trat Jakob herzu und wälzte den Stein von der Mündung des Brunnens und tränkte das Kleinvieh Labans, des Bruders seiner Mutter.',
        11: 'Und Jakob küßte Rachel, und hob seine Stimme auf und weinte.',
        12: 'Und Jakob sagte der Rachel an, daß er ein Bruder ihres Vaters und ein Sohn Rebekahs sei. Und sie lief und sagte es ihrem Vater an.',
        13: 'Und es geschah, als Laban die Kunde von Jakob, dem Sohne seiner Schwerster, hörte, da lief er ihm entgegen und umarmte ihn und küßte ihn, und brachte ihn in sein Haus herein. Und er erzählte Laban alle diese Worte.',
        14: 'Und Laban sprach zu ihm: Fürwahr, du bist mein Bein und mein Fleisch, und er wohnte bei ihm einen Monat von Tagen.',
        15: 'Und Laban sprach zu Jakob: Solltest du, weil du mein Bruder bist, mir umsonst dienen? Sage mir an, was soll dein Lohn sein?',
        16: 'Und Laban hatte zwei Töchter, die ältere mit Namen Leah und die Jüngere mit Namen Rachel.',
        17: 'Und Leahs Augen waren blöde, Rachel aber war schön von Gestalt und schön von Ansehen.',
        18: 'Und Jakob liebte Rachel und sprach: Ich will dir sieben Jahre um Rachel, deine jüngste Tochter, dienen.',
        19: 'Und Laban sprach: Es ist besser, ich gebe sie dir, als daß ich sie einem anderen Manne gebe; bleibe bei mir.',
        20: 'Und Jakob diente um Rachel sieben Jahre; und sie waren in seinen Augen wie einige Tage, in seiner Liebe für sie.',
        21: 'Und Jakob sprach zu Laban: Gib mir mein Weib; denn meine Tage sind erfüllt, daß ich zu ihr komme.',
        22: 'Und Laban versammelte alle Männer des Ortes und machte ein Gastmahl.',
        23: 'Und es geschah am Abend, da nahm er Leah, seine Tochter, und brachte sie zu ihm hinein, und er ging zu ihr ein.',
        24: 'Und Laban gab ihr Silpah seine Dienstmagd, seiner Tochter Leah zur Dienstmagd.',
        25: 'Und es war am Morgen - siehe, da war es Leah. Und er sprach zu Laban: Warum hast du mir das getan? Habe ich nicht bei dir um Rachel gedient, und warum hast du mich betrogen?',
        26: 'Und Laban sprach: Man tut nicht also in unserem Orte, daß man die Jüngere gibt vor der Erstgeborenen.',
        27: 'Erfülle diese Woche, dann wollen wir dir auch diese geben um den Dienst, den du bei mir noch andere sieben Jahre dienen sollst.',
        28: 'Und Jakob tat also, und erfüllte diese Woche, und er gab ihm Rachel, seine Tochter, ihm zum Weibe.',
        29: 'Und Laban gab Rachel, seiner Tochter, seine Dienstmagd Bilhah, ihr zur Dienstmagd.',
        30: 'Und er kam auch zu Rachel und liebte auch die Rachel mehr denn die Leah, und diente bei ihm noch andere sieben Jahre.',
        31: 'Und Jehovah sah, daß Leah gehaßt wurde und Er öffnete ihren Mutterschoß, Rachel aber war unfruchtbar.',
        32: 'Und Leah empfing und gebar einen Sohn und sie nannte seinen Namen Ruben; denn, sprach sie, Jehovah hat mein Elend gesehen. Denn jetzt wird mich mein Mann lieben.',
        33: 'Und sie empfing wieder und gebar einen Sohn, und sprach: Jehovah hat gehört, daß ich gehaßt bin und hat mir auch diesen gegeben, und nannte seinen Namen Schimeon.',
        34: 'Und sie empfing wieder und gebar einen Sohn, und sprach: Jetzt, diesmal wird mein Mann mir anhangen, denn ich habe ihm drei Söhne geboren; deshalb nannte sie seinen Namen Levi.',
        35: 'Und sie empfing wieder und gebar einen Sohn, und sprach: Diesmal bekenne ich Jehovah; daher nannte sie seinen Namen Jehudah, und sie hörte auf zu gebären.',
    },
    30: {
        1: 'Und Rachel sah, daß sie dem Jakob nicht gebar, und Rachel eiferte wider ihrer Schwester und sprach zu Jakob: Gib mir Söhne und wo nicht, so sterbe ich.',
        2: 'Und es entbrannte Jakobs Zorn wider Rachel, und er sprach: Bin ich an Gottes Statt, Der dir die Frucht des Leibes vorenthält?',
        3: 'Und sie sprach: Siehe, da ist meine Magd Bilhah. Komm zu ihr, auf daß sie auf meinen Knien gebäre, und auch ich aus ihr aufgebaut werde.',
        4: 'Und sie gab ihm Bilhah, ihre Dienstmagd zum Weibe, und Jakob kam zu ihr.',
        5: 'Und Bilhah empfing und gebar dem Jakob einen Sohn.',
        6: 'Und Rachel sprach: Gott hat für mich gerechtet und auch auf meine Stimme gehört und mir einen Sohn gegeben; daher nannte sie seinen Namen Dan.',
        7: 'Und Bilhah, Rachels Dienstmagd, empfing wieder und gebar Jakob einen zweiten Sohn.',
        8: 'Und Rachel sprach: Mit dem Ringen Gottes habe ich mit meiner Schwester gerungen, auch sie übermocht, und nannte seinen Namen Naphthali.',
        9: 'Und Leah sah, daß sie aufhörte zu gebären, und sie nahm Silpah, ihre Dienstmagd und gab sie Jakob zum Weibe.',
        10: 'Und Silpah, Leahs Dienstmagd, gebar Jakob einen Sohn.',
        11: 'Und Leah sprach: Mit einer Schar! und sie nannte seinen Namen Gad.',
        12: 'Und Silpah, Leahs Dienstmagd, gebar dem Jakob einen zweiten Sohn.',
        13: 'Und Leah sprach: Zu meiner Seligkeit! denn selig preisen mich die Töchter; und sie nannte seinen Namen Ascher.',
        14: 'Und Ruben ging in den Tagen der Weizenernte und fand Dudaim auf dem Felde und brachte sie Leah, seiner Mutter. Und Rachel sprach zu Leah: Gib mir doch von den Dudaim deines Sohnes.',
        15: 'Und sie sprach zu ihr: ist es ein Kleines, daß du meinen Mann genommen hast, daß du auch die Dudaim meines Sohnes nehmen willst? Und Rachel sagte: Darum soll er denn diese Nacht bei dir liegen für deines Sohnes Dudaim.',
        16: 'Und Jakob kam am Abend vom Felde, und Leah ging hinaus ihm entgegen und sprach: Zu mir sollst du kommen, denn ich habe dich mit meines Sohnes Dudaim gedingt. Und er lag diese Nacht bei ihr.',
        17: 'Und Gott erhörte Leah, und sie empfing und gebar dem Jakob einen fünften Sohn.',
        18: 'Und Leah sprach: Gott hat mir dafür meinen Lohn gegeben, daß ich meine Dienstmagd meinem Manne gab, und sie nannte seinen Namen Isaschar.',
        19: 'Und Leah empfing wieder und gebar dem Jakob den sechsten Sohn.',
        20: 'Und Leah sprach: Gott hat mir eine gute Bescherung beschert. Diesmal wird mein Mann mir beiwohnen, denn sechs Söhne habe ich ihm geboren; und sie nannte seinen Namen Sebulon.',
        21: 'Und danach gebar sie eine Tochter, und sie nannte ihren Namen Dinah.',
        22: 'Und Gott gedachte der Rachel, und Gott hörte auf sie und öffnete ihren Mutterschoß.',
        23: 'Und sie empfing und gebar einen Sohn und sprach: Gott hat meine Schmach von mir weggenommen.',
        24: 'Und sie nannte seinen Namen Joseph, und sprach: Jehovah wolle mir einen anderen Sohn hinzutun.',
        25: 'Und es geschah, als Rachel den Joseph geboren hatte, da sprach Jakob zu Laban: Entsende mich, daß ich nach meinem Orte und meinem Lande gehe.',
        26: 'Gib mir meine Weiber und meine Kinder, für die ich dir gedient, und ich will gehen; denn du weißt meinen Dienst, damit ich dir gedient.',
        27: 'Und Laban sprach zu ihm: Möchte ich doch Gnade in deinen Augen finden. Ich deute mir, daß Jehovah deinetwegen mich gesegnet hat.',
        28: 'Und er sprach: Benenne deinen Lohn bei mir, und ich gebe dir ihn.',
        29: 'Und er sprach zu ihm: Du weißt, wie ich dir gedient habe, und was deine Vieherde unter mir geworden ist.',
        30: 'Denn wenig war es, das du vor mir hattest, und es ist zur Menge hervorgebrochen, und Jehovah hat dich durch meinen Fuß gesegnet, und nun, wann soll auch ich etwas für mein Haus tun?',
        31: 'Und er sprach: Was soll ich dir geben? Und Jakob sprach: Du sollst mir nichts geben. Wenn du mir tust nach diesem Worte, so kehre ich zurück, weide dein Kleinvieh, hüte es.',
        32: 'Ich will heute durch all dein Kleinvieh durchgehen, und daraus jedes gesprenkelte und gefleckte Lamm, und jedes schwarze Lamm unter den Schafen, und jedes gefleckte und gesprenkelte unter den Ziegen wegnehmen; und soll mein Lohn sein.',
        33: 'Und antworten soll für mich meine Gerechtigkeit am morgenden Tage, wenn du über meinen Lohn, der vor dir ist, kommen wirst. Alles, was nicht gesprenkelt und gefleckt unter den Ziegen und schwarz unter den Schafen ist, das sei bei mir gestohlen.',
        34: 'Und Laban sprach: Siehe, es geschehe nach deinem Worte.',
        35: 'Und an demselben Tage nahm er die bunten und gefleckten Böcke und alle gesprenkelten und gefleckten Ziegen, alle, an denen etwas Weißes war, weg, und alles Schwarze unter den Schafen, und gab sie in die Hand seiner Söhne.',
        36: 'Und er setzte einen Weg von drei Tagen zwischen sich und zwischen Jakob. Und Jakob weidete des übrige Kleinvieh Labans.',
        37: 'Und Jakob nahm sich frische Stöcke von Weißpappel und Hasel und Platane, und schälte weiße Streifen darein, so daß das Weiße an den Stöcken entblößt wurde.',
        38: 'Und er stellte die Stöcke, die er geschält hatte, in die Rinnen in den Tränken des Wassers, zu denen das Kleinvieh kam, um zu trinken, dem Kleinvieh gegenüber auf, daß sie brünstig würden, wenn sie kämen zu trinken.',
        39: 'Und das Kleinvieh wurde brünstig bei den Stöcken, und das Kleinvieh gebar bunte, gesprenkelte und gefleckte.',
        40: 'Und die Schafe trennte Jakob und wandte die Angesichter des Kleinviehs gegen das Bunte und alles Schwarze unter dem Kleinvieh Labans, und er stellte Herden für sich besonders, und er stellte sie nicht zu Labans Kleinvieh.',
        41: 'Und es geschah, daß, sobald die Feisteren der Herde brünstig wurden, Jakob die Stöcke vor die Augen der Herde in die Rinnen legte, damit sie bei den Stöcken brünstig würden.',
        42: 'Aber bei den Späteren des Kleinviehs legte er sie nicht hinein, und so wurden die Späteren Labans, und die Feisteren des Jakob.',
        43: 'Und es breitete sich der Mann sehr, sehr aus, und hatte viel Kleinvieh und Dienstmägde und Knechte und Kamele und Esel.',
    },
    31: {
        1: 'Und er hörte die Worte der Söhne Labans, die sagten: Jakob hat alles, was unseres Vaters war, genommen, und von dem, was unseres Vaters war, hat er sich all diese Herrlichkeit gemacht.',
        2: 'Und Jakob sah das Angesicht Labans, und siehe, es war nicht mehr mit ihm wie gestern und ehegestern.',
        3: 'Und Jehovah sprach zu Jakob: Kehre zurück in das Land deiner Väter und in deinen Geburtsort, und Ich will mit dir sein.',
        4: 'Und Jakob sandte und rief Rachel und Leah ins Feld zu seinem Kleinvieh;',
        5: 'Und er sprach zu ihnen: Ich sehe, daß eures Vaters Angesicht gegen mich nicht ist wie gestern und ehegestern: und der Gott meines Vaters ist mit mir gewesen.',
        6: 'Und ihr wisset, daß ich mit all meiner Kraft eurem Vater gedient habe.',
        7: 'Aber euer Vater hat mich hintergangen und meinen Lohn zehnmal abgeändert; aber Gott gab nicht zu, daß er mir Böses täte.',
        8: 'Wenn er sagte: Gesprenkelte seien dein Lohn, so hat alles Kleinvieh bunte geboren.',
        9: 'Und Gott entriß die Viehherden eures Vaters und gab sie mir.',
        10: 'Und es geschah zur Zeit der Brunst des Kleinviehs, daß ich meine Augen aufhob und sah im Traum, und siehe: die Böcke, welche das Kleinvieh besprangen, waren bunt und gesprenkelt und getüpfelt.',
        11: 'Und der Engel Gottes sprach zu mir im Traum: Jakob! Und ich sprach: Siehe, hier bin ich!',
        12: 'Und Er sprach: Hebe doch deine Augen auf und siehe: Alle Böcke, welche das Kleinvieh bespringen, sind bunt und gesprenkelt und getüpfelt; denn Ich habe alles gesehen, was Laban dir tut.',
        13: 'Ich bin der Gott Bethels, woselbst du die Denksäule gesalbt, woselbst du Mir ein Gelübde gelobtest. Mache dich nun auf gehe aus von diesem Lande, und kehre nach dem Lande deiner Geburt zurück.',
        14: 'Und Rachel und Leah antworteten und sprachen zu ihm: Haben wir noch ein Teil und Erbe in unseres Vaters Haus?',
        15: 'Wird unser von ihm nicht als der Auswärtigen gedacht? denn er hat uns verkauft, und unser Silber verzehrt.',
        16: 'Denn aller Reichtum, den Gott unsrem Vater entrissen hat, gehört uns und unseren Söhnen. Und nun, alles, was Gott zu dir gesprochen hat, das tue.',
        17: 'Und Jakob machte sich auf und hob seine Söhne und seine Weiber auf die Kamele.',
        18: 'Und trieb hinweg all seine Viehherden und all seine Habe, die er gewonnen, und die Viehherden, die er erworben, so er in Padan Aram gewonnen; um zu Isaak, seinem Vater, in das Land Kanaan zu kommen.',
        19: 'Laban aber war gegangen, sein Kleinvieh zu scheren, und Rachel stahl die Theraphim, die ihrem Vater gehörten.',
        20: 'Und Jakob stahl das Herz Labans, des Aramiters, indem er ihm nicht ansagte, daß er entweiche.',
        21: 'Und er entwich, er und alles, das er hatte, und machte sich auf und setzte über den Fluß und richtete sein Angesicht nach dem Berge Gilead.',
        22: 'Und man sagte am dritten Tage Laban an, daß Jakob entwichen sei.',
        23: 'Und er nahm seine Brüder mit sich, und setze ihm nach sieben Tagereisen, und holte ihn ein am Berge Gilead.',
        24: 'Gott aber kam zu dem Aramiter Laban im Traum in der Nacht und sprach zu ihm: Hüte dich, daß du nicht mit Jakob vom Guten bis zum Bösen redest.',
        25: 'Und Laban erreichte den Jakob. Jakob aber hatte sein Zelt auf dem Berge aufgeschlagen, und Laban schlug mit seinen Brüdern sein Zelt auf dem Berge Gilead auf.',
        26: 'Und Laban sprach zu Jakob: Was hast du getan, und hast mein Herz gestohlen und meine Töchter wie mit dem Schwert gefangen weggeführt?',
        27: 'Warum bist du heimlich entwichen, und hast mich bestohlen und mir nicht angesagt, auf daß ich dich mit Fröhlichkeit und mit Gesängen, mit Pauke und mit Harfe entlassen hätte?',
        28: 'Und hast mir nicht gestattet meine Söhne und meine Töchter zu küssen? Nun hast du närrisch gehandelt in deinem Tun.',
        29: 'Es wäre bei Gott in meiner Hand, euch Böses zu tun, aber der Gott eures Vaters hat gestern Nacht zu mir gesprochen und gesagt: Hüte dich mit Jakob vom Guten bis zum Bösen zu reden.',
        30: 'Und nun, bist du gegangen, weil du dir das Haus deines Vaters ersehnt hast - warum aber hast du mir meine Götter gestohlen?',
        31: 'Und Jakob antwortete und sprach zu Laban: Weil ich fürchtete und sprach: Daß du mir deine Töchter nicht entreißest.',
        32: 'Bei wem du aber deine Götter findest, der soll nicht am Leben bleiben vor unseren Brüdern. Besieh dir, was ich bei mir habe, und nimm es dir. Denn Jakob wußte nicht, daß Rachel sie gestohlen hatte.',
        33: 'Und Laban kam in das Zelt Jakobs und in das Zelt Leahs und in das Zelt der beiden Mägde und fand nichts. Und er ging heraus von dem Zelte Leahs und kam in Rachels Zelt.',
        34: 'Rachel aber hatte die Theraphim genommen und unter die Kamelsstreue gelegt und saß darauf. Und Laban betastete alles im Zelt und fand nicht.',
        35: 'Und sie sprach zu ihrem Vater: Es entbrenne nicht Zorn in den Augen meines Herrn, daß ich nicht aufzustehen vermag vor dir, denn es geht mir nach der Weiber Weise; und er durchsuchte es, fand aber die Theraphim nicht.',
        36: 'Und Jakob entbrannte und er haderte mit Laban; und Jakob antwortete und sprach zu Laban: Was ist meine Übertretung, was ist meine Sünde, daß du hinter mir nachgejagt?',
        37: 'Du hast alle meine Gefäße betastet, was hast du von allen Gefäßen deines Hauses gefunden? Lege es her hier vor meine Brüder und vor deine Brüder, sie mögen bestimmen zwischen uns beiden!',
        38: 'Diese zwanzig Jahre bin ich bei dir gewesen. Deine Mutterschafe und deine Ziegen haben nicht fehlgeboren, und die Widder deines Kleinviehs habe ich nicht gegessen.',
        39: 'Das Zerfleischte habe ich dir nicht hereingebracht; ich habe es erstattet. Von meiner Hand hast du gesucht das bei Tag Gestohlene und das bei Nacht Gestohlene.',
        40: 'Und so bin ich gewesen, bei Tag verzehrte mich die Hitze, und der Frost bei Nacht; und der Schlaf entfloh von meinen Augen.',
        41: 'Diese zwanzig Jahre sind es, daß ich in deinem Hause diente, vierzehn Jahre um deine zwei Töchter und sechs Jahre um dein Kleinvieh, und zehn Mal hast du meinen Lohn abgeändert.',
        42: 'Wäre nicht der Gott meines Vaters, der Gott Abrahams, und der Schauer Isaaks mit mir gewesen, du hättest mich jetzt leer entsandt. Mein Elend und die Ermüdung meiner Hände hat Gott gesehen, und gestern Nacht hat Er es gerügt.',
        43: 'Und Laban antwortete und sprach zu Jakob: Die Töchter sind meine Töchter und die Söhne sind meine Söhne, und das Kleinvieh ist mein Kleinvieh, und alles, was du siehst, ist mein. Aber meinen Töchtern, was sollte ich ihnen heute tun, oder ihren Söhnen, die sie geboren?',
        44: 'Und nun, geh zu, wir wollen einen Bund schließen, ich und du, und er soll zum Zeugnis sein zwischen mir und zwischen dir.',
        45: 'Und Jakob nahm einen Stein und richtete ihn zu einer Denksäule empor.',
        46: 'Und Jakob sprach zu seinen Brüdern: Leset Steine auf, und sie nahmen Steine und machten einen Haufen, und aßen dort über dem Haufen.',
        47: 'Und Laban nannte ihn Jegar Sahaduta und Jakob nannte ihn Gal-Eed.',
        48: 'Und Laban sprach: Dieser Haufen sei Zeuge zwischen mir und dir an diesem Tage. Daher hieß man ihn Gal-Eed.',
        49: 'Und auch Mizpah denn er sagte: Jehovah wache zwischen mir und zwischen dir, wenn einer wird dem andern verborgen sein.',
        50: 'Denn so du bedrückest meine Töchter und so du Weiber zu meinen Töchtern nimmst, während kein Mann bei uns ist; siehe, so ist Gott Zeuge zwischen mir und zwischen dir.',
        51: 'Und Laban sprach zu Jakob: Siehe diesen Haufen und siehe die Denksäule, die ich aufgeworfen zwischen mir und zwischen dir.',
        52: 'Zeuge sei dieser Haufen und Zeuge die Denksäule, ob ich nicht über diesen Haufen hinziehe gegen dich, und ob du nicht über diesen Haufen und die Denksäule da hinziehest gegen mich zum Bösen.',
        53: 'Der Gott Abrahams und der Gott Nachors soll richten zwischen uns, der Gott ihres Vaters; und Jakob schwur bei dem Schauer seines Vaters Isaak.',
        54: 'Und Jakob brachte ein Opfer auf dem Berge und rief seine Brüder, Brot zu essen, und sie aßen Brot und übernachteten auf dem Berge.',
    },
    32: {
        1: 'Und Laban stand frühe am Morgen auf, und küßte seine Söhne und seine Töchter und segnete sie; und Laban ging und kehrte zurück an seinen Ort.',
        2: 'Und Jakob ging seinen Weg und die Engel Gottes stießen auf ihn.',
        3: 'Und da Jakob sie sah, sprach er: Dies ist ein Lager Gottes, und er nannte den Namen desselben Ortes Machanaim.',
        4: 'Und Jakob sandte Boten vor sich her an Esau, seinen Bruder, in das Land Seir, ins Gefilde Edom;',
        5: 'Und gebot ihnen und sagte: So sprecht zu meinem Herrn, zu Esau: Also spricht dein Knecht Jakob: Bei Laban habe ich mich aufgehalten und bis jetzt verweilet.',
        6: 'Und ich habe Ochs und Esel, Kleinvieh, und Knechte und Dienstmägde, und ich sende es meinem Herrn, anzusagen, um Gnade in deinen Augen zu finden.',
        7: 'Und die Boten kehrten zurück zu Jakob und sprachen: Wir sind zu deinem Bruder, zu Esau, gekommen, und auch er zieht dir entgegen und vierhundert Mann mit ihm.',
        8: 'Und Jakob fürchtete sich sehr und er ward bedrängt; und er verteilte das Volk, das bei ihm war, und das Kleinvieh und die Rinder und die Kamele in zwei Lager.',
        9: 'Und er sprach: So Esau kommt zu dem einen Lager und schlägt es, so wird das Lager, das verbleibt, entkommen.',
        10: 'Und Jakob sprach: Gott meines Vaters Abraham, und Gott meines Vaters Isaak, Jehovah, Der Du zu mir gesprochen hast: Kehr in dein Land und deinen Geburtsort zurück, und Ich will dir Gutes tun.',
        11: 'Ich bin zu gering all der Barmherzigkeit und all der Wahrheit, die Du an Deinem Knechte getan hast; denn mit meinem Stocke setzte ich über den Jordan da, und nun bin ich zu zwei Lagern geworden.',
        12: 'Errette mich doch aus der Hand meines Bruders, aus der Hand Esaus; denn ich fürchte ihn, er möchte kommen und mich schlagen, die Mutter über den Söhnen.',
        13: 'Aber Du hast gesagt: Ich will dir gewiß-lich Gutes tun und deinen Samen machen wie den Sand des Meeres, den man nicht zählt vor Menge.',
        14: 'Und er übernachtete daselbst in selbiger Nacht, und nahm von dem, was in seine Hand kam, ein Geschenk für Esau, seinen Bruder,',
        15: 'Zweihundert Ziegen und zwanzig Böcke, zweihundert Mutterschafe und zwanzig Widder.',
        16: 'Dreißig säugende Kamele und ihre Füllen, vierzig Kühe und zehn Farren, zwanzig Eselinnen und zehn Eselsfüllen.',
        17: 'Und er gab sie in die Hand seiner Knechte, jegliche Herde besonders und sprach zu seinen Knechten: Ziehet vor mir her und setzet einen Abstand zwischen Herde und zwischen Herde.',
        18: 'Und er gebot dem ersten und sprach: Wenn Esau, mein Bruder, auf dich trifft und dich fragt und sagt: Wem gehörst du an, und wohin gehst du, und für wen sind die da vor dir?',
        19: 'So sage: Deinem Knechte Jakob; es ist ein Geschenk, das er meinem Herrn, dem Esau, sendet, und siehe, auch er ist hinter uns.',
        20: 'Und er gebot auch dem zweiten und auch dem dritten, auch allen, die hinter den Herden hergingen, und sagte: Solche Worte sollt ihr reden mit Esau, wenn ihr ihn findet.',
        21: 'Und ihr sollt auch sagen: Siehe, dein Knecht Jakob ist hinter uns; denn, sagte er, ich will sein Angesicht versöhnen mit dem Geschenk, das vor mir geht; und danach will ich sein Angesicht sehen, vielleicht erhebt er mein Angesicht.',
        22: 'Und das Geschenk zog vor ihm her, und er übernachtete in dem Lager dieselbige Nacht.',
        23: 'Und er machte sich in jener Nacht auf, und nahm seine zwei Weiber und seine zwei Dienstmägde und seine elf Kinder, und setzte über die Furt des Jabbok.',
        24: 'Und er nahm sie und ließ sie über den Bach setzen, und alles, was er hatte, ließ er übersetzen.',
        25: 'Und Jakob blieb allein übrig; und es rang ein Mann mit ihm, bis die Morgenröte heraufkam,',
        26: 'Und Er sah, daß er nichts über ihn vermochte, und berührte ihn an der Hüftpfanne, und die Hüftpfanne Jakobs verrenkte sich, indem er mit Ihm rang.',
        27: 'Und Er sprach: Entlaß mich, denn die Morgenröte ist heraufgekommen; er aber sprach: Ich entlasse Dich nicht, Du segnest mich denn.',
        28: 'Und Er sprach zu ihm: Was ist dein Name? Und er sprach: Jakob.',
        29: 'Und Er sprach: Dein Name heiße hinfort nicht mehr Jakob, sondern Israel; denn du hast wie ein Fürst mit Gott und mit Männern gekämpft, und hast sie übermocht.',
        30: 'Und Jakob fragte und sprach: Sage mir doch an Deinen Namen; und Er sprach: Warum fragst du nach Meinem Namen? Und Er segnete ihn daselbst.',
        31: 'Und Jakob nannte den Namen des Ortes Peniel; denn, ich habe Gott von Angesicht zu Angesicht gesehen; und meine Seele ist errettet.',
        32: 'Und es ging ihm die Sonne auf, wie er bei Peniel hinzog, und er hinkte an seiner Hüfte. Daher essen die Söhne Israels nicht die Bewegungssehne über der Hüftpfanne bis auf diesen Tag; weil Er an der Hüftpfanne Jakobs die Bewegungssehne berührt.',
    },
    33: {
        1: 'Und Jakob hob seine Augen auf und sah, und siehe, Esau kam, und mit ihm vierhundert Mann; und er verteilte die Kinder an Leah und an Rachel und die beiden Dienstmägde.',
        2: 'Und stellte die Dienstmägde und ihre Kinder zuerst, und Leah und ihre Kinder hernach, und Rachel und Joseph nach ihnen.',
        3: 'Und er zog hin vor ihnen und verbeugte sich siebenmal zur Erde, bis daß er zu seinem Bruder hinzutrat.',
        4: 'Und Esau lief ihm entgegen und umarmte ihn und fiel ihm um den Hals und küßte ihn, und sie weinten.',
        5: 'Und er hob seine Augen auf, und sah die Weiber und die Kinder und sprach: Wer sind diese bei dir? Und er sprach: Die Kinder, mit denen Gott in Gnade deinen Knecht begabt hat.',
        6: 'Und die Dienstmägde traten herzu, sie und ihre Kinder, und verbeugten sich.',
        7: 'Und auch Leah trat herzu und ihre Kinder und verbeugten sich, und nachher traten Joseph und Rachel herzu und verbeugten sich.',
        8: 'Und er sprach: Was soll dir das ganze Lager da, auf das ich getroffen bin? Und er sprach: Auf daß ich Gnade finde in den Augen meines Herrn.',
        9: 'Und Esau sprach: Ich habe viele; mein Bruder, laß dein sein, was dein ist.',
        10: 'Und Jakob sprach: Nicht doch, fände ich doch Gnade in deinen Augen, daß du mein Geschenk aus meiner Hand nähmest! denn darum habe ich dein Angesicht gesehen, wie man das Angesicht Gottes sieht; und du hattest Wohlgefallen an mir.',
        11: 'Nimm doch meinen Segen, der dir gebracht wurde; denn Gott hat mich gnädig begabt und ich habe alles; und er drang in ihn, und er nahm es.',
        12: 'Und er sprach: Laß uns aufbrechen und gehen; und ich will vor dir gehen.',
        13: 'Und er sprach zu ihm: Mein Herr weiß, daß die Kinder zart sind, und daß das Kleinvieh und Rindvieh bei mir säugt; und übertriebe man sie einen Tag, so würde alles Kleinvieh sterben.',
        14: 'Ziehe doch mein Herr vor seinem Knechte hin, und ich will sie sachte leiten, je nach dem Schritte des Viehs vor mir her, und nach dem Schritte der Kinder, bis daß ich zu meinem Herrn nach Seir komme.',
        15: 'Und Esau sprach: Ich will doch von dem Volke, das bei mir ist, dir zustellen. Er aber sprach: Wozu das? laß mich doch Gnade in den Augen meines Herrn finden!',
        16: 'Und Esau kehrte an demselben Tag auf seinem Weg nach Seir zurück.',
        17: 'Und Jakob brach nach Sukkoth auf, und baute sich ein Haus, und für seine Viehherde machte er Hütten. Deshalb nannte man den Namen des Ortes Sukkoth.',
        18: 'Und Jakob kam nach Schalem, die Stadt des Schechem, im Lande Kanaan, wenn man von Padan Aram kommt, und lagerte sich vor der Stadt.',
        19: 'Und er kaufte einen Teil des Feldes, auf dem er sein Zelt aufschlug, von der Hand der Söhne Chamors, des Vaters von Schechem, um hundert Kesitah.',
        20: 'Und er stellte dort einen Altar auf und nannte ihn El Elohe Israel.',
    },
    34: {
        1: 'Und Dinah, die Tochter Leahs, die sie dem Jakob gebar, ging aus, um die Töchter des Landes zu sehen.',
        2: 'Und Schechem, der Sohn Chamors, des Chiviters, des Fürsten des Landes, sah sie und nahm sie und lag bei ihr und schwächte sie.',
        3: 'Und seine Seele hing an Dinah, der Tochter Jakobs, und er liebte das Mädchen und redete zu dem Herzen des Mädchens.',
        4: 'Und Schechem sprach zu Chamor, seinem Vater, und sagte: Nimm mir dieses Mädchen zum Weibe.',
        5: 'Und Jakob hörte, daß er Dinah, seine Tochter, geschändet hatte; seine Söhne aber waren bei seiner Viehherde auf dem Felde, und Jakob schwieg stille, bis sie kamen.',
        6: 'Chamor aber, Schechems Vater, ging heraus zu Jakob, um mit ihm zu reden.',
        7: 'Und die Söhne Jakobs kamen vom Felde, als sie es hörten, und es schmerzte die Männer und sie entbrannten sehr, daß er eine Torheit in Israel getan und bei der Tochter Jakobs gelegen hatte, und solches sollte nicht getan werden.',
        8: 'Und Chamor redete mit ihnen und sprach: Die Seele meines Sohnes Schechem hat Gefallen an eurer Tochter, gebet sie ihm doch zum Weibe.',
        9: 'Und verschwägert euch mit uns, gebt uns eure Töchter und nehmet euch unsre Töchter.',
        10: 'Und wohnet bei uns; und das Land soll vor eurem Angesichte sein, wohnet und handelt darin und habet Eigentum in demselben.',
        11: 'Und Schechem sprach zu ihrem Vater und zu ihren Brüdern: Möchte ich Gnade finden in euren Augen und was ihr zu mir saget, will ich geben.',
        12: 'Mehret mir sehr die Morgengabe und Gabe, und ich will geben, was ihr zu mir saget, nur gebet mir das Mädchen zum Weibe.',
        13: 'Und die Söhne Jakobs antworteten dem Schechem und Chamor, seinem Vater, trüglich, und redeten so, weil er Dinah, ihre Schwester, geschändet hatte;',
        14: 'Und sagten zu ihnen: Wir können das Wort nicht tun, daß wir unsre Schwester einem Manne geben, der Vorhaut hat; denn es wäre eine Schmach für uns.',
        15: 'Wir können nur einwilligen, wenn ihr werdet wie wir, daß ihr alles Männliche bei euch beschneidet.',
        16: 'Und dann geben wir euch unsere Töchter und nehmen uns eure Töchter, und werden dann bei euch wohnen und zu einem Volke werden.',
        17: 'Wenn ihr aber nicht auf uns höret, euch zu beschneiden, dann nehmen wir unsre Tochter und gehen.',
        18: 'Und ihre Worte waren gut in den Augen Chamors und in den Augen Schechems, des Sohnes Chamors.',
        19: 'Und der Jüngling zögerte nicht nach diesem Worte zu tun; denn er hatte Lust an Jakobs Tochter, und war vor allen geehrt im Hause seines Vaters.',
        20: 'Und Chamor kam und Schechem, sein Sohn, zum Tore ihrer Stadt und redeten mit den Männern ihrer Stadt und sprachen:',
        21: 'Diese Männer sind friedlich unter uns und wollen im Lande wohnen und darin handeln, und siehe, das Land ist weit zu beiden Seiten vor ihnen. Lasset uns ihre Töchter uns zu Weibern nehmen und unsere Töchter ihnen geben.',
        22: 'Aber nur so wollen die Männer einwilligen bei uns zu wohnen und ein Volk zu werden, daß wir bei uns alles Männliche beschneiden, so wie sie beschnitten sind.',
        23: 'Ihre Viehherden und ihr Angekauftes und all ihr Vieh, wird es nicht unser sein, wenn wir nur ihnen einwilligen, und sie werden bei uns wohnen?',
        24: 'Und sie hörten auf Chamor und auf Schechem, seinen Sohn, alle, die von dem Tor seiner Stadt ausgingen, und ließen alles Männliche beschneiden, alles, das von dem Tor seiner Stadt ausging.',
        25: 'Und es geschah am dritten Tage, während sie in Schmerzen waren, nahmen zwei Söhne Jakobs, Simeon und Levi, Brüder Dinahs, jeder Mann sein Schwert und kamen kecklich in die Stadt und erwürgten alles Männliche.',
        26: 'Und den Chamor und Schechem, seinen Sohn, erwürgten sie mit der Schärfe des Schwertes und nahmen Dinah aus dem Hause Schechems und gingen hinaus.',
        27: 'Die Söhne Jakobs kamen über die Erschlagenen und beraubten die Stadt dafür, daß sie ihre Schwester geschändet hatten.',
        28: 'Ihr Kleinvieh und ihre Rinder und ihre Esel, und was in der Stadt war und was auf dem Felde war, nahmen sie.',
        29: 'Und all ihr Vermögen, und alle ihre Kindlein und ihre Weiber nahmen sie gefangen und raubten alles, was im Hause war.',
        30: 'Und Jakob sprach zu Simeon und zu Levi: Ihr habt mich zerrüttet, daß ich stinke bei dem Einwohner des Landes, bei dem Kanaaniter und dem Pherisiter. Und ich habe nur wenig Leute. Und sie werden sich versammeln wider mich und mich schlagen, und ich und mein Haus werden vernichtet.',
        31: 'Sie aber sagten: Soll man unsrer Schwester tun wie einer Buhlerin?',
    },
    35: {
        1: 'Und Gott sprach zu Jakob: Mache dich auf, gehe hinauf nach Bethel und wohne daselbst, und mache dort einen Altar dem Gotte, Der dir erschienen ist, da du vor deinem Bruder Esau flohest.',
        2: 'Und Jakob sprach zu seinem Hause und allen, die mit ihm waren: Nehmt weg die ausländischen Götter, die in eurer Mitte sind und reinigt euch und wechselt eure Gewänder.',
        3: 'Und wir wollen uns aufmachen und hinauf gen Bethel gehen; und dort will ich einen Altar machen dem Gotte, Der mir geantwortet hat am Tage meiner Bedrängnis und mit mir war auf dem Wege, den ich wandelte.',
        4: 'Und sie gaben Jakob alle ausländischen Götter, die in ihrer Hand waren, und die Reife, die sie in ihren Ohren hatten und Jakob verbarg sie unter der Eiche, die bei Schechem war.',
        5: 'Und sie brachen auf, und das Entsetzen Gottes war über den Städten um sie her, so daß sie hinter den Söhnen Jakobs nicht nachsetzten.',
        6: 'Und Jakob kam nach Luz im Lande Kanaan, das ist Bethel, er und alles Volk, das mit ihm war.',
        7: 'Und daselbst baute er einen Altar und nannte den Ort El-Bethel, weil dort sich ihm Gott offenbarte, als er vor seinem Bruder entwich.',
        8: 'Und es starb Deborah, Rebekahs Amme, und ward unterhalb Bethel unter der Eiche begraben, und man nannte ihren Namen Allon Bachuth.',
        9: 'Und Gott erschien dem Jakob wieder, als er von Padan Aram gekommen war, und segnete ihn.',
        10: 'Und Gott sprach zu ihm: Dein Name ist Jakob; dein Name soll nicht mehr Jakob genannt werden, vielmehr Israel soll dein Name sein. Und Er nannte seinen Namen Israel.',
        11: 'Und Gott sprach zu ihm: Ich bin der Gott Schaddai; sei fruchtbar und mehre dich, eine Völkerschaft und eine Versammlung von Völkerschaften soll von dir werden, und Könige sollen von deinen Hüften hervorgehen.',
        12: 'Und das Land, daß Ich Abraham und Isaak gegeben, werde Ich dir geben, und deinem Samen nach dir werde Ich das Land geben.',
        13: 'Und Gott stieg von ihm auf an dem Ort, da Er mit ihm geredet hatte.',
        14: 'Und Jakob stellte eine Denksäule auf an dem Orte, da er mit Ihm geredet, eine Denksäule von Stein, und spendete darauf ein Trankopfer und goß Öl darauf.',
        15: 'Und Jakob nannte den Namen des Ortes, da Gott mit ihm geredet hatte, Bethel.',
        16: 'Und von Bethel brachen sie auf, und es war noch eine Strecke Landes, bis man nach Ephratah kam, und Rachel gebar und litt Hartes bei der Geburt.',
        17: 'Und es geschah, daß es ihr hart ward über der Geburt, da sprach die Wehmutter zu ihr: Fürchte dich nicht, denn auch dies ist dir ein Sohn.',
        18: 'Und es geschah, da ihr die Seele ausging, daß sie am Sterben war, da nannte sie seinen Namen Benoni, sein Vater aber nannte ihn Benjamin.',
        19: 'Und Rachel starb und ward begraben auf dem Wege nach Ephratah, das ist Bethlehem.',
        20: 'Und Jakob stellte eine Denksäule über ihrem Grabe auf, das ist die Denksäule von Rachels Grab bis auf diesen Tag.',
        21: 'Und Israel brach auf und schlug sein Zelt auf jenseits des Migdal Eder.',
        22: 'Und es geschah, da Israel in diesem Lande wohnte, da ging Ruben hin und lag bei Bilhah, dem Kebsweibe seines Vaters, und Israel hörte es. Jakob aber hatte zwölf Söhne.',
        23: 'Die Söhne Leahs: Der Erstgeborene Jakobs: Ruben und Simeon, und Levi und Judah und Isaschar und Sebulun.',
        24: 'Die Söhne Rachels: Joseph und Benjamin.',
        25: 'Und die Söhne Bilhahs, der Dienstmagd Rachels: Dan und Naphthali.',
        26: 'Und die Söhne Silpahs, Leahs Dienstmagd: Gad und Ascher. Dies sind die Söhne Jakobs, die ihm in Padan Aram geboren wurden.',
        27: 'Und Jakob kam zu Isaak, seinem Vater, nach Mamre bei Kiriath Arba, das ist Chebron, woselbst Abraham und Isaak sich aufgehalten.',
        28: 'Und es waren Isaaks Tage hundert Jahre und achtzig Jahre.',
        29: 'Und Isaak verschied und starb und ward zu seinen Völkern versammelt, alt und an Tagen satt. Und es begruben ihn Esau und Jakob, seine Söhne.',
    },
    36: {
        1: 'Und dies sind die Geburten Esaus, das ist Edom.',
        2: 'Esau nahm seine Weiber von den Töchtern Kanaans: Adah, die Tochter Elons, des Chethiters und Oholibamah, Tochter Anahs, Tochter des Zibeon, des Chiviters.',
        3: 'Und Basemath eine Tochter Ismaels, Schwester des Nabajoth.',
        4: 'Und Adah gebar dem Esau Eliphas und Basemath gebar Reguel.',
        5: 'Und Oholibamah gebar Jeusch und Jaelam und Korach. Dies sind die Söhne Esaus, die ihm im Lande Kanaan geboren wurden.',
        6: 'Und Esau nahm seine Weiber und seine Söhne und sein Töchter und alle Seelen seines Hauses, und sein Besitztum und all sein Vieh, und all sein Erkauftes, das er im Lande Kanaan gewonnen, und ging in ein Land, hinweg von Jakob, seinem Bruder.',
        7: 'Denn ihrer Habe war zu viel, als daß sie beisammen hätten wohnen können; und das Land ihrer Wanderungen vermochte nicht, wegen ihrer Viehherden sie zu tragen.',
        8: 'Und Esau wohnte auf dem Berge Seir; Esau, das ist Edom.',
        9: 'Und dies sind die Geburten Esaus, des Vaters von Edom auf dem Berge Seir.',
        10: 'Dies sind die Namen der Söhne Esaus: Eliphas, Sohn von Adah, Esaus Weib; Reguel, Sohn von Basemath, Esaus Weib.',
        11: 'Und die Söhne des Eliphas waren Theman, Omar, Zepho und Gaetham und Kenas.',
        12: 'Und Thimna war Kebsweib des Eliphas, des Sohnes Esaus, und gebar dem Eliphas Amalek. Dies sind die Söhne von Adah, Esaus Weib.',
        13: 'Und das sind die Söhne Reguels: Nachath und Serach, Schammah und Missah. Dies waren die Söhne Basemaths, Esaus Weib.',
        14: 'Und dies waren die Söhne Oholibamahs, der Tochter Anahs, der Tochter Zibeons, Esaus Weib. Und sie gebar dem Esau Jeusch und Jaelam und Korach.',
        15: 'Dies waren die Stammhäupter der Söhne Esaus: Die Söhne von Eliphas, dem Erstgeborenen Esaus: das Stammhaupt Theman, das Stammhaupt Omar, das Stammhaupt Zepho, das Stammhaupt Kenas.',
        16: 'Das Stammhaupt Korach, das Stammhaupt Gaetham, das Stammhaupt Amalek. Dies die Stammhäupter des Eliphas im Lande Edom. Dies sind die Söhne Adahs.',
        17: 'Und das sind die Söhne Reguels, des Sohnes Esaus: Das Stammhaupt Nachath, das Stammhaupt Serach, das Stammhaupt Schammah, das Stammhaupt Missah. Dies sind die Stammhäupter Reguels im Lande Edom. Dies die Söhne von Basemath, Esaus Weib.',
        18: 'Und das sind die Söhne Oholibamahs, Esaus Weib: Das Stammhaupt Jeusch, das Stammhaupt Jaelam, das Stammhaupt Korach. Dies die Stammhäupter Oholibamahs, der Tochter Anahs, Esaus Weib.',
        19: 'Das sind die Söhne Esaus, und das ihre Stammhäupter, er ist Edom.',
        20: 'Das sind die Söhne Seirs, des Horiten, die das Land bewohnen: Lotan und Schobal und Zibeon und Anah.',
        21: 'Und Dischon und Ezer und Dischan. Dies die Stammhäupter des Horiten, die Söhne Seirs im Lande Edom.',
        22: 'Und Lotans Söhne waren Hori und Hemam und die Schwester Lotans war Thimna.',
        23: 'Und das sind die Söhne Schobals: Alwan, und Manachath, und Ebal, Schepho und Onam.',
        24: 'Und das sind die Söhne Zibeons: Ajah, und Anah. Dies ist der Anah, der in der Wüste die Maulesel fand, als er die Esel seines Vaters Zibeon weidete.',
        25: 'Und das sind die Söhne Anahs: Dischon und Oholibamah war Anahs Tochter.',
        26: 'Und das sind die Söhne Dischons: Chemdan und Eschban, und Jithran und Cheran.',
        27: 'Das sind die Söhne Ezers: Bilhan und Saawan und Akan.',
        28: 'Das sind die Söhne Dischans: Uz und Aran.',
        29: 'Das sind die Stammhäupter des Horiten: Das Stammhaupt Lotan, das Stammhaupt Schobal das Stammhaupt Zibeon, das Stammhaupt Anah.',
        30: 'Das Stammhaupt Dischon, das Stammhaupt Ezer, das Stammhaupt Dischan: Dies die Stammhäupter des Horiten nach ihren Stammhäuptern im Lande Seir.',
        31: 'Und das sind die Könige, die im Lande Edom regierten, ehe ein König über die Söhne Israel regierte.',
        32: 'Und in Edom regierte Bela, der Sohn Beors, und der Name seiner Stadt war Dinhabah.',
        33: 'Und Bela starb, und an seiner Statt regierte Jobab, der Sohn Serachs aus Bozrah.',
        34: 'Und Jobab starb, und statt seiner regierte Chuscham aus dem Lande der Themaniter.',
        35: 'Und Chuscham starb, und an seiner Statt regierte Hadad, der Sohn Bedads, der Midjan schlug in dem Gefilde Moabs, und der Name seiner Stadt war Awith.',
        36: 'Und Hadad starb, und es regierte an seiner Statt Samlah aus Masrekah.',
        37: 'Und Samlah starb, und an seiner Statt regierte Schaul aus Rechoboth am Flusse.',
        38: 'Und Schaul starb, und es regierte statt seiner Baal Chanan, der Sohn Achbors.',
        39: 'Und Baal Chanan, der Sohn Achbors, starb, und es regierte statt seiner Hadar, und der Name seiner Stadt war Pau, und der Name seines Weibes war Mehetabeel, Tochter der Matred, die eine Tochter Mesahabs war.',
        40: 'Und das sind die Namen der Stammhäupter Esaus nach ihren Familien, nach ihren Orten, bei ihren Namen: Stammhaupt Thimna, Stammhaupt Alwah, Stammhaupt Jetheth.',
        41: 'Stammhaupt Oholibamah, Stammhaupt Elah, Stammhaupt Pinon.',
        42: 'Stammhaupt Kenas, Stammhaupt Theman, Stammhaupt Mibzar.',
        43: 'Stammhaupt Magdiel, Stammhaupt Iram. Dies sind die Stammhäupter Edoms nach ihren Wohnsitzen in dem Lande ihres Eigentums. Das ist Esau, der Vater Edoms.',
    },
    37: {
        1: 'Und Jakob wohnte im Lande der Wanderungen seines Vaters, im Lande Kanaan.',
        2: 'Das sind die Geburten Jakobs. Joseph war siebzehn Jahre alt, er war mit seinen Brüdern ein Hirte beim Kleinvieh. Und der Junge war bei den Söhnen der Bilhah und den Söhnen Silpahs, der Weiber seines Vaters, und Joseph brachte das böse Gerede von ihnen herein zu ihrem Vater.',
        3: 'Und Israel liebte Joseph mehr denn alle seine Söhne, weil er der Sohn seines Alters war, und machte ihm einen buntfarbigen Rock.',
        4: 'Und seine Brüder sahen, daß ihr Vater ihn mehr als alle seine Brüder liebte, und sie haßten ihn, und vermochten nicht im Frieden mit ihm reden.',
        5: 'Und Joseph träumte einen Traum, und sagte ihn seinen Brüdern an, und sie haßten ihn noch mehr.',
        6: 'Und er sprach zu ihnen: Höret doch diesen Traum, den ich geträumt habe.',
        7: 'Und siehe, wir banden Garben inmitten des Feldes, und siehe, es richtete sich auf meine Garbe und stand aufrecht, und siehe, eure Garben umgaben sie und verbeugten sich vor meiner Garbe.',
        8: 'Und seine Brüder sprachen zu ihm: Du willst wohl gar über uns regieren, willst du über uns herrschen? und sie haßten ihn noch mehr ob seinen Träumen und ob seinen Worten.',
        9: 'Und er träumte noch einen anderen Traum und erzählte ihn seinen Brüdern. Und er sprach: Siehe, ich träumte noch einen Traum, und siehe, die Sonne und der Mond und elf Sterne verbeugten sich vor mir.',
        10: 'Und er erzählte es seinem Vater und seinen Brüdern; sein Vater aber bedrohte ihn und sagte zu ihm: Was soll es mit diesem Traume, den du geträumt hast? Sollen wir, ich und deine Mutter und deine Brüder kommen und uns vor dir zu Erde verbeugen?',
        11: 'Und seine Brüder beneideten ihn; sein Vater aber behielt das Wort.',
        12: 'Und seine Brüder gingen das Kleinvieh ihres Vaters zu weiden in Schechem.',
        13: 'Und Israel sprach zu Joseph: Sind nicht deine Brüder auf der Weide in Schechem? Gehe, und ich will dich zu ihnen senden. Und er sprach zu ihm: Siehe, hier bin ich.',
        14: 'Und er sprach zu ihm: Geh doch und sieh, wie es deinen Brüdern geht, und wie es mit dem Kleinvieh geht und bring mir das Wort zurück. Und er sandte ihn aus dem Talgrunde Chebron und er kam nach Schechem.',
        15: 'Und es fand ihn ein Mann, und siehe, er wanderte auf dem Felde umher. Und der Mann fragte ihn und sprach: Was suchest du?',
        16: 'Und er sprach: Meine Brüder suche ich. Sage mir doch an, wo sie auf der Weide sind.',
        17: 'Und der Mann sagte ihm: Sie sind von hier aufgebrochen; denn ich hörte sie sagen: Wir wollen nach Dothan gehen. Und Joseph ging seinen Brüdern nach und fand sie in Dothan.',
        18: 'Und sie sahen ihn von ferne, und ehe er ihnen nahe kam, faßten sie den Anschlag wider ihn, ihn zu töten.',
        19: 'Und sie sprachen der eine zum anderen: Siehe, da kommt dieser Traummeister.',
        20: 'Und nun kommet, laßt uns ihn erwürgen und in eine der Gruben werfen und sagen: Ein böses, wildes Tier hat ihn gefressen, und wir wollen sehen, was aus seinen Träumen wird.',
        21: 'Und Ruben hörte dies und wollte ihn aus ihrer Hand erretten, und sprach: Wir wollen ihm nicht an die Seele gehen.',
        22: 'Und Ruben sprach zu ihnen: Vergießet nicht Blut, werfet ihn in die Grube dort in der Wüste, strecket aber eure Hand nicht aus gegen ihn; auf daß er ihn aus ihrer Hand errette, um ihn zu seinem Vater zurückzubringen.',
        23: 'Und es geschah, da Joseph zu seinen Brüdern kam, zogen sie dem Joseph seinen Rock, den buntfarbigen Rock aus, den er anhatte;',
        24: 'Und sie nahmen ihn und warfen ihn in die Grube; die Grube aber war leer, kein Wasser war darin.',
        25: 'Und sie setzten sich, das Brot zu essen, und hoben ihre Augen auf und sahen, und siehe, ein Wanderzug Ismaeliten kam von Gilead; und ihre Kamele trugen Gewürze und Balsam und Stakte, und sie gingen, sie hinab nach Ägypten zu bringen.',
        26: 'Und Judah sprach zu seinen Brüdern: Welchen Gewinn haben wir davon, daß wir unseren Bruder erwürgen und sein Blut verbergen?',
        27: 'Kommt lasset uns ihn an die Ismaeliten verkaufen; und unsre Hand sei nicht an ihm; denn er ist unser Bruder, unser Fleisch ist er; und seine Brüder hörten auf ihn.',
        28: 'Und die midianitischen Männer, die Händler, zogen daher; sie aber zogen Joseph heraus und brachten ihn herauf aus der Grube, und verkauften Joseph an die Ismaeliten um zwanzig Silberlinge; und sie brachten Joseph nach Ägypten.',
        29: 'Und Ruben kehrte nach der Grube zurück, und siehe: kein Joseph war in der Grube; und er zerriß seine Kleider;',
        30: 'Und er kehrte zu seinen Brüdern zurück und sprach: Das Kind ist nicht mehr da. Und ich, wohin komme ich?',
        31: 'Sie aber nahmen Josephs Rock und schlachteten einen Bock von den Ziegen, und tauchten den Rock in das Blut.',
        32: 'Und sie sandten den buntfarbigen Rock fort und brachten ihn zu ihrem Vater und sagten: Diesen haben wir gefunden! besieh ihn doch, ob es deines Sohnes Rock ist, oder nicht.',
        33: 'Und er erkannte ihn und sprach: Es ist der Rock meines Sohnes, ein böses, wildes Tier hat ihn gefressen. Zerfleischt ist Joseph.',
        34: 'Und Jakob zerriß seine Gewänder und legte einen Sack um seine Lenden, und trauerte viele Tage um seinen Sohn.',
        35: 'Und alle seine Söhne und alle seine Töchter, machten sich auf, ihn zu trösten; aber er weigerte, sich trösten zu lassen und sprach: Ich will trauend in die Gruft hinabgehen zu meinem Sohne; und es beweinte ihn sein Vater.',
        36: 'Die Midianiter aber verkauften ihn nach Ägypten an Potiphar, einen Hofbeamten Pharaos, Obersten der Leibwachen.',
    },
    38: {
        1: 'Und es geschah um jene Zeit, daß Judah hinabging von seinen Brüdern, und sich zu einem adullamitischen Manne abwandte, und sein Name war Chirah.',
        2: 'Und dort sah Judah die Tochter eines kanaanitischen Mannes, dessen Name Schua war und er nahm sie und kam zu ihr.',
        3: 'Und sie empfing und gebar einen Sohn, und er nannte seinen Namen Er.',
        4: 'Und sie empfing wieder und gebar einen Sohn, und sie nannte seinen Namen Onan.',
        5: 'Und sie gebar wieder einen Sohn, und sie nannte seinen Namen Schelah; und er war in Chesib, da sie ihn gebar.',
        6: 'Und Judah nahm dem Er seinem Erstgeborenen ein Weib, und ihr Name war Thamar.',
        7: 'Und Er, Judahs Erstgeborener, war böse in den Augen Jehovahs, und Jehovah ließ ihn sterben.',
        8: 'Und Judah sprach zu Onan: Komm zu dem Weibe deines Bruders und leiste ihr die Schwagerpflicht, und erwecke Samen deinem Bruder.',
        9: 'Und Onan wußte, daß der Same nicht sein eigen sein sollte, und es geschah, als er zu dem Weibe seines Bruders kam, da verdarb er ihn auf die Erde, um seinem Bruder keinen Samen zu geben.',
        10: 'Und es war böse in den Augen Jehovahs, was er tat; und Er ließ auch ihn sterben.',
        11: 'Und Judah sprach zu Thamar, seiner Schnur: Bleib Witwe im Hause deines Vaters, bis Schelah, mein Sohn, groß geworden ist; denn er sprach: Sonst könnte auch er sterben, wie seine Brüder. Und Thamar ging und blieb in ihres Vaters Haus.',
        12: 'Und es wurden der Tage viel, und es starb die Tochter Schuas, Judahs Weib; und Judah tröstete sich, und ging hinauf zu den Scherern seines Kleinviehs er und Chirah, sein Genosse, der Adullamite, nach Thimnath.',
        13: 'Und es ward der Thamar angesagt, sprechend: Siehe, dein Schwäher geht hinauf gen Thimnath, sein Vieh zu scheren.',
        14: 'Und sie legte die Kleider ihrer Witwenschaft ab von ihr und bedeckte sich mit einem Schleier und verhüllte sich und setzte sich an den Eingang zu Enajim, die auf dem Wege nach Thimnath ist; denn sie sah, daß Schelah groß geworden und sie ihm nicht zum Weibe gegeben ward.',
        15: 'Und Judah sah sie und dachte, sie wäre eine Buhlerin; denn sie hatte ihr Gesicht bedeckt.',
        16: 'Und er wandte sich ab zu ihr am Wege und sprach: Laß mich doch zu dir kommen; denn er wußte nicht, daß sie seine Schnur war. Sie aber sagte: Was gibst du mir, daß du zu mir kommst?',
        17: 'Und er sprach: Ich will dir ein Ziegenböcklein von dem Kleinvieh senden; sie aber sagte: Wenn du ein Pfand gibst, bis du es sendest.',
        18: 'Und er sagte: Was ist das Pfand, das ich dir geben soll? Und sie sprach: Deinen Siegelring und deine Schnur und deinen Stab, der in deiner Hand ist; und er gab sie ihr und kam zu ihr; und sie empfing von ihm.',
        19: 'Sie aber machte sich auf und ging und legte ihren Schleier ab von ihr und zog die Kleider ihrer Witwenschaft an.',
        20: 'Und Judah sandte das Ziegenböcklein durch die Hand seines Genossen, den Adullamiten, um das Pfand von der Hand des Weibes zu holen, fand sie aber nicht.',
        21: 'Und er fragte die Männer ihres Ortes und sprach: Wo ist die Buhlpriesterin bei Enajim am Wege; sie aber sagten: Es ist keine Buhlpriesterin dagewesen.',
        22: 'Und er kehrte zu Judah zurück und sagte: Ich habe sie nicht gefunden, und auch die Männer des Ortes sagten: Es ist keine Buhlpriesterin dagewesen.',
        23: 'Judah aber sagte: Sie mag es zu sich nehmen, daß wir nicht verachtet werden. Siehe, ich habe dieses Böcklein gesandt und du hast sie nicht gefunden.',
        24: 'Und es geschah nach drei Monaten, daß man Judah ansagte und sprach: Deine Schnur Thamar hat gebuhlt, und siehe, sie hat auch von ihren Buhlereien empfangen. Und Judah sprach: Bringt sie heraus, daß sie verbrannt werde.',
        25: 'Sie ward hinausgebracht und sie sandte an ihren Schwäher und sprach: Von dem Manne, dem dieses zugehört, hab ich empfangen. Und sie sprach: Besieh dir doch, wessen dieser Siegelring und diese Schnur und dieser Stab sind.',
        26: 'Und Judah besah sie und sprach: Sie ist gerechter denn ich gewesen, weil ich sie nicht meinem Sohne Schelah gegeben; aber er erkannte sie hinfort nicht mehr.',
        27: 'Und es geschah zur Zeit, da sie gebar, und siehe, es waren Zwillinge in ihrem Leibe.',
        28: 'Und es geschah, als sie gebar, daß einer eine Hand hergab. Und die Wehmutter nahm seine Hand und band Scharlach darum und sprach: Der ist zuerst herausgekommen.',
        29: 'Und es geschah, da er seine Hand zurückzog, siehe, da kam sein Bruder heraus; und sie sprach: Was hast du für dich einen Durchbruch durchgebrochen? Und er nannte seinen Namen Perez.',
        30: 'Und nachher kam sein Bruder heraus, an dessen Hand der Scharlach war, und er nannte seinen Namen Serach.',
    },
    39: {
        1: 'Und Joseph ward nach Ägypten hinabgebracht, und es kaufte ihn Potiphar, ein Hofbeamter Pharaos, Oberster der Leibwachen, ein ägyptischer Mann, aus der Hand der Ismaeliten, die ihn hinabgebracht hatten.',
        2: 'Und Jehovah war mit Joseph, und er war ein Mann, dem es gelang; und er war im Hause seines Herrn, des Ägypters.',
        3: 'Und sein Herr sah, daß Jehovah mit ihm war und alles, was er tat, Jehovah in seiner Hand gelingen ließ.',
        4: 'Und Joseph fand Gnade in seinen Augen, und er tat ihm Dienst. Und er bestellte ihn über sein Haus und alles, was er hatte, gab er in seine Hand.',
        5: 'Und es geschah, von da an, daß er ihn über sein Haus und alles, was er hatte, bestellt hatte, da segnete Jehovah das Haus des Ägypters wegen Josephs; und der Segen Jehovahs war in allem, das er hatte im Haus und im Feld.',
        6: 'Und er ließ alles, das er hatte, in der Hand Josephs, und wußte bei ihm um nichts, als das Brot, das er aß; und Joseph war schön von Gestalt und schön von Ansehen.',
        7: 'Und es geschah nach diesen Dingen, daß das Weib seines Herrn ihre Augen aufhob zu Joseph und zu ihm sprach: Liege bei mir.',
        8: 'Er aber weigerte sich und sprach zu dem Weibe seines Herrn: Siehe, mein Herr weiß um nichts bei mir, was im Hause ist, und hat alles, was er hat, in meine Hand gegeben.',
        9: 'Es ist kein Größerer denn ich in diesem Hause, und nichts hat er von mir zurückgehalten, außer dir, weil du sein Weib bist; und warum sollte ich solch großes Böses tun, und wider Gott sündigen?',
        10: 'Und es geschah, daß sie mit Joseph redete Tag für Tag, er hörte aber nicht auf sie, daß er neben ihr läge und bei ihr wäre.',
        11: 'Und es geschah eines Tages, daß er in das Haus kam, um sein Werk zu tun, und kein Mann von den Männern des Hauses war dort im Hause.',
        12: 'Und sie erfaßte ihn an seinem Kleid und sprach: Liege bei mir! Er aber ließ sein Kleid in ihrer Hand und floh und ging hinaus.',
        13: 'Und es geschah, da sie sah, daß er sein Kleid in ihrer Hand ließ und hinausfloh,',
        14: 'Daß sie rief den Männern ihres Hauses und sprach zu ihnen und sagte: Seht, da brachte er einen hebräischen Mann zu uns herein, seinen Scherz mit uns zu treiben; er kam zu mir, um bei mir zu liegen. Ich aber rief mit großer Stimme.',
        15: 'Und es geschah, wie er hörte, daß ich meine Stimme erhob und rief, da ließ er sein Kleid bei mir, und floh und ging hinaus.',
        16: 'Und sie legte sein Kleid neben sich nieder, bis sein Herr in sein Haus kam;',
        17: 'Und sie redete zu ihm dieselben Worte und sprach: Der hebräische Knecht, den du zu uns hereingebracht, ist zu mir hereingekommen, um seinen Scherz mit mir zu treiben.',
        18: 'Und es geschah, wie ich meine Stimme erhob und rief, da ließ er sein Kleid neben mir und floh hinaus.',
        19: 'Und es geschah, als sein Herr die Worte seines Weibes hörte, die sie zu ihm redete, indem sie sprach: Solches hat mir dein Knecht getan, da entbrannte sein Zorn.',
        20: 'Und Josephs Herr nahm ihn und gab ihn in das Gefängnishaus, den Ort, wo die Gebundenen des Königs gebunden waren; und er war dort in dem Gefängnishaus.',
        21: 'Aber Jehovah war mit Joseph und neigte ihm Barmherzigkeit zu, und gab ihm Gnade in den Augen des Obersten des Gefängnishauses.',
        22: 'Und der Oberste des Gefängnishauses gab in Josephs Hand alle Gebundenen, die im Gefängnishause waren, und alles, was sie dort taten, das tat er.',
        23: 'Der Oberste des Gefängnishauses sah nach nichts, von allem, das in seiner Hand war, weil Jehovah mit ihm war, und was er tat, Jehovah gelingen ließ.',
    },
    40: {
        1: 'Und es geschah nach diesen Dingen, daß der Mundschenk des Königs von Ägypten und der Bäcker an ihrem Herrn, dem Könige von Ägypten, sündigten.',
        2: 'Und Pharao war entrüstet über seine beiden Hofbeamten, über den Obersten der Mundschenken und über den Obersten der Bäcker;',
        3: 'Und gab sie in Gewahrsam in das Haus des Obersten der Leibwachen, in das Gefängnishaus, an den Ort, in dem Joseph gebunden war.',
        4: 'Und der Oberste der Leibwachen bestellte Joseph bei ihnen, daß er ihnen Dienst tun sollte, und sie waren etliche Tage in Gewahrsam.',
        5: 'Und sie träumten beide einen Traum, jeder Mann seinen Traum, in einer Nacht, jeder nach der Deutung seines Traums, der Mundschenk und der Bäcker, die der König von Ägypten hatte, und die gebunden waren in dem Gefängnishaus.',
        6: 'Und am Morgen kam Joseph zu ihnen hinein und sah sie und siehe, sie waren verdrossen.',
        7: 'Und er fragte die Hofbeamten Pharaos, die mit ihm in dem Gewahrsam des Hauses seines Herrn waren und sagte: Warum ist euer Angesicht heute böse?',
        8: 'Und sie sprachen zu ihm: Wir haben einen Traum geträumt, und niemand ist da, der ihn deute. Joseph aber sprach zu ihnen: Gehören Deutungen nicht Gott zu? Erzählt sie mir doch.',
        9: 'Und der Oberste der Mundschenken erzählte dem Joseph seinen Traum und sprach zu ihm: In meinem Traume siehe, da war ein Weinstock vor mir;',
        10: 'Und an dem Weinstock waren drei Reben; und es war, als sproßte er, seine Blüte ging auf und seine Trauben ließen die Weinbeeren reifen.',
        11: 'Und Pharaos Becher war in meiner Hand, und ich nahm die Weinbeeren und drückte sie aus in den Becher Pharaos, und ich gab den Becher in Pharaos Hand.',
        12: 'Und Joseph sprach zu ihm: Dies ist seine Deutung: Die drei Reben, sie sind drei Tage.',
        13: 'In noch drei Tagen wird Pharao dein Haupt aufheben und dich in deine Stelle zurückbringen, und du wirst den Becher Pharaos in seine Hand geben in der früheren Weise, da du sein Mundschenk warst.',
        14: 'Aber möchtest du meiner bei dir gedenken, wenn es gut bei dir ist, und Barmherzigkeit an mir tun, und meiner bei Pharao gedenken, daß du mich aus diesem Hause herausbrächtest.',
        15: 'Denn gestohlen bin ich worden aus dem Lande der Hebräer, und auch hier habe ich nichts getan, daß sie mich in die Grube legten.',
        16: 'Und der Oberste der Bäcker sah, daß er gut gedeutet hatte, und sprach zu Joseph: Auch ich war in meinem Traum, und siehe, drei durchbrochene Körbe waren auf meinem Haupte.',
        17: 'Und in dem obersten Korb waren von allen Speisen Pharaos, die der Bäcker macht, und das Gevögel fraß sie aus dem Korb von meinem Haupt.',
        18: 'Und Joseph antwortete und sprach: Dies ist seine Deutung: Die drei Körbe, sie sind drei Tage.',
        19: 'In noch drei Tagen wird Pharao dein Haupt von dir aufheben und dich ans Holz hängen, und das Gevögel wird dein Fleisch von dir fressen.',
        20: 'Und es geschah am dritten Tage, Pharaos Geburtstag, daß er allen seinen Knechten ein Gastmahl machte; und er hob auf das Haupt des Obersten der Mundschenken und das Haupt des Obersten der Bäcker inmitten seiner Knechte.',
        21: 'Und brachte den Obersten der Mundschenken in sein Mundschenkenamt zurück, und er gab den Becher in Pharaos Hand;',
        22: 'Aber den Obersten der Bäcker ließ er hängen, wie ihnen Joseph gedeutet hatte.',
        23: 'Aber der Oberste der Mundschenken gedachte nicht an Joseph, und vergaß sein.',
    },
    41: {
        1: 'Und es geschah am Ende zweier Jahre von Tagen, daß Pharao träumte, und siehe, er stand am Strome.',
        2: 'Und siehe, aus dem Strome stiegen auf sieben Kühe, schön anzusehen und feist an Fleisch, und weideten im Riedgras.',
        3: 'Und siehe, sieben andere Kühe stiegen nach ihnen auf aus dem Strome, übel anzusehen und mager an Fleisch, und sie standen neben den Kühen am Ufer des Stromes.',
        4: 'Und die Kühe, übel anzusehen und mager an Fleisch, fraßen die sieben Kühe, die schön anzusehen und feist waren; und Pharao erwachte.',
        5: 'Und er schlief ein und träumte zum zweiten Mal; und siehe, sieben Ähren kamen herauf an einem Halm, feist und gut.',
        6: 'Und siehe, sieben Ähren, mager und vom Ostwind versengt, sproßten nach ihnen auf.',
        7: 'Und die mageren Ähren verschlangen die sieben feisten und vollen Ähren, und Pharao erwachte, und siehe, es war ein Traum.',
        8: 'Und es geschah am Morgen, daß sein Geist beunruhigt war, und er sandte aus und rief all die Wahrsager Ägyptens und alle seine Weisen, und Pharao erzählte ihnen seinen Traum, und es war keiner, der sie dem Pharao deutete.',
        9: 'Und der Oberste der Mundschenken redete mit Pharao und sprach: Ich gedenke heute meiner Sünden.',
        10: 'Pharao war entrüstet über seine Knechte und gab mich in Gewahrsam in das Haus des Obersten der Leibwachen, mich und den Obersten der Bäcker.',
        11: 'Und wir träumten einen Traum in einer Nacht, ich und er, jeder Mann nach der Deutung seines Traumes träumten wir.',
        12: 'Und daselbst war bei uns ein hebräischer Jüngling, ein Knecht des Obersten der Leibwachen, und wir erzählten es ihm und er deutete uns unsere Träume, jedem Mann nach seinem Traume deutete er.',
        13: 'Und es geschah, wie er uns gedeutet hatte, so war es. Mich brachte er wieder an meine Stelle, und ihn ließ er hängen.',
        14: 'Und Pharao sandte und rief Joseph, und sie brachten ihn eilends aus der Grube. Und er schor sich und wechselte seine Gewänder und kam zu Pharao.',
        15: 'Und Pharao sprach zu Joseph: Ich habe einen Traum geträumt und ist niemand der ihn deutet. Von dir aber hörte ich sagen, du hörest einen Traum, ihn zu deuten.',
        16: 'Und Joseph antwortete dem Pharao und sprach: Bei mir ist es nicht. Gott wird dem Pharao Frieden antworten.',
        17: 'Und Pharao redete zu Joseph: Siehe, ich stand in meinem Traume am Ufer des Stromes.',
        18: 'Und siehe, aus dem Strome stiegen auf sieben Kühe, feist an Fleisch und schön von Gestalt, und sie weideten im Riedgras.',
        19: 'Und siehe, sieben andere Kühe stiegen nach ihnen auf, ärmlich und sehr übel von Gestalt und abgemagert an Fleisch, ich sah dergleichen nicht in ganz Ägyptenland, so schlecht.',
        20: 'Und die abgemagerten und schlechten Kühe fraßen die sieben ersten feisten Kühe.',
        21: 'Und sie gingen in sie hinein, und man wußte es nicht, daß sie in sie hineingekommen, und ihr Ansehen war so schlecht, wie im Anbeginn; und ich erwachte.',
        22: 'Und ich sah in meinem Traume, und siehe, sieben Ähren kamen hervor an einem Halm, voll und gut.',
        23: 'Und siehe, sieben Ähren, verdorrt, mager, vom Ostwind versengt, sproßten nach denselben auf.',
        24: 'Und die mageren Ähren verschlangen die sieben guten Ähren; und ich sagte es den Wahrsagern und keiner konnte mir es ansagen.',
        25: 'Und Joseph sprach zu Pharao: Der Traum Pharaos ist einer. Was Gott tun wird, hat er Pharao angesagt.',
        26: 'Die sieben guten Kühe, die sind sieben Jahre; und die sieben guten Ähren, die sind sieben Jahre. Es ist ein Traum.',
        27: 'Und die sieben abgemagerten und schlechten Kühe, die nach ihnen aufstiegen, die sind sieben Jahre und die sieben leeren, vom Ostwind versengten Ähren werden sieben Jahre des Hungers sein.',
        28: 'Das ist das Wort, das ich zu Pharao geredet habe; was Gott tun wird, das hat er Pharao gezeigt.',
        29: 'Siehe, es kommen sieben Jahre großen Überflusses in ganz Ägyptenland.',
        30: 'Und es erstehen nach ihnen sieben Hungerjahre; und man vergißt all des Überflusses im Land Ägypten, und der Hunger verzehrt das Land.',
        31: 'Und man wird nichts mehr wissen von dem Überfluß im Lande vor dieser Hungersnot, die hernach sein wird; denn sehr schwer wird sie sein.',
        32: 'Und daß der Traum für Pharao zum zweiten Male wiederholt worden ist, ist, weil das Wort von Gott bereitet ist, und Gott eilt, es zu tun.',
        33: 'Und jetzt sehe Pharao nach einem einsichtsvollen und weisen Mann und setze ihn über Ägyptenland.',
        34: 'Dies tue Pharao und bestelle Amtleute über das Land, und nehme in den sieben Jahren des Überflusses den Fünften im Lande Ägypten.',
        35: 'Und sie sollen alle die Speise dieser guten Jahre, die da kommen, zusammenbringen und unter der Hand Pharaos Getreide in den Städten zur Speise aufhäufen und behalten.',
        36: 'Und die Speise sei ein Vorrat für das Land auf die sieben Hungerjahre, die sein werden im Lande Ägypten, und das Land wird nicht ausgerottet werden durch den Hunger.',
        37: 'Und das Wort war gut in den Augen Pharaos und in den Augen aller seiner Knechte.',
        38: 'Und Pharao sprach zu seinen Knechten: Können wir einen Mann finden wie diesen, in dem der Geist Gottes ist?',
        39: 'Und Pharao sprach zu Joseph: Nachdem dir Gott alles dies zu wissen getan, ist keiner so verständig und weise wie du.',
        40: 'Du sollst sein über mein Haus, und auf deinen Mund soll küssen all mein Volk; nur um den Thron will ich größer sein, als du.',
        41: 'Und Pharao sprach zu Joseph: Siehe, ich hab dich gesetzt über ganz Ägyptenland.',
        42: 'Und Pharao nahm seinen Ring ab von seiner Hand und gab ihn an Josephs Hand, und ließ ihm Kleider von Byssus anziehen und legte eine goldene Kette an seinen Hals.',
        43: 'Und ließ ihn in dem zweiten Streitwagen fahren, den er hatte, und sie riefen vor ihm Abrech! und setzte ihn über ganz Ägyptenland.',
        44: 'Und Pharao sprach zu Joseph: Ich bin Pharao; und ohne dich soll niemand seine Hand und seinen Fuß emporheben in ganz Ägyptenland.',
        45: 'Und Pharao nannte den Namen Josephs Zaphnath Paneach, und gab ihm Asnath, die Tochter Potipheras, Priester von On, zum Weibe, und Joseph ging aus über Ägyptenland.',
        46: 'Und Joseph war dreißig Jahre alt, als er vor Pharao, dem Könige von Ägypten stand. Und Joseph ging aus von Pharao und zog hin in das ganze Land Ägypten.',
        47: 'Und das Land trug in den sieben Jahren des Überflusses zu vollen Händen.',
        48: 'Und er brachte alle Speise der sieben Jahre, die im Lande Ägypten waren, zusammen und gab die Speise in die Städte; die Speise von dem Felde, das rings um die Stadt war, gab er in ihre Mitte.',
        49: 'Und Joseph häufte Getreide auf wie Sand am Meere, so sehr viel, daß er aufhörte zu zählen, denn es war ohne Zahl.',
        50: 'Und dem Joseph wurden zwei Söhne geboren, ehe das Hungerjahr kam, die ihm gebar Asnath, die Tochter Potipheras, des Priesters von On.',
        51: 'Und Joseph nannte den Namen des Erstgeborenen Menascheh; denn Gott, sprach er, ließ mich all mein Mühsal und das ganze Haus meines Vaters vergessen.',
        52: 'Und den Namen des zweiten nannte er Ephraim; denn Gott hat mich im Land meines Elends fruchtbar gemacht.',
        53: 'Und die sieben Jahre des Überflusses, der im Lande Ägypten war, waren vollendet.',
        54: 'Und es fingen die sieben Hungerjahre an zu kommen, wie Joseph gesprochen, und Hunger war in allen Ländern, aber im ganzen Lande Ägypten war Brot.',
        55: 'Und ganz Ägyptenland litt Hunger und das Volk schrie zu Pharao um Brot. Pharao sprach aber zu ganz Ägypten: Gehet zu Joseph; was er euch sagt, das tut.',
        56: 'Und die Hungersnot war über das ganze Land; und Joseph öffnete alles, wo etwas war, und verkaufte Getreide an Ägypten, und die Hungersnot wurde stark im Lande Ägypten.',
        57: 'Und alle Länder kamen nach Ägypten zu Joseph, um Getreide zu kaufen, weil auf der ganzen Erde die Hungersnot stark war.',
    },
    42: {
        1: 'Und Jakob sah, daß in Ägypten Getreide war, und Jakob sprach zu seinen Söhnen: Was sehet ihr einander an?',
        2: 'Und er sprach: Siehe, ich habe gehört, daß in Ägypten Getreide ist. Gehet dort hinab und kaufet Getreide für uns von dort, auf daß wir leben und nicht sterben.',
        3: 'Und die zehn Brüder Josephs gingen hinab, um aus Ägypten Getreide zu kaufen.',
        4: 'Aber Benjamin, Josephs Bruder, sandte Jakob nicht mit seinen Brüdern; denn, sagte er, es möchte ihm ein Unfall begegnen.',
        5: 'Und die Söhne Israels kamen, um Getreide zu kaufen, inmitten der Kommenden; denn die Hungersnot war im Lande Kanaan.',
        6: 'Und Joseph war der Gewalthaber über das Land, er selbst verkaufte das Getreide an alles Volk des Landes. Und die Brüder Josephs kamen und verbeugten sich vor ihm mit dem Antlitz zur Erde.',
        7: 'Und Joseph sah seine Brüder, und er erkannte sie, und stellte sich fremd gegen sie, und redete sie hart an und sprach zu ihnen: Woher kommet ihr? Und sie sprachen: Aus dem Lande Kanaan, um Speise zu kaufen.',
        8: 'Und Joseph erkannte seine Brüder, sie aber erkannten ihn nicht.',
        9: 'Und Joseph gedachte der Träume, die er von ihnen geträumt hatte und sprach zu ihnen: Kundschafter seid ihr; um die Blöße des Landes zu sehen seid ihr gekommen.',
        10: 'Sie aber sprachen zu ihm: Nein, mein Herr, sondern deine Knechte sind gekommen, Speise zu kaufen.',
        11: 'Wir alle sind Söhne eines Mannes; wir sind redlich. Deine Knechte sind keine Kundschafter.',
        12: 'Und er sprach zu ihnen: Nein, ihr seid gekommen, die Blöße des Landes zu sehen.',
        13: 'Sie aber sprachen: Wir, deine Knechte, sind zwölf Brüder, Söhne eines Mannes im Lande Kanaan, und siehe, der kleine ist diesen Tag mit unserm Vater, und einer ist nicht mehr.',
        14: 'Und Joseph sprach zu ihnen: Es ist, wie ich zu euch geredet und gesagt: Ihr seid Kundschafter.',
        15: 'Daran sollt ihr geprüft werden; beim Leben Pharaos, ihr sollt nicht von dannen ausgehen, es komme denn euer kleiner Bruder hierher.',
        16: 'Sendet einen von euch, daß er euern Bruder hole; ihr aber seid gebunden, daß eure Worte geprüft werden, ob Wahrheit bei euch ist; und wo nicht, so seid ihr beim Leben Pharaos Kundschafter.',
        17: 'Und er tat sie beisammen im Gewahrsam drei Tage.',
        18: 'Und am dritten Tage sprach Joseph zu ihnen: So tut, auf daß ihr lebet. Ich fürchte Gott.',
        19: 'Wenn ihr redlich seid, so werde ein Bruder von euch gebunden im Hause eures Gewahrsams, ihr aber gehet und bringt Getreide für den Hunger eurer Häuser.',
        20: 'Euren jüngsten Bruder aber bringt ihr zu mir, auf daß euren Worten geglaubt werde, und ihr nicht sterbet. Und sie taten so.',
        21: 'Und sie sprachen einer zum anderen: Fürwahr, das haben wir an unsrem Bruder verschuldet; wir sahen ihn in der Bedrängnis seiner Seele, wie er zu uns flehte, und wir hörten nicht. Deshalb kommt diese Bedrängnis über uns.',
        22: 'Und Ruben antwortete ihnen und sprach: Habe ich nicht zu euch gesprochen und gesagt: Sündiget nicht an dem Kinde; aber ihr hörtet nicht. Und siehe, es wird auch sein Blut von uns gefordert.',
        23: 'Und sie wußten nicht, daß Joseph es hörte; denn ein Dolmetscher war zwischen ihnen.',
        24: 'Er wandte sich aber herum von ihnen und weinte; und er kehrte zu ihnen zurück und redete mit ihnen. Und er nahm Simeon aus ihnen und band ihn vor ihren Augen.',
        25: 'Und Joseph gebot und sie füllten ihre Gefäße mit Getreide und gaben ihr Silber einem jeden Mann in seinen Sack zurück und gaben ihnen Zehrung auf den Weg; und man tat ihnen also.',
        26: 'Und sie hoben ihr Getreide auf ihre Esel und gingen von dannen.',
        27: 'Und es öffnete einer seinen Sack, um seinem Esel Futter zu geben in dem Nachtlager; und sah sein Silber und siehe es war in der Öffnung seines Mantelsackes.',
        28: 'Und er sprach zu seinen Brüdern: Mein Silber ist zurückgegeben, und siehe es ist auch in meinem Mantelsack. Und es ging ihnen das Herz aus, und erzitternd sprachen sie zueinander: Warum hat uns Gott das getan?',
        29: 'Und sie kamen zu Jakob, ihrem Vater, ins Land Kanaan und sagten ihm alles an, was ihnen begegnet war, und sprachen:',
        30: 'Der Mann, der Herr des Landes, redete uns hart an und gab uns für Kundschafter des Landes aus.',
        31: 'Wir aber sagten zu ihm: Wir sind redlich, wir sind keine Kundschafter.',
        32: 'Zwölf Brüder sind wir, Söhne unseres Vaters, einer ist nicht mehr und der Kleine ist heute bei unserem Vater im Lande Kanaan.',
        33: 'Und der Mann, der Herr des Landes, sprach zu uns: Daran will ich wissen, daß ihr redlich seid: Lasset einen von euch Brüdern bei mir bleiben; und nehmet für den Hunger eurer Häuser und gehet.',
        34: 'Und bringet euren kleinen Bruder zu mir, auf daß ich wisse, daß ihr keine Kundschafter seid, daß ihr redlich seid. Euren Bruder gebe ich euch, und ihr dürft im Lande handeln.',
        35: 'Und es geschah, da sie ihre Säcke leerten und siehe, das Bündelchen mit eines jeden Mannes Silber war in seinem Sacke; und sie sahen die Bündelchen ihres Silbers, sie und ihr Vater und sie fürchteten sich.',
        36: 'Und Jakob, ihr Vater, sprach zu ihnen: Ihr machet mich kinderlos. Joseph ist nicht da und Simeon ist nicht da und Benjamin wollet ihr nehmen. Dies alles kommt über mich.',
        37: 'Und Ruben sprach zu seinem Vater und sagte: Meine zwei Söhne sollst du töten, wenn ich ihn nicht zu dir herbringe; gib ihn auf meine Hand und ich bringe ihn dir zurück.',
        38: 'Er aber sprach: Mein Sohn soll nicht mit euch hinabgehen; denn sein Bruder ist tot, und er allein ist mir geblieben; und begegnet ihm ein Unfall auf dem Wege, auf dem ihr gehet, so bringet ihr mein Greisenhaar mit Gram in die Gruft hinab.',
    },
    43: {
        1: 'Und die Hungersnot war schwer im Lande.',
        2: 'Und es geschah, als sie das Getreide, das sie aus Ägypten gebracht, aufgezehrt hatten, da sprach ihr Vater zu ihnen: Gehet zurück und kaufet uns ein wenig zu essen.',
        3: 'Und Judah sprach zu ihm und sagte: Der Mann hat uns höchlich bezeugt und gesagt: Ihr sollt mein Angesicht nicht sehen, wofern nicht euer Bruder mit euch ist.',
        4: 'Ist es nun, daß du unseren Bruder mit uns sendest, so wollen wir hinabgehen und dir Speise kaufen.',
        5: 'Sendest du ihn aber nicht, so gehen wir nicht hinab; denn der Mann hat uns gesagt: Ihr sollt mein Angesicht nicht sehen, es sei den euer Bruder mit euch.',
        6: 'Und Israel sprach: Warum habt ihr so übel an mir getan, daß ihr dem Manne ansagtet, ihr hättet noch einen Bruder?',
        7: 'Und sie sprachen: Der Mann hat uns über uns und unsre Geburt gefragt und gesagt: Lebt euer Vater noch? Habt ihr einen Bruder? Und wir sagten ihm an, gemäß diesen Worten. Konnten wir irgendwie wissen, daß er sagen würde: Bringet euren Bruder herab?',
        8: 'Und Judah sprach zu Israel, seinem Vater: Sende den Jungen mit mir, und wir machen uns auf und gehen, daß wir leben und nicht sterben, beides, wir und du und unsre Kindlein.',
        9: 'Ich verbürge mich für ihn, von meiner Hand sollst du ihn fordern. Wenn ich ihn nicht zu dir herbringe und dir ihn vor das Angesicht stelle, so will ich alle Tage an dir gesündigt haben.',
        10: 'Denn hätten wir nicht gezaudert, schon diese zweimal wären wir zurückgekehrt.',
        11: 'Und Israel, ihr Vater, sprach zu ihnen: Wenn dem nun so ist, so tut es, nehmet von dem Gepriesenen des Landes in eure Gefäße, und bringt dem Manne ein Geschenk hinab, ein wenig Balsam und ein wenig Honig und Harz und Stakte, Terebinthennüsse und Mandeln.',
        12: 'Und an Silber nehmet das Doppelte in eure Hand, und das Silber, das in die Öffnung eurer Mantelsäcke zurückgegeben wurde, bringt zurück in eurer Hand, vielleicht ist es ein Versehen.',
        13: 'Und euren Bruder nehmet, und macht euch auf und kehrt zu dem Manne zurück.',
        14: 'Und Gott Schaddai gebe euch Erbarmungen vor dem Manne, daß er euch entlasse euern andern Bruder und Benjamin; und ich, sei ich denn kinderlos, wie ich kinderlos sein soll!',
        15: 'Und die Männer nahmen dieses Geschenk und das Doppelte des Silbers nahmen sie in ihre Hand, und Benjamin, und sie machten sich auf und gingen hinab nach Ägypten und standen vor Joseph.',
        16: 'Und Joseph sah Benjamin mit ihnen und sprach zu dem, der über sein Haus war: Bringe die Männer herein ins Haus und schlachte und bereite; denn die Männer sollen mit mir essen am Mittag.',
        17: 'Und der Mann tat, wie Joseph sagte; und der Mann brachte die Männer herein in Josephs Haus.',
        18: 'Die Männer aber fürchteten sich, daß sie in Josephs Haus hereingebracht wurden und sprachen: Wegen des Silbers, das im Anbeginn wieder in unsre Mantelsäcke zurückkam, werden wir hereingebracht, um es auf uns zu wälzen und über uns herzufallen und uns zu Knechten zu nehmen und unsere Esel.',
        19: 'Und sie traten herzu zu dem Manne, der über Josephs Haus war und redeten zu ihm am Eingang des Hauses;',
        20: 'Und sprachen: Bitte, mein Herr, wir sind im Anbeginn herabgekommen, um Speise zu kaufen.',
        21: 'Und es geschah, wie wir in das Nachtlager kamen und unsre Mantelsäcke öffneten, da siehe, da war eines jeden Mannes Silber in der Öffnung seines Mantelsackes, unser Silber nach seinem Gewicht, und wir bringen es hier in unserer Hand zurück.',
        22: 'Und anderes Silber brachten wir in unsrer Hand herab, um Speise zu kaufen. Wir wissen nicht, wer unser Silber in unsre Mantelsäcke gelegt hat.',
        23: 'Und er sprach: Friede sei mit euch! Fürchtet euch nicht: Euer Gott und der Gott eures Vaters hat euch etwas Verborgenes in eure Mantelsäcke gegeben. Euer Silber ist mir zugekommen; und er brachte Simeon zu ihnen heraus.',
        24: 'Und der Mann brachte die Männer herein in Josephs Haus, und gab Wasser und sie wuschen ihre Füße, und ihren Eseln gab er Futter.',
        25: 'Und sie machten das Geschenk bereit bis Joseph am Mittag käme, denn sie hatten gehört, daß sie das Brot da essen sollten.',
        26: 'Und Joseph kam nach Hause und sie brachten ihm das Geschenk, das in ihrer Hand war, herein ins Haus und sie beugten sich vor ihm nieder zur Erde.',
        27: 'Und er fragte nach ihrem Frieden und sprach: Und hat Frieden euer alter Vater, von dem ihr gesagt? Lebt er noch?',
        28: 'Und sie sagten: Dein Knecht, unser Vater, hat Frieden. Er lebt noch. Und sie verneigten sich und beugten sich nieder.',
        29: 'Und er hob seine Augen auf und sah Benjamin, seinen Bruder, den Sohn seiner Mutter, und sprach: Ist dies euer kleiner Bruder, von dem ihr mir gesprochen habt? Und er sprach: Gott sei dir gnädig, mein Sohn.',
        30: 'Und Joseph eilte; denn sein Erbarmen erregte sich für seinen Bruder, und er suchte, wo er weinte; und er ging in die Kammer hinein und weinte daselbst.',
        31: 'Und er wusch sein Gesicht und kam heraus, und hielt an sich und sprach: Setzet Brot auf.',
        32: 'Und sie legten ihm besonders vor, und ihnen besonders, und den Ägyptern, die mit ihm aßen, besonders; denn die Ägypter können nicht Brot essen mit den Hebräern, weil dies den Ägyptern ein Greuel ist.',
        33: 'Und sie saßen vor ihm, der Erstgeborene nach seiner Erstgeburt und der Jüngste nach seiner Jugend; und die Männer verwunderten sich, jeder Mann zu seinem Genossen.',
        34: 'Und man hob Gerichte von seinem Angesichte weg vor sie hin, aber Benjamins Gericht war fünfmal mehr denn das Gericht von ihnen allen. Und sie tranken und wurden trunken mit ihm.',
    },
    44: {
        1: 'Und er gebot dem, der über sein Haus war, und sprach: Fülle die Mantelsäcke der Männer mit Speise, so viel sie tragen können, und eines jeden Mannes Silber lege in die Öffnung seines Mantelsackes.',
        2: 'Und meinen Kelch, den silbernen Kelch, lege in die Öffnung des Mantelsackes des Kleinsten und das Geld für sein Getreide; und er tat nach Josephs Wort, das er geredet.',
        3: 'Am Morgen ward es Licht, und die Männer wurden entsendet, sie und ihre Esel.',
        4: 'Sie gingen aus von der Stadt und waren noch nicht ferne, da sprach Joseph zu dem, der über sein Haus war: Mache dich auf, setze den Männern nach, und wenn du sie erreichst, da sprich zu ihnen: Warum habt ihr Gutes mit Bösem vergolten?',
        5: 'Ist es nicht der, aus dem mein Herr trinkt, und aus dem er voraussagt? Ihr habt übel getan an dem, was ihr tatet.',
        6: 'Und er erreichte sie und redete zu ihnen diese Worte.',
        7: 'Und sie sprachen zu ihm: Warum redet mein Herr solche Worte? Fern sei von deinen Knechten, nach diesem Worte zu tun.',
        8: 'Siehe, das Silber, das wir in der Öffnung unsrer Mantelsäcke gefunden, haben wir dir aus dem Lande Kanaan zurückgebracht. Und wie sollten wir aus dem Hause deines Herrn Silber oder Gold stehlen?',
        9: 'Bei welchem von deinen Knechten es gefunden wird, der soll sterben; und auch wir wollen meinem Herrn zu Knechten sein.',
        10: 'Und er sprach: Es sei nun auch so nach euren Worten! Der, bei dem er gefunden wird, der soll mein Knecht sein, ihr aber sollt ungestraft sein.',
        11: 'Und sie eilten und ließen jeder Mann seinen Mantelsack auf die Erde herab und öffneten jeder Mann seinen Mantelsack.',
        12: 'Und er forschte nach, fing bei dem Größten an und hörte beim Kleinsten auf; und der Kelch fand sich in Benjamins Mantelsack.',
        13: 'Und sie zerrissen ihre Gewänder, und jeder Mann belud seinen Esel und sie kehrten nach der Stadt zurück.',
        14: 'Und Judah und seine Brüder kamen in Josephs Haus und er war noch da, und sie fielen vor ihm zur Erde.',
        15: 'Und Joseph sprach zu ihnen: Was ist das für eine Tat, die ihr getan? wußtet ihr nicht, daß ein Mann, wie ich, vorhersagen kann?',
        16: 'Und Judah sprach: Was sollen wir sagen zu meinem Herrn, was sollen wir reden und wie uns rechtfertigen? Gott hat gefunden die Missetat deiner Knechte. Siehe, wir sind Knechte meinem Herrn, sowohl wir als er, in dessen Hand der Kelch gefunden worden.',
        17: 'Und er sprach: Ferne sei von mir, solches zu tun. Der Mann, in dessen Hand der Kelch gefunden worden, der soll mein Knecht sein. Und ihr, gehet ihr im Frieden hinauf zu eurem Vater!',
        18: 'Und Judah trat her zu ihm und sprach: Bitte, mein Herr, laß doch deinen Knecht ein Wort reden in den Ohren meines Herrn, und es entbrenne nicht dein Zorn gegen deinen Knecht; denn du bist wie Pharao.',
        19: 'Mein Herr fragte seine Knechte und sprach: Habt ihr einen Vater oder einen Bruder?',
        20: 'Und wir sagten zu meinem Herrn: Wir haben einen alten Vater und ein Kind seines Alters, den Kleinsten, und sein Bruder ist tot, und er ist allein übrig geblieben von seiner Mutter, und sein Vater liebt ihn.',
        21: 'Und du sprachst zu deinen Knechten: Bringet ihn herab zu mir, daß ich mein Auge auf ihn richte.',
        22: 'Und wir sprachen zu meinem Herrn: Der Junge kann seinen Vater nicht verlassen; und verläßt er seinen Vater, so stirbt dieser.',
        23: 'Und du sprachst zu deinen Knechten: Wenn euer kleiner Bruder nicht mit euch herabkommt, so sollt ihr nicht wieder mein Angesicht sehen.',
        24: 'Und es geschah, daß wir hinaufgingen zu deinem Knecht, meinem Vater, und sagten ihm an die Worte meines Herrn.',
        25: 'Und unser Vater sprach: Kehret zurück, kaufet uns ein wenig zu essen.',
        26: 'Wir aber sagten: Wir können nicht hinabgehen; wenn unser kleiner Bruder mit uns ist, dann wollen wir hinabgehen; denn wir können das Angesicht des Mannes nicht sehen, wenn unser kleiner Bruder nicht mit uns ist.',
        27: 'Und es sprach dein Knecht, mein Vater, zu uns: Ihr wisset, daß mein Weib, mir zwei geboren hat.',
        28: 'Und der eine ist von mir hinausgegangen, und ich sprach: Gewiß, er ist zerfleischt, und ich hab ihn nicht gesehen bisher.',
        29: 'Und nehmet ihr auch diesen von meinem Angesicht, und begegnet ihm ein Unfall, dann bringet ihr mein Greisenhaar durch Übel in die Gruft hinab.',
        30: 'Und nun, wenn ich zu deinem Knecht, meinem Vater, komme, und der Junge ist nicht mit uns - und seine Seele ist mit dessen Seele verbunden -',
        31: 'So wird es geschehen, wenn er sieht, daß der Junge nicht da ist, daß er stirbt. Und es werden deine Knechte das Greisenhaar deines Knechtes, unseres Vaters, mit Gram in die Gruft bringen.',
        32: 'Denn dein Knecht hat sich verbürgt für den Jungen bei meinem Vater und gesagt: Wenn ich ihn nicht zu dir hereinbringe, so will ich alle Tage gegen meinen Vater gesündigt haben.',
        33: 'Und nun laß deinen Knecht anstatt des Jungen als Knecht meinem Herrn bleiben, und den Jungen mit seinen Brüdern hinaufgehen.',
        34: 'Denn wie sollte ich zu meinem Vater hinaufgehen, ohne daß der Junge bei mir ist? Ich müßte nur das Böse sehen, das meinen Vater trifft.',
    },
    45: {
        1: 'Und Joseph vermochte nicht an sich zu halten vor allen, die bei ihm standen und rief: Lasset jeden Mann hinausgehen von mir! Und es stand kein Mann bei ihm, als Joseph sich seinen Brüdern zu erkennen gab.',
        2: 'Und seine Stimme brach in Weinen aus, und es hörten es die Ägypter und das Haus Pharaos hörte es.',
        3: 'Und Joseph sprach zu seinen Brüdern: Ich bin Joseph. Lebt mein Vater noch? Aber seine Brüder vermochten nicht ihm zu antworten; denn sie waren bestürzt vor seinem Angesicht.',
        4: 'Und Joseph sprach zu seinen Brüdern: Tretet doch her zu mir; und sie traten herzu. Und er sprach: Ich bin Joseph, euer Bruder, ich, den ihr nach Ägypten verkauft habt.',
        5: 'Nun aber laßt es euch nicht schmerzen, und laßt es nicht entbrennen in euren Augen, daß ihr mich hierher verkauft habt; denn um am Leben zu erhalten, hat mich Gott vor euch hergesandt.',
        6: 'Denn diese zwei Jahre war Hungersnot inmitten des Landes; und noch sind es fünf Jahre, in denen kein Pflügen und Ernten sein wird.',
        7: 'Und Gott hat mich vor euch hergesandt, um euch seinen Überrest zu setzen auf Erden, und euch das Leben zu erhalten, zu einer großen Errettung.',
        8: 'Und nun seid nicht ihr es, die mich hierher gesandt, sondern Gott. Und Er hat mich dem Pharao zum Vater, und seinem ganzen Hause zum Herrn, und zum Herrscher im ganzen Land Ägypten gesetzt.',
        9: 'Eilet und gehet hinauf zu meinem Vater und saget ihm: Also spricht dein Sohn Joseph: Gott hat mich zum Herrn über ganz Ägypten gesetzt; komm herab zu mir, bleib nicht stehen!',
        10: 'Und du sollst im Lande Gosen wohnen und mir nahe sein, du und deine Söhne und die Söhne deiner Söhne, und dein Kleinvieh und deine Rinder, und alles, was dein ist.',
        11: 'Und ich will dich da versorgen; denn noch sind fünf Hungerjahre, auf daß du nicht verkommest, du und dein Haus und alles, was dein ist.',
        12: 'Und siehe, eure Augen sehen es, und die Augen meines Bruders Benjamin, daß es mein Mund ist, der zu euch redet.',
        13: 'Und saget an meinem Vater alle meine Herrlichkeit in Ägypten und alles, was ihr gesehen habt, und eilet und bringt meinen Vater hier herab.',
        14: 'Und er fiel seinem Bruder Benjamin um den Hals und weinte, und Benjamin weinte an seinem Hals.',
        15: 'Und er küßte alle seine Brüder und weinte über ihnen, und nachher redeten seine Brüder mit ihm.',
        16: 'Und ihre Stimme ward gehört im Hause Pharaos, und man sagte: Josephs Brüder sind gekommen. Und es war gut in den Augen Pharaos und in den Augen seiner Knechte.',
        17: 'Und Pharao sprach zu Joseph: Sag deinen Brüdern: Das tut, ladet euren Lasttieren auf und gehet, kommt nach dem Lande Kanaan.',
        18: 'Und nehmet euren Vater und eure Häuser, und kommet zu mir, und ich will euch das Gute des Landes Ägypten geben, und ihr sollt essen das Fett des Landes.',
        19: 'Und du sollst ihnen gebieten: Dies tut, nehmet euch vom Lande Ägypten Wagen für eure Kindlein und für eure Weiber, und bringet euren Vater und kommet.',
        20: 'Und lasset eure Augen euer Geräte nicht schonen; denn das Gut vom ganzen Lande Ägypten ist euer.',
        21: 'Und die Söhne Israels taten so, und Joseph gab ihnen Wagen nach Pharaos Ausspruch, und gab ihnen Zehrung auf den Weg.',
        22: 'Ihnen allen gab er, einem jeden Mann, Gewänder zum Wechseln; dem Benjamin aber gab er dreihundert Silberlinge und fünf Gewänder zum Wechseln.',
        23: 'Seinem Vater aber schickte er wie folgt: Zehn Esel, tragend vom Guten Ägyptens, und zehn Eselinnen, tragend Getreide und Brot und Lebensmittel für seinen Vater auf den Weg.',
        24: 'Und er entsandte seine Brüder und sie gingen, und er sprach zu ihnen: Zanket nicht auf dem Wege.',
        25: 'Sie aber gingen hinauf von Ägypten und kamen ins Land Kanaan zu Jakob, ihrem Vater;',
        26: 'Und sie sagten es ihm an und sprachen: Joseph lebt noch und er herrscht im ganzen Land Ägypten; aber sein Herz erstarrte, denn er glaubte ihnen nicht.',
        27: 'Und sie redeten zu ihm alle Worte Josephs, die er zu ihnen geredet hatte. Und er sah die Wagen, die Joseph sandte, um ihn hinzufahren, und der Geist ihres Vaters Jakob lebte auf.',
        28: 'Und Israel sprach: Das ist viel! Mein Sohn Joseph lebt noch. Ich will gehen und ihn sehen, bevor ich sterbe.',
    },
    46: {
        1: 'Und Israel brach auf und alles, was er hatte, und kam nach Beerscheba, und opferte dem Gotte seines Vaters Isaak Opfer.',
        2: 'Und Gott sprach zu Israel in Gesichten der Nacht, und Er sprach: Jakob, Jakob! Und er sprach: Hier bin ich.',
        3: 'Und Er sprach: Ich bin der Gott, der Gott deines Vaters. Fürchte dich nicht, nach Ägypten hinabzugehen; denn ich will dich dort zu einer großen Völkerschaft setzen.',
        4: 'Ich werde mit dir hinabgehen nach Ägypten und dich auch heraufkommen lassen, und Joseph wird seine Hand auf deine Augen legen.',
        5: 'Und Jakob machte sich auf von Beerscheba, und die Söhne Israels hoben ihren Vater Jakob, ihre Kindlein und ihre Weiber auf in die Wagen, die Pharao gesandt, ihn zu fahren.',
        6: 'Und sie nahmen ihre Viehherden und ihre Habe, die sie im Lande Kanaan gewonnen hatten und kamen nach Ägypten, Jakob und all sein Same mit ihm.',
        7: 'Seine Söhne und seiner Söhne Söhne mit ihm, seine Töchter und seiner Söhne Töchter, und all seinen Samen brachte er mit sich nach Ägypten.',
        8: 'Und dies sind die Namen der Söhne Israels, die nach Ägypten kamen, Jakobs und seiner Söhne: der Erstgeborene Jakobs: Ruben.',
        9: 'Und die Söhne Rubens waren: Chanoch und Phallu und Chezron und Karmi.',
        10: 'Und die Söhne Simeons: Jemuel und Jamin und Ohad und Jachin und Zochar und Schaul, der Sohn einer Kanaaniterin.',
        11: 'Und die Söhne Levis: Gerschon und Kohath und Merari.',
        12: 'Und die Söhne Judahs: Er und Onan und Schelah und Pherez und Serach; Er und Onan aber waren gestorben im Lande Kanaan; und die Söhne des Pherez waren Chezron und Chamul.',
        13: 'Und die Söhne Isaschars: Thola und Phuvah und Job und Schimron.',
        14: 'Und die Söhne Sebulons: Sered und Elon und Jachleel.',
        15: 'Dies sind die Söhne der Leah, die sie dem Jakob in Padan Aram gebar, und Dinah, seine Tochter. Alle Seelen seiner Söhne und seiner Töchter waren dreiundreißig.',
        16: 'Und die Söhne Gads: Ziphjon und Chaggi, Schuni und Ezbon, Eri und Arodi und Areli.',
        17: 'Und die Söhne Aschers: Jimnah und Jischvah und Jischvi und Berijah und Serach, ihre Schwester, und die Söhne Berijahs: Cheber und Malchiel.',
        18: 'Dies sind die Söhne Silpahs, die Laban seiner Tochter Leah gab. Und sie gebar diese dem Jakob, sechszehn Seelen.',
        19: 'Die Söhne von Rachel, Jakobs Weib, waren Joseph und Benjamin.',
        20: 'Und dem Joseph wurden geboren in Ägyptenland, die Asenath, die Tochter Potipheras, des Priesters von Ohn, ihm gebar, Menascheh und Ephraim.',
        21: 'Und die Söhne Benjamins waren: Bela und Becher und Aschbel, Gera und Naaman, Echi und Rosch, Muppim und Chuppim und Arde.',
        22: 'Dies sind die Söhne Rachels, die dem Jakob geboren wurden, alle Seelen, vierzehn.',
        23: 'Und die Söhne Dans: Chuschim.',
        24: 'Und die Söhne Naphthalis waren: Jachzeel und Guni und Jezer und Schillem.',
        25: 'Dies sind die Söhne Bilhahs, die Laban seiner Tochter Rachel gab. Und sie gebar sie dem Jakob, alle Seelen, sieben.',
        26: 'Alle Seelen, die mit Jakob nach Ägypten kamen, die aus seinen Hüften hervorgingen, außer den Weibern der Söhne Jakobs, waren es alle Seelen, sechsundsechzig.',
        27: 'Und die Söhne Josephs, die ihm in Ägypten geboren wurden, waren zwei Seelen. Alle Seelen vom Hause Jakobs, die nach Ägypten kamen, waren siebzig.',
        28: 'Und den Judah sandte er vor sich hin an Joseph, vor ihm her zu weisen nach Goschen; und sie kamen nach dem Lande Goschen.',
        29: 'Und Joseph spannte seinen Streitwagen an und ging hinauf, seinem Vater Israel entgegen nach Goschen. Und als er sich ihm zeigte, da fiel er ihm um den Hals und weinte lange an seinem Hals.',
        30: 'Und Israel sprach zu Joseph: Nunmehr will ich sterben, nachdem ich dein Angesicht gesehen, daß du noch lebst.',
        31: 'Und Joseph sprach zu seinen Brüdern und zu dem Haus seines Vaters: Ich will hinaufgehen und Pharao ansagen, und ich will zu ihm sagen: Meine Brüder und das Haus meines Vaters, die im Lande Kanaan waren, sind zu mir gekommen.',
        32: 'Und die Männer sind Hirten des Kleinviehs; denn sie sind Männer der Viehherden und haben ihr Kleinvieh und ihre Rinder und alles, was sie haben, hergebracht.',
        33: 'Und wenn es geschieht, daß Pharao euch ruft und sagt: Was ist euer Tun?',
        34: 'Dann saget: Männer der Viehherden sind deine Knechte gewesen von unsrer Jugend auf und bis jetzt, sowohl wir als unsre Väter; auf daß ihr wohnen möget im Lande Goschen; denn alle, die Kleinvieh weiden, sind den Ägyptern ein Greuel.',
    },
    47: {
        1: 'Und Joseph kam und sagte es Pharao an und sprach: Mein Vater und meine Brüder und ihr Kleinvieh und ihre Rinder und alles, was sie haben, sind aus dem Lande Kanaan gekommen; und siehe, sie sind im Lande Goschen.',
        2: 'Und aus der Zahl seiner Brüder nahm er fünf Männer und stellte sie vor Pharao.',
        3: 'Und Pharao sprach zu seinen Brüdern: Was ist euer Tun? Und sie sprachen zu Pharao: Hirten des Kleinviehs sind deine Knechte, sowohl wir, als auch unsre Väter.',
        4: 'Und sie sprachen zu Pharao: Um uns aufzuhalten im Lande, sind wir gekommen, weil keine Weide ist für das Kleinvieh, das deine Knechte haben; denn die Hungersnot ist schwer im Lande Kanaan; und nun möchten deine Knechte im Lande Gosen wohnen.',
        5: 'Und Pharao sprach zu Joseph und sagte: Dein Vater und deine Brüder sind zu dir gekommen.',
        6: 'Das Land Ägypten, das ist vor dir. Laß deinen Vater und deine Brüder im Besten des Landes wohnen. Sie mögen wohnen im Lande Goschen. Und wenn du weißt, daß tüchtige Männer unter ihnen sind, so setze sie als Oberste über die Viehherden, die ich habe.',
        7: 'Und Joseph brachte Jakob, seinen Vater, und stellte ihn vor Pharao; und Jakob segnete Pharao.',
        8: 'Und Pharao sprach zu Jakob: Wieviel sind die Tage deiner Lebensjahre?',
        9: 'Und Jakob sprach zu Pharao: Die Tage der Jahre meiner Wanderungen sind hundertdreißig Jahre. Wenig und böse waren die Tage meiner Lebensjahre, und reichen nicht an die Tage der Lebensjahre meiner Väter in den Tagen ihrer Wanderungen.',
        10: 'Und Jakob segnete den Pharao, und ging hinaus von Pharao.',
        11: 'Joseph aber ließ seinen Vater und seine Brüder wohnen und gab ihnen Eigentum im Lande Ägypten, im Besten des Landes, im Lande Raamses, wie Pharao geboten hatte.',
        12: 'Und Joseph versorgte seinen Vater und seine Brüder und das ganze Haus seines Vaters mit Brot nach dem Munde der Kindlein.',
        13: 'Und es war kein Brot im ganzen Lande; denn die Hungersnot war sehr schwer, und das Land Ägypten und das Land Kanaan schmachteten vor Hunger.',
        14: 'Und Joseph sammelte alles Silber, das sich im Lande Ägypten und im Lande Kanaan fand, für das Getreide, das sie kauften, und Joseph brachte das Silber herein in das Haus Pharaos.',
        15: 'Und das Silber vom Lande Ägypten und vom Lande Kanaan war ganz aus, da kamen alle Ägypter zu Joseph und sprachen: Gib uns Brot! Warum sollen wir sterben vor dir, weil das Silber zu Ende ist?',
        16: 'Und Joseph sprach: Gebt eure Viehherden, und ich will es euch für eure Viehherden geben, wenn das Silber zu Ende ist!',
        17: 'Und sie brachten ihre Viehherden zu Joseph und Joseph gab ihnen Brot für die Pferde und für die Viehherden von Kleinvieh und für die Viehherden von Rindern und für die Esel, und er versorgte sie in diesem Jahr mit Brot für all ihre Viehherden.',
        18: 'Und dieses Jahr war ganz aus, und sie kamen im zweiten Jahr zu ihm und sprachen zu ihm: Wir wollen es vor dem Herrn nicht verhehlen, daß unser Silber ganz aus ist, und das Besitztum des Viehs unsres Herrn ist, und uns vor dem Herrn nichts bleibt, als unser Leib und unser Boden.',
        19: 'Warum sollten wir vor deinen Augen sterben, so wir, wie unser Boden. Kaufe uns und unseren Boden für das Brot, dann wollen wir und unser Boden dem Pharao Knechte sein, und gib Samen, daß wir leben und nicht sterben und der Boden nicht wüste werde.',
        20: 'Und Joseph kaufte allen Boden Ägyptens für Pharao; denn die Ägypter verkauften jeder Mann sein Feld, weil die Hungersnot stark war über ihnen, und das Land wurde des Pharao.',
        21: 'Und das Volk ließ er hinziehen nach den Städten vom Ende der Grenze Ägyptens und bis zu seinem Ende.',
        22: 'Nur den Boden der Priester kaufte er nicht; denn die Priester hatten von Pharao ihr Bestimmtes, und sie aßen ihr Bestimmtes, das ihnen Pharao gegeben hatte, deshalb verkauften sie ihren Boden nicht.',
        23: 'Und Joseph sprach zu dem Volke: Siehe, ich habe euch und euern Boden heute für Pharao gekauft. Da ist Samen für euch und besäet den Boden.',
        24: 'Und von dem Ertrage sollet ihr den Fünften an Pharao geben, und vier Teile sollen euer sein für den Samen des Feldes und zu eurer Speise und derer, so in euern Häusern sind, und für eure Kindlein zum Essen.',
        25: 'Und sie sprachen: Du hast uns das Leben erhalten. Wir haben Gnade in den Augen des Herrn gefunden; und wir wollen Knechte sein dem Pharao.',
        26: 'Und Joseph setzte dies zur Satzung ein bis auf diesen Tag über den Boden Ägyptens, dem Pharao den Fünften zu geben. Nur der Boden der Priester allein ward nicht des Pharaos.',
        27: 'Und Israel wohnte im Lande Ägypten, im Lande Goschen; und sie hatten dort Eigentum, und waren fruchtbar und mehrten sich sehr.',
        28: 'Und Jakob lebte im Lande Ägypten siebzehn Jahre; und die Tage Jakobs, seiner Lebensjahre waren hundertsiebenundvierzig Jahre.',
        29: 'Und die Tage Israels nahten, daß er sterben sollte, und er rief seinen Sohn Joseph und sprach zu ihm: Wenn ich Gnade gefunden in deinen Augen, so lege doch deine Hand unter meine Hüfte und tue mir die Barmherzigkeit und Wahrheit, daß du mich doch nicht in Ägypten begrabest.',
        30: 'Und laß mich liegen bei meinen Vätern, und trage mich hinauf aus Ägypten und begrabe mich in ihrem Grabe. Und er sprach: Ich will tun nach deinem Worte.',
        31: 'Und er sprach: Schwöre mir! und er schwur ihm. Und Israel verbeugte sich über das Haupt seines Bettes.',
    },
    48: {
        1: 'Und es geschah nach diesen Dingen, daß man Joseph sagte: Siehe, dein Vater ist krank. Und er nahm seine zwei Söhne Menascheh und Ephraim mit sich.',
        2: 'Und man sagte dem Jakob an und sprach: Siehe, dein Sohn Joseph kommt zu dir. Und Israel machte sich stark und setzte sich im Bette.',
        3: 'Und Jakob sprach zu Joseph: Der Gott Schaddai erschien mir in Lus im Lande Kanaan und segnete mich;',
        4: 'Und Er sprach zu mir: Siehe, Ich mache dich fruchtbar und mehre dich und mache dich zu einem Haufen von Völkern, und gebe dieses Land deinem Samen nach dir zu ewigem Eigentum.',
        5: 'Und nun, deine zwei Söhne, die dir im Lande Ägypten geboren wurden, bis ich zu dir kam nach Ägypten, sind mein. Ephraim und Menascheh, wie Ruben und Simeon sollen sie mir sein.',
        6: 'Aber deine Erzeugten, die du nach ihnen zeugst, die sollen dein sein. Nach dem Namen ihrer Brüder sollen sie genannt werden in ihrem Erbteil.',
        7: 'Und ich, als ich aus Padan kam, starb mir Rachel im Lande Kanaan auf dem Wege, da noch eine Strecke Landes war, bis man nach Ephratah kommt, und ich begrub sie daselbst im Wege Ephrath, das ist Bethlehem.',
        8: 'Und Israel sah die Söhne Josephs und sprach: Wer sind diese?',
        9: 'Und Joseph sprach zu seinem Vater: Meine Söhne sind es, die mir Gott hier gegeben hat. Und er sprach: Bring sie mir doch her, daß ich sie segne.',
        10: 'Und Israels Augen waren schwer vor Alter, so daß er nicht sehen konnte, und er ließ sie herzutreten zu ihm, und er küßte und umarmte sie.',
        11: 'Und Israel sprach zu Joseph: Ich meinte nicht, dein Angesicht zu sehen, und siehe, Gott ließ mich auch deinen Samen sehen.',
        12: 'Und Joseph ließ sie herauskommen von seinen Knien und verbeugte sich mit dem Antlitz zur Erde.',
        13: 'Und Joseph nahm sie beide, Ephraim mit seiner Rechten zur Linken Israels, und Menascheh mit seiner Linken zur Rechten Israels, und ließ sie zu ihm herzutreten.',
        14: 'Und Israel streckte seine Rechte aus und legte sie auf das Haupt Ephraims, und der war der Jüngere, und seine Linke auf das Haupt Menaschehs, indem er seine Hände kreuzte, denn Menascheh war der Erstgeborene.',
        15: 'Und er segnete Joseph und sprach: Der Gott, vor Dem meine Väter wandelten, Abraham und Isaak, der Gott, Der mich weidete, seit ich bin, bis auf diesen Tag;',
        16: 'Der Engel, Der mich erlöset hat von allem Übel, segne die Jungen und mein Name werde in ihnen genannt, und der Name meiner Väter Abraham und Isaak, und sie sollen zunehmen zu einer Menge inmitten des Landes.',
        17: 'Und Joseph sah, daß sein Vater seine rechte Hand auf Ephraims Haupt legte, und es war böse in seinen Augen, und er hielt die Hand seines Vaters, um sie vom Haupte Ephraims wegzunehmen auf Menaschehs Haupt.',
        18: 'Und Joseph sprach zu seinem Vater: Nicht also, mein Vater, denn dieser ist der Erstgeborene. Lege deine Rechte auf sein Haupt.',
        19: 'Sein Vater aber weigerte sich und sprach: Ich weiß es, mein Sohn, ich weiß es. Auch er wird zu einem Volke werden, und auch er wird groß werden; und gleichwohl wird sein kleiner Bruder größer werden, denn er; und sein Same wird eine Fülle von Völkerschaften sein.',
        20: 'Und er segnete sie an diesem Tag und sprach: Mit dir soll Israel segnen und sprechen: Gott setze dich wie Ephraim und wie Menascheh; und er setzte Ephraim vor Menascheh.',
        21: 'Und Israel sprach zu Joseph: Siehe, ich sterbe, und Gott wird mit euch sein und euch zurückbringen zum Lande eurer Väter.',
        22: 'Und ich gebe dir einen Anteil über deine Brüder, denn ich aus der Hand der Amoriter mit meinem Schwert und meinem Bogen genommen habe.',
    },
    49: {
        1: 'Und Jakob rief seine Söhne und sprach: Versammelt euch, und ich sage euch an, was euch in späteren Tagen begegnen wird.',
        2: 'Kommet zusammen und höret, ihr Söhne Jakobs, und höret auf Israel, euern Vater.',
        3: 'Ruben, mein Erstgeborener bist du, meine Kraft und der Anfang meiner Vollkraft, hervorragend an Erhabenheit und hervorragend an Stärke!',
        4: 'Leicht wie Wasser sollst du nicht hervorragen; denn du hast deines Vaters Lager bestiegen, da hast du es entweiht. Auf meine Lagerstätte ist er hinaufgestiegen.',
        5: 'Simeon und Levi sind Brüder; Werkzeuge der Gewalttat sind ihre Dolche.',
        6: 'In ihr Geheimnis gehe nicht ein, meine Seele, mit ihrer Versammlung vereine dich nicht, meine Herrlichkeit; denn in ihrem Zorn erwürgten sie einen Mann, und in ihrem Wohlgefallen lähmten sie einen Ochsen.',
        7: 'Verflucht sei ihr Zorn, denn er ist stark und ihr Wüten, denn es ist hart. Ich werde sie verteilen in Jakob und sie zerstreuen in Israel.',
        8: 'Judah bist du; es werden dich lobpreisen deine Brüder; deine Hand soll sein am Nacken deiner Feinde; es werden sich vor dir niederbeugen die Söhne deines Vaters.',
        9: 'Das Junge eines Löwen ist Judah; vom Zerfleischten, mein Sohn, kommst du herauf. Er hat sich gebeugt und sich gelagert, wie der Löwe, wie ein gealterter Löwe! Wer will machen, daß er stehe?',
        10: 'Nicht weggenommen wird von Judah das Zepter, noch der Gesetzgeber von zwischen seinen Füßen, bis daß Schiloh kommt; und ihm wird der Gehorsam der Völker.',
        11: 'Er bindet an den Weinstock sein Eselsfüllen, und an die Edelrebe den Sohn seiner Eselin. Er wäscht im Weine seinen Anzug und im Blut der Weinbeeren seinen Mantel.',
        12: 'Tiefrot sind seine Augen vom Wein, und die Zähne sind weiß von Milch.',
        13: 'Sebulon wird wohnen am Hafen der Meere, an dem Hafen der Schiffe und seine Seite über Sidon.',
        14: 'Isaschar ist ein knochiger Esel, der sich zwischen den Bürden lagert.',
        15: 'Und er sieht die Ruhe, daß sie gut, und das Land, daß es lieblich sei, und neigt seine Schulter zum Lasttragen; und er wird ein zinsbarer Knecht.',
        16: 'Dan wird rechten für sein Volk, als einer der Stämme Israels.',
        17: 'Dan wird eine Schlange am Wege und eine Pfeilschlange auf dem Pfade sein, die das Pferd in die Fersen beißt, so daß sein Reiter Rücklings fällt.',
        18: 'Auf dein Heil hoffe ich, Jehovah!',
        19: 'Gad werden Scharen verwüsten, aber er verwundet die Ferse.',
        20: 'Fett ist das Brot, das von Ascher kommt, und Wonnen des Königs gibt er.',
        21: 'Naphthali ist eine losgelassene Hindin; er gibt zierliche Reden.',
        22: 'Der Sohn einer Fruchtbaren ist Joseph, der Sohn einer Fruchtbaren an der Quelle, einer Tochter, die auf der Mauer einherschreitet.',
        23: 'Es erbittern ihn und schießen und grollen ihm die Meister der Pfeile.',
        24: 'Aber sie wird sitzen in der Tüchtigkeit seines Bogens; und gestärkt werden die Arme seiner Hände von den Händen des Gewaltigen Jakobs. Von dort her ist der Hirte, der Stein Israels.',
        25: 'Von dem Gott deines Vaters, Der dir beistehen und mit Schaddai, Der dich segnen wird mit Segnungen des Himmels von oben, mit Segnungen des Abgrundes, der unten lagert, mit Segnungen der Brüste und des Mutterschoßes.',
        26: 'Die Segnungen deines Vaters werden mächtiger sein, als die Segnungen meiner Erzeuger, bis zum Sehnen der Hügel des Zeitlaufs, sie werden sein auf Josephs Haupt und auf den Scheitel des Nasirs unter seinen Brüdern.',
        27: 'Benjamin ist ein Wolf, der zerfleischt am Morgen, den Raub frißt und am Abend die Beute verteilt.',
        28: 'Das sind alle die zwölf Stämme Israels, und das ist, was ihr Vater zu ihnen redete. Und er segnete sie; jeden Mann gemäß seinem Segen segnete er sie.',
        29: 'Und er gebot ihnen und sprach zu ihnen: Ich werde zu meinem Volke versammelt. Begrabet mich bei meinen Vätern in der Höhle, die im Felde Ephrons, des Chethiters, ist.',
        30: 'In der Höhle, die im Felde Machpelah ist, bei dem Angesichte Mamres, im Lande Kanaan, welches Abraham mit dem Felde von Ephron, dem Chethiter gekauft für ein Grabeigentum.',
        31: 'Dorthin begruben sie Abraham und Sarah, sein Weib; dorthin begruben sie Isaak und Rebekah, sein Weib, und dorthin begrub ich Leah.',
        32: 'Das Feld und die Höhle darin sind ein Ankauf von den Söhnen Cheths.',
        33: 'Und Jakob vollendete seinen Söhnen zu gebieten, und er zog seine Füße zusammen in das Bett und verschied, und ward zu seinen Völkern versammelt.',
    },
    50: {
        1: 'Und es fiel Joseph auf das Angesicht seines Vaters und er weinte über ihm und küßte ihn.',
        2: 'Und Joseph gebot seinen Knechten, den Ärzten, seinen Vater einzubalsamieren, und die Ärzte balsamierten Israel ein.',
        3: 'Und es wurden ihm erfüllt vierzig Tage; denn so werden die Tage der Einbalsamierten erfüllt; und die Ägypter beweinten ihn siebzig Tage.',
        4: 'Und die Tage des Beweinens gingen vorüber, und Joseph redete zu dem Hause Pharaos und sagte: Wenn ich nun Gnade in euern Augen gefunden, so redet doch vor den Ohren Pharaos und saget:',
        5: 'Mein Vater hat mich schwören lassen und gesagt: Siehe, ich sterbe, du aber begrabe mich, dort in meinem Grabe, das ich mir im Lande Kanaan gegraben habe, und nun laß mich hinaufgehen und meinen Vater begraben und zurückkehren.',
        6: 'Und Pharao sprach: Gehe hinauf und begrabe deinen Vater, wie er dich hat schwören lassen.',
        7: 'Und Joseph ging hinauf, seinen Vater zu begraben; und es gingen mit ihm hinauf alle Knechte Pharaos, die Ältesten seines Hauses und alle Ältesten vom Lande Ägypten.',
        8: 'Und das ganze Haus Josephs und seine Brüder und das Haus seines Vaters. Nur ihre Kindlein und ihr Kleinvieh und ihre Rinder ließen sie im Lande Goschen.',
        9: 'Und es gingen auch mit ihm hinauf Streitwagen und auch Reiter, und es war ein sehr großes Lager.',
        10: 'Und sie kamen zur Tenne Atad, die am Übergang des Jordans ist, und sie klagten daselbst eine große und sehr schwere Klage, und Joseph stellte um seinen Vater eine Trauer von sieben Tagen an.',
        11: 'Und der Einwohner des Landes, der Kanaaniter, sah die Trauer auf der Tenne Atad und sie sagten: Das ist eine schwere Trauer der Ägypter; deshalb nannte man den Namen Abel Mizraim, am Übergang des Jordans.',
        12: 'Und seine Söhne taten ihm wie er ihnen geboten hatte.',
        13: 'Und seine Söhne trugen ihn nach dem Lande Kanaan, und begruben ihn in der Höhle des Feldes Machpelah, die Abraham samt dem Felde zu einem Grabeigentum gekauft hatte von dem Chethiter Ephron, Mamre gegenüber.',
        14: 'Und Joseph kehrte zurück nach Ägypten, er und seine Brüder und alle, die mit ihm heraufgezogen, um seinen Vater zu begraben, nachdem er seinen Vater begraben hatte.',
        15: 'Und die Brüder Josephs sahen, daß ihr Vater tot war und sie sprachen: Joseph grollt uns vielleicht und gibt uns zurück all das Böse, das wir ihm angetan haben.',
        16: 'Und sie entboten dem Joseph und sagten: Dein Vater hat vor seinem Tode geboten und gesagt:',
        17: 'So sollt ihr sagen zu Joseph: Verzeihe doch die Übertretung deiner Brüder und ihre Sünde; denn Böses haben sie dir angetan; und nun verzeihe doch die Übertretung der Knechte des Gottes deines Vaters. Und Joseph weinte, als sie zu ihm redeten.',
        18: 'Und seine Brüder gingen auch und fielen vor ihm nieder und sprachen: Siehe, wir sind dir Knechte.',
        19: 'Und Joseph sprach zu ihnen: Fürchtet euch nicht. Bin ich denn an Gottes Statt?',
        20: 'Ihr gedachtet über mir Böses, Gott aber gedachte es zum Guten, um zu tun wie es an diesem Tage ist, daß Er viel Volks am Leben erhalte.',
        21: 'Und nun fürchtet euch nicht: Ich werde euch versorgen, euch und eure Kindlein; und er tröstete sie und redete zu ihrem Herzen.',
        22: 'Und Joseph wohnte in Ägypten, er und das Haus seines Vaters. Und Joseph lebte hundertzehn Jahre.',
        23: 'Und Joseph sah von Ephraim Söhne bis ins dritte Glied, auch die Söhne von Machir, dem Sohne Menaschehs wurden auf Josephs Knien geboren.',
        24: 'Und Joseph sprach zu seinen Brüdern: Ich sterbe, und Gott wird euch gewißlich heimsuchen und euch hinaufbringen aus diesem Lande zum Lande, das Er Abraham, Isaak und Jakob geschworen hat.',
        25: 'Und Joseph ließ die Söhne Israels schwören und sprach: Gewißlich wird Gott euch heimsuchen, und ihr sollt meine Gebeine von da hinaufbringen.',
        26: 'Und Joseph starb in einem Alter von hundertzehn Jahren, und sie balsamierten ihn ein; und er ward in eine Lade gelegt in Ägypten.',
    },
}
